INSERT INTO `destinations` VALUES (1,NULL,'TIBET','tibet','The Roof of the World — Potala Palace, sacred lakes, and Everest’s north face across a high, spiritual plateau.','<p><strong>Tibet — Roof of the World</strong></p>\n<p>Often described as Shangri-La, Tibet is a high, spiritual plateau where Buddhism shapes daily life. Monasteries perch above barley fields, prayer flags flutter over 4,500-meter passes, and pilgrims circle sacred peaks. From Lhasa’s Potala Palace and Jokhang Temple to Yamdrok Lake, Shigatse’s Tashilhunpo, and the north face of Everest, Tibet offers a profound blend of culture and Himalayan grandeur.</p>\n<p><strong>Highlights with Adventure Specialist Travel</strong></p>\n<ul>\n<li>Lhasa cultural core: Potala (UNESCO), Sera and Drepung monasteries, Barkhor pilgrim circuit</li>\n<li>Scenic overland: Yamdrok Tso, Karo La Glacier, Gyantse Kumbum and Shigatse</li>\n<li>Everest Base Camp (Tibet side) and optional Kailash kora for pilgrims</li>\n</ul>\n<p><strong>At a Glance</strong></p>\n<table style=\"width: 100%;\" border=\"1\" cellspacing=\"1\" cellpadding=\"8\">\n<tbody>\n<tr><td><strong>Location</strong></td><td>Southwest China, bordering Xinjiang, Qinghai, Sichuan, Yunnan and — south/west — Myanmar, India, Bhutan, Nepal</td></tr>\n<tr><td><strong>Area</strong></td><td>~1.22 million sq. km</td></tr>\n<tr><td><strong>Average Elevation</strong></td><td>~4,000 meters</td></tr>\n<tr><td><strong>Population</strong></td><td>~3.6 million (Tibetan ~90%)</td></tr>\n<tr><td><strong>Capital</strong></td><td>Lhasa (3,650m)</td></tr>\n</tbody>\n</table>\n<p>&nbsp;</p>\n<p><strong>When to Go</strong> April–June and September–October for clear skies and comfortable days. July–August can be wet in Nepal but often dry on the plateau. Winter is cold, crisp, and uncrowded — ideal for cultural touring with warm layers.</p>\n<p><strong>Travel with Care</strong> Tibet requires permits and guided travel. We arrange all permits, acclimatization, private transport and knowledgeable Tibetan guides, ensuring respectful, safe and well-paced journeys by flight via Kathmandu or overland.</p>\n<p>Choose a <em>Tibet Tour</em> for monasteries and EBC or a <em>Tibet Trek</em> for nomadic trails — or combine both.</p>',NULL,NULL,NULL,'/assets/images/destinations/tibet.jpg',0,'2026-08-23 11:55:00','2026-08-23 11:55:00',1),(2,1,'Tibet Tour','tibet-tour','Curated overland and fly-in tours across the Tibetan Plateau — Lhasa, Shigatse, Gyantse and Everest Base Camp with monasteries, lakes and Himalayan panoramas.','<p><strong>Tibet Tour — Roof of the World</strong></p><p>Our Tibet tours balance spiritual heritage with high-altitude comfort. From the Potala Palace and Jokhang Temple in Lhasa to Yamdrok Lake, Karo La Glacier, and the north face of Everest, every day blends Buddhist culture with vast plateau landscapes. Adventure Specialist Travel handles permits, acclimatization, and expert Tibetan guides so you travel safely and respectfully.</p><p><strong>Highlights</strong></p><ul><li>Lhasa cultural core: Potala, Sera, Drepung and Barkhor circuit</li><li>Scenic overland via Yamdrok Tso and Gyantse Kumbum to Shigatse</li><li>Everest Base Camp (Tibet side) and Tingri panoramas</li><li>Comfortable hotels, private transport, and oxygen-supported acclimatization</li></ul><p><strong>Best Season</strong> April–June and September–October for clear skies. July–August is monsoon in Nepal but often dry on the plateau. Winter offers fewer crowds and crisp light.</p><p><em>Explore our Lhasa and EBC itineraries below and let us tailor your dates, pace, and entry route via Kathmandu or mainland China.</em></p>',NULL,NULL,NULL,'/assets/images/destinations/tibet.jpg',0,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(3,2,'Lasa Tour','lasa-tour','07 NIGHT/08 DAYS TIBET TOUR WITH EBC – GROUP JOINING TOUR DAY 01: KATHMANDU (1300M) - LHASA (3650M) Fly (1hr.) to LHASA over crossing the highest Himalayan ranges of the world. Transfer by…','<p style=\"text-align: center;\"><span style=\"font-size: 18pt;\"><strong>07 NIGHT/08 DAYS TIBET TOUR WITH EBC – GROUP JOINING TOUR</strong></span></p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"><strong>DAY 01: KATHMANDU (1300M) - LHASA (3650M)</strong></p>\n<p style=\"text-align: left;\">Fly (1hr.) to LHASA over crossing the highest Himalayan ranges of the world. Transfer by comfortable vehicle and check-in to your hotel. Remaining of the day will be rest for acclimatization. – Overnight at hotel.</p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"><strong>Day 02: IN LHASA,<br />\n </strong>Breakfast at hotel. In the morning visit Potala enormous, UNESCO world heritage, and the palace of Norbulingka, respectively, winter and summer residences of the Dalai Lama. In the following visit to monastery of Sera. - Overnight at hotel.</p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"><strong>Day 03: IN LHASA,<br />\n </strong>Lhasa Breakfast at hotel. Visit the monastery of Deprung (founded 1416), home of the \"Yellow Sect\" and the temple of Nechung, home of the Oracle of Tibet was that contains rare paintings doesn\'t visible elsewhere. Also visit the historical center of the Barkhor the Jokhang Temple. - Overnight at hotel.</p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"><strong>Day 04: LHASA – GYANTSE (3950 M) – XIGATSE (3900 M/360 KM),<br />\n </strong>Lhasa - Gyantse  After breakfast. Departure for the Tsangpo in Chusul, from where it goes to step Kampa La (4794 m), which offers a splendid view across the azure waters of Lake Yamdrok Tso (4450 m). Arrival in Gyantse (3900 m) once the center of control of caravans heading to Bhutan and Sikkim. Visit of Kumbum stupa, the largest \"Chorten\" existing in Tibet, with its 73 rooms decorated with frescoes by magnifche 27,000 Fgura Buddhist iconography, expression of Newari. The stupa is connected to Palkor Chode Monastery and continue drive to Shigatse (3900 m, 90 km), . When you arrive in Shigatse, visit the great monastery of Tashilumpo, full of priceless treasures, which was founded by the first Dalai Lama in 1447 and was the historic seat of the Panchen Lama. -Overnight at hotel.</p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"><strong>Day 05: XIGATSE – RONGBUCK (5000 M/340 KM),<br />\n </strong>Morning visit  of Tashilumpo, full of priceless treasures, which was founded by the first Dalai Lama in 1447 and was the historic seat of the Panchen Lama. Drive to Rongbuck. Visit Rongbuck monastery. – Overnight at Guest house.</p>\n<p style=\"text-align: left;\"><strong> </strong></p>\n<p style=\"text-align: left;\"><strong>Day 06: RONGBUCK – SHAKYA (4050 M/270 KM),<br />\n </strong>Morning visit EBC and explore the area and drive to Shakya. Visit Shakya monastery.  - Overnight at hotel.</p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"><strong>Day 07: SHAKYA – LHASA (3650 M/430 KM),<br />\n </strong>Drive back to Lhasa. Remaining of the day will be free or personal activities. – Overnight at hotel.</p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"><strong>Day 08: LHASA – KATHMANDU,<br />\n </strong>Drive to airport for final departure.</p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"><strong> GROUP JOINING TOUR:  (MINIMUM 02 PAX)</strong></p>\n<table class=\" alignleft\">\n<tbody>\n<tr>\n<td width=\"145\">\n<p><strong>TOUR COST</strong></p>\n</td>\n<td width=\"330\">\n<p><strong>HOTEL TIBET HERITAGE – BB,</strong></p>\n</td>\n</tr>\n<tr>\n<td width=\"145\">\n<p>PER PERSON</p>\n</td>\n<td width=\"330\">\n<p>US $ 980.00 PER PERSON</p>\n</td>\n</tr>\n</tbody>\n</table>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"><strong>EXTRA COST:</strong></p>\n<p style=\"text-align: left;\">AIR FARE: KTM/LXA/KTM:- US $ 440 - $ 675.00 (on available basis till june),</p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"><strong>NEW TIBET VISA FEE STRUCTURE:</strong></p>\n<table class=\" alignleft\">\n<tbody>\n<tr>\n<td width=\"317\">\n<p><strong>NATIONALS</strong></p>\n</td>\n<td width=\"156\">\n<p><strong>VISA FEES</strong>    </p>\n</td>\n</tr>\n<tr>\n<td width=\"317\">\n<p>US NATIONALS</p>\n</td>\n<td width=\"156\">\n<p>US $ 175.00</p>\n</td>\n</tr>\n<tr>\n<td width=\"317\">\n<p>CANADIANS</p>\n</td>\n<td width=\"156\">\n<p>US $ 155.00</p>\n</td>\n</tr>\n<tr>\n<td width=\"317\">\n<p>ROMANIAN</p>\n</td>\n<td width=\"156\">\n<p>US $ 115.00</p>\n</td>\n</tr>\n<tr>\n<td width=\"317\">\n<p>SERBIAN</p>\n</td>\n<td width=\"156\">\n<p>US $   52.00</p>\n</td>\n</tr>\n<tr>\n<td width=\"317\">\n<p>PAKISTAN,ALBANIA,MALDIVES, BOSNIA &amp; HERZEGOVINA</p>\n</td>\n<td width=\"156\">\n<p>US $   55.00</p>\n</td>\n</tr>\n<tr>\n<td width=\"317\">\n<p>MONTENEGRO</p>\n</td>\n<td width=\"156\">\n<p>US $   95.00</p>\n</td>\n</tr>\n<tr>\n<td width=\"317\">\n<p>OTHER NATIONALS</p>\n</td>\n<td width=\"156\">\n<p>US $   85.00</p>\n</td>\n</tr>\n</tbody>\n</table>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"><strong> </strong></p>\n<p style=\"text-align: left;\"> <strong> ABOVE COST INCLUDES:</strong></p>\n<ul style=\"text-align: left;\">\n	<li>HOTEL ACCOMMODATION IN TWIN SHARING ROOM ON BB BASIS IN THE RESPECTIVE HOTELS IN LHASA, EN-ROUTE BEST AVAILABLE HTLS WILL BE PROVIDED,</li>\n	<li>GOOD &amp; COMFORTABLE JEEP/VAN/COACH WILL BE PROVIDED FOR THE TOUR DEPENDING ON GROUP SIZE,</li>\n	<li>SIGHTSEEING WITH A GOOD ENGLISH SPEAKING TIBETAN GUIDE AS PER ITINERARY,</li>\n	<li>TIBET TRAVEL PERMIT FEE,</li>\n	<li>ENTRANCE FEES TO MONASTERIES &amp; MONUMENTS,</li>\n	<li>AIRPORT/HOTEL/AIRPORT TRANSFERS.</li>\n</ul>\n<p style=\"text-align: left;\"><strong> </strong></p>\n<p style=\"text-align: left;\"><strong> COST DOES NOT INCLUDE:</strong></p>\n<ul style=\"text-align: left;\">\n	<li>AIRPORT TAXES, </li>\n	<li>NEPAL RE-ENTRY VISA FEE, </li>\n	<li>ALL INSURANCE,</li>\n	<li>PHOTOGRAPHY FEES IN MONASTERIES,</li>\n	<li>EXTRA COST DUE TO NATURAL AND POLITICAL CAUSES SUCH AS LANDSLIDES, SNOW, STRIKES, ETC.,</li>\n	<li>ALL EXPENSES OF PERSONAL NATURE SUCH AS DRINKS, LAUNDRY, TIPS, ETC.</li>\n</ul>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"><strong>FIXED DEPARTURE DATES FOR 2017/2018.</strong></p>\n<table class=\" alignleft\">\n<tbody>\n<tr>\n<td width=\"107\">\n<p><strong>MONTH</strong></p>\n</td>\n<td width=\"188\">\n<p><strong> DATES</strong></p>\n</td>\n</tr>\n<tr>\n<td width=\"107\">\n<p>APRIL</p>\n</td>\n<td width=\"188\">\n<p> 04, 07, 12, 19, 21, 28</p>\n</td>\n</tr>\n<tr>\n<td width=\"107\">\n<p>MAY</p>\n</td>\n<td width=\"188\">\n<p>05, 13, 19, 26</p>\n</td>\n</tr>\n<tr>\n<td width=\"107\">\n<p>JUNE</p>\n</td>\n<td width=\"188\">\n<p>02, 09, 15, 23</p>\n</td>\n</tr>\n<tr>\n<td width=\"107\">\n<p>JULY</p>\n</td>\n<td width=\"188\">\n<p>05, 12, 19, 26</p>\n</td>\n</tr>\n<tr>\n<td width=\"107\">\n<p>AUGUST</p>\n</td>\n<td width=\"188\">\n<p>02, 09, 16, 23</p>\n</td>\n</tr>\n<tr>\n<td width=\"107\">\n<p>SEPTEMBER</p>\n</td>\n<td width=\"188\">\n<p>01, 08, 15, 22</p>\n</td>\n</tr>\n<tr>\n<td width=\"107\">\n<p>OCTOBER</p>\n</td>\n<td width=\"188\">\n<p>01, 11, 18, 25</p>\n</td>\n</tr>\n<tr>\n<td width=\"107\">\n<p>NOVEMBER</p>\n</td>\n<td width=\"188\">\n<p>03, 10, 17</p>\n</td>\n</tr>\n<tr>\n<td width=\"107\">\n<p>DECEMBER</p>\n</td>\n<td width=\"188\">\n<p>01, 08,15</p>\n</td>\n</tr>\n<tr>\n<td width=\"107\">\n<p>JANUARY</p>\n</td>\n<td width=\"188\">\n<p>05, 12, 19</p>\n</td>\n</tr>\n<tr>\n<td width=\"107\">\n<p>FEBRUARY</p>\n</td>\n<td width=\"188\">\n<p>02, 09, 16</p>\n</td>\n</tr>\n</tbody>\n</table>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\">(<strong>Schedule is subject to change under unavoidable circumstances.)</strong></p>\n<p style=\"text-align: left;\"> </p>\n<p style=\"text-align: left;\"><strong>HOTEL WE PROVIDE:</strong></p>\n<table class=\" alignleft\">\n<tbody>\n<tr>\n<td width=\"135\">\n<p><strong>PLACES</strong></p>\n</td>\n<td width=\"376\">\n<p><strong>NAME OF THE HOTEL.</strong></p>\n</td>\n</tr>\n<tr>\n<td width=\"135\">\n<p>LHASA</p>\n</td>\n<td width=\"376\">\n<p>HTL TIBET HERITAGE OR SIMILAR</p>\n</td>\n</tr>\n<tr>\n<td width=\"135\">\n<p>XIGATSE</p>\n</td>\n<td width=\"376\">\n<p>HTL MANASAROVAR OR SIMILAR</p>\n</td>\n</tr>\n<tr>\n<td width=\"135\">\n<p>RONGBUCK</p>\n</td>\n<td width=\"376\">\n<p>GUEST HOUSE</p>\n</td>\n</tr>\n<tr>\n<td width=\"135\">\n<p>SHAKYA</p>\n</td>\n<td width=\"376\">\n<p>HTL MANASAROVAR SHAKYA OR SIMILAR</p>\n</td>\n</tr>\n</tbody>\n</table>\n<p style=\"text-align: left;\"> </p></p>',NULL,NULL,NULL,'/assets/images/destinations/tibet.jpg',0,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(4,1,'Tibet Trek','tibet-trek','High-plateau treks from nomadic pastures to Kailash kora and Everest approaches — remote, spiritual, and visually immense.','<p><strong>Tibet Trek — Across the High Plateau</strong></p><p>Trekking in Tibet is a journey into silence, sky, and sacred geography. Trails cross 4,500m+ passes, turquoise lakes, and centuries-old hermitages far from roads. Whether a short Shingri La traverse or the three-day Kailash kora, our team manages yaks, camp logistics, and gradual acclimatization.</p><p><strong>Highlights</strong></p><ul><li>Nomadic camps, monasteries, and sky-burial sites with cultural context</li><li>Panoramas of Everest, Cho Oyu, and Shishapangma</li><li>Guided acclimatization and wilderness camp support</li></ul><p><strong>Who it suits:</strong> Fit trekkers comfortable with altitude and basic camping. Best April–June and September–October.</p>',NULL,NULL,NULL,'/assets/images/destinations/tibet.jpg',1,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(5,NULL,'BHUTAN','bhutan','Bhutan General Information Land of the Thunder Dragon Sandwiched between India and Tibet and for centuries forbidden to foreigners, the kingdom of Bhutan has preserved its timeless traditions and…','<p><strong>Bhutan General Information</strong> <br />\n <strong>Land of the Thunder Dragon</strong><br />\n Sandwiched between India and Tibet and for centuries forbidden to foreigners, the kingdom of Bhutan has preserved its timeless traditions and ancestral way of life. Apart from the rich cultural heritage, it is a land of soaring scenery of paramount peaks. Scared mountains, often unnamed and unclimbed, soar above tropical forests and richly cultivated valleys. Ancient legends are preserved in spectacular Cliffside monasteries and colorful festivals echo the unwavering Buddhist beliefs of the local people.<br />\n <br />\n The selected trek highlights begin from Paro where the famous “Tiger Nest” monastery is perched high on a vertical 2,000 foot cliff face. From here there is a choice to either trek east, via Thimpu the capital city, to Gangtey, or north towards Laya village through the wild and rugged country on the border with Tibet.<br />\n <br />\n A choice toward the east is relatively easier with a combination of the Gagtey and the Bumthang valleys. The trek leads into a beautiful and unspoiled countryside, through forests of rhododendron, magnolia and juniper, and across two gentle passes with wonderful views of the mountains to the north. The stop at Gogana with its enchanting monastery and nomadic dialect, the Bjopkha, will be a haunting experience. On the other hand Bhumthang is considered the most sacred of the valleys from where a circuitous route across the Phephel Pass to the Thang valley holds spiritual essence.<br />\n <br />\n North of Paro, the trek involves some 150 miles of rugged walking the trail moves through the villages of Linghsi, Laya and Gassa. The attractions of this trek include semi-tropical and alpine forests home to a wealth of birdlife and flora. Higher up dwell the blue sheep, takin the horned ruminant and various species of beautiful birds. Through out the trek semi-nomadic life full with the magnificent panoramic views of Chomolhari, Jichu Brake and Tsering Gang.<br />\n <br />\n Adventure Specialist Travel can also arrange the variety of treks, cultural tours in Bhutan. We will forward all necessary details upon receiving your inquiries.<br />\n <br />\n Besides treks, Adventure Specialists Travel organizes rafting adventures in four rapid strewn Himalayan Rivers and private climbing expedition for groups and individuals to any of Nepal’s trekking peaks. Details are available on request.</p>\n<p> <br />\n <strong>Full Country Name</strong><br />\n Kingdom of Bhutan<br />\n <br />\n <strong> Area</strong><br />\n 46,620 sq km (18,182 sq mi)<br />\n <br />\n <strong>Population</strong><br />\n 700,000 (approax. 1 million)<br />\n <br />\n <strong>Capital City</strong><br />\n Thimpu (Population: 40,000)<br />\n <br />\n <strong> Language</strong><br />\n Dzongkha, English, Sharchopha, Nepali etc<br />\n <br />\n <strong>Religion</strong><br />\n 70% Buddhist, 25% Hindu, 5% others<br />\n <br />\n <strong>Government</strong><br />\n Monarchy<br />\n <br />\n <strong> King</strong><br />\n Jigmey Singey Wangchuck<br />\n <br />\n <strong>Prime Minister</strong><br />\n Rotates every year among the cabinet ministers<br />\n  <strong><br />\n Time</strong><br />\n Bhutan time is 6 hours ahead of GMT and there is only one time zone throughout the country.<br />\n <br />\n <strong> <br />\n Language</strong><br />\n The national language is Dzongkha. English is widely spoken in major towns and is a medium of education in schools. Other widely spoken languages are Nepali, Bumthap, Sharchop and Hindi. There are a host of local dialects spoken in small pockets within the country.<br />\n <br />\n <br />\n <strong>Money</strong><br />\n The unit of currency is the ngultrum (Nu), which is equivalent to one Indian Rupee. The Indian rupee is also legal tender. Major convertible currencies and travelers\' Cheques can be exchanged at banks in all major towns. Certain credit cards (MasterCard, Visa, &amp; American Express) are accepted at a few large hotels and some shops. <br />\n <br />\n <br />\n <strong>Food</strong><br />\n Bhutanese eat simple and are renowned for the plentiful use of chilies; among the most popular dish is an \"Ema Datshi\' made entirely out of chilies and cheese. However Tourist hotels and lodges offer buffet style meals with choice of continental, Bhutanese and Indian Cuisine. On Treks and camping, you will be pleasantly surprised by what our cooks can prepare.<br />\n <br />\n <strong> <br />\n Drinks</strong><br />\n It is safer to drink bottled, boiled and filtered water. A reasonable variety of both hard and soft drinks are available in hotels, restaurants and shops in most towns. Many Bhutanese enjoy drinking traditional homemade alcoholic brews made from wheat, millet or rice.<br />\n <br />\n <br />\n <strong>Electricity</strong><br />\n All towns in western Bhutan have a reliable power supply. Elsewhere, access is less consistent, and electricity is not available in many outlying areas of the country. The voltage supply is 220/240, the same as India. If you do bring electrical appliances, take along an international converter kit complete with a set of adapter plugs. The sockets are round.<br />\n <br />\n <br />\n <strong>Health</strong><br />\n The main health risks are similar to other South Asian countries, namely diarrhea, respiratory infection or more unusual tropical infection. It is wise to have health insurance, and although vaccinations are not mandatory they are recommended. When trekking, there are also risks associated with altitude sickness and accident. In the event of health problems there are basic hospital facilities in each district headquarters.<br />\n <br />\n <br />\n <strong>Safety</strong><br />\n The crime rate is currently extremely low, making Bhutan one of the safer places in the world. It is rare to feel insecure within the country.<br />\n <br />\n <br />\n <strong>Communications</strong><br />\n All major towns have basic communication facilities, including post, telephone, fax and telegraph. Television and internet were introduced in 1999, and can be accessed from most towns and cities.<br />\n <br />\n <br />\n <strong>Shopping</strong><br />\n The most popular tourist purchases are traditional Bhutanese arts and handicrafts. Produced by skilled artisans, these are generally of a high quality, and include Buddhist paintings and statues, textiles, jewelry and wooden bowls and carvings. Bhutan is not a consumer society, and the variety of everyday goods available is not particularly large. Bhutan is also popular for its exquisite postage stamps.<br />\n <br />\n <strong> <br />\n Weather/Climate</strong><br />\n The central valleys of Punakha, Wangdiphodrang, Mongar, Trashigang and Lhunsthi enjoy a semi tropical climate with very cool winters, while Thimphu, Paro, Tongsa and Bumthang have pleasant summer, cold winters, with monsoon rains mainly from June-August.<br />\n <br />\n At the end of September, after the last of the big rains, autumn suddenly arrives, and is a magnificent season for trekking until November.<br />\n <br />\n Winter in Bhutan is from starts from the end of November until Febuary, and at this time of the year the climate is dry, with daytime temperatures sometimes falling below zero Celsius.<br />\n The southern part of Bhutan is tropical, and in general the east of Bhutan is warmer than the west of the country.<br />\n <br />\n <br />\n <strong>National Symbols of Bhutan</strong><br />\n Find out more about national symbols; Flag, national anthem, emblem, national animal, bird, flower, tree, national sport - archery etc.<br />\n <br />\n <strong><br />\n Archery the National Sport</strong><br />\n Since time immemorial Bhutanese have been passionate about their national sport of Dha. Competitions are a riot of colour and excitement, with two teams in traditional dress shooting at small wooden targets placed 140m apart (Olympic standard is 50m).<br />\n <br />\n <strong><br />\n Traditional Medicine</strong><br />\n One of the ancient names for Bhutan was Menjong \'the Land of Medicinal Herbs\'.<br />\n The Himalayan Buddhist system of medicine is called So-ba Rig-pa and is practised in many countries today. Because it originally developed in ancient Tibet, it is commonly known as Tibetan medicine.<br />\n <br />\n <strong><br />\n The Black Necked Cranes</strong><br />\n The rare and endangered black-necked crane occupies a special place in Bhutanese hearts and folklore. Its arrival every autumn from Tibet in­spires songs and dances; it usually heralds the end of the harvesting season and also the time when farm families start migrating to warmer climates.</p></p>',NULL,NULL,NULL,'/assets/images/destinations/bhutan.jpg',1,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(6,5,'Bhutan Tour','bhutan-tour','Cultural tours through the Thunder Dragon Kingdom — Paro, Thimphu, Punakha and Bumthang with dzongs, festivals, and forested valleys.','<p><strong>Bhutan Tour — Kingdom in the Clouds</strong></p><p>Bhutan combines living Buddhism with pristine landscapes. Visit Tiger’s Nest perched above Paro, the grand dzongs of Punakha and Thimphu, and the sacred valleys of Bumthang. Our itineraries are paced for genuine encounters — artisans, monks, and farmers — not just sights.</p><p><strong>Highlights</strong></p><ul><li>Tiger’s Nest hike and Paro valley heritage</li><li>Punakha Dzong, Dochula Pass, and Phobjikha glacial valley</li><li>Festival dates (Paro & Thimphu Tshechu) on request</li></ul><p><strong>Travel Note:</strong> Bhutan’s daily sustainable fee is included in our quotes; we arrange permits, guides, and private transport. Best March–May and September–November.</p>',NULL,NULL,NULL,'/assets/images/destinations/bhutan.jpg',0,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(7,5,'Bhutan Trekking','bhutan-trekking','Gentle valley walks to rugged northern trails — rhododendron forests, yak pastures, and Himalayan views in a pristine kingdom.','<p><strong>Bhutan Trekking — Between Monasteries and Meadows</strong></p><p>From the classic Druk Path between Paro and Thimphu to the wild routes of Laya and Lingzhi, Bhutan’s trails are immaculate and uncrowded. Trek through juniper and rhododendron forests, cross bright prayer-flag passes, and overnight in villages or comfortable camps.</p><p><strong>Highlights</strong></p><ul><li>Druk Path, Bumthang Owl Trek, and Jomolhari Base Camp options</li><li>High hospitality: camping crews, ponies, and sanctuary lodges</li><li>Spring rhododendron and autumn clarity</li></ul><p>We match grade to experience and provide thorough briefings, local guides, and eco-conscious logistics.</p>',NULL,NULL,NULL,'/assets/images/destinations/bhutan.jpg',1,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(8,NULL,'SIKKIM','sikkim','Nestled between the Kingdoms of Bhutan and Nepal is a little known region called Sikkim. Now a province of India, Sikkim was an independent Kingdom until 1952 and is the overland gateway to Bhutan.…','Nestled between the Kingdoms of Bhutan and Nepal is a little known region called Sikkim. Now a province of India, Sikkim was an independent Kingdom until 1952 and is the overland gateway to Bhutan. Although the region has been populated by a huge range of Himalayan ethnicities Sikkim is still predominantly Buddhist. Famed for its amazing array of flora and fauna, our trips here offer all levels of trekker an intimate and beautiful mountain experience. Apart from seeing the 3rd highest mountain, Kanchenjunga up close you will meander through stands of Buddhist prayer flags, idyllic villages and lush forests full of colorful butterflies.<br />\n<br />\n</p>\n<p><strong>Highlights:</strong> <br />\nPanoramic views of Kanchenjunga, unspoilt Tibetan villages and culture, beautiful mountain vistas, giant butterflies fluttering through old growth forests.<br />\n<br />\nDue to the extreme altitude, there is an immense variation in climate and vegetation. With a rainfall of about 140 inches in Gangtok, the climate is tropical up to 5,000ft, temperate between 5,000ft–13,000ft, alpine at 13,000ft, and snowbound at 16,000ft and above.</p>\n<p>The best time to visit Sikkim is between mid-March and June but<br />\nespecially, April and May, when the rhododendrons and orchids are in bloom. However, temperatures can be high, especially in the valleys. During the monsoons, from the end of June until end September, rivers and roads become impenetrable, though plants nurtured by the incessant rain erupt again into bloom towards the end of August. October, when orchids bloom once again and November tend to have the clearest weather of all. As December approaches, it gets bitterly cold at high altitudes, and remains that way until early March, despite long periods of clear weather.</p>\n<p>The best time to visit this zone is from mid September to mid December, although it gets pretty cold by December. The high seasons again starts from mid-march &amp; continues till mid June. During monsoon months ie; from June to September, the view of the mountains gets obscured &amp; rainfall is pretty heavy (270 cm annually)<br />\n<br />\n</p>\n<p><strong>People &amp; Religion</strong><br />\nSikkim is the least populated state in India. There are three principal communities of Nepalese (75%), Lepchas (20%), and smaller proportions of Bhutias and Limbus. The Bhutias are Buddhist and so are most of the Lepchas. The Nepalese are chiefly Hindus. Lepchas or the Rong appear to be the original inhabitants of Sikkim as no legends of their migration are available. In the 13th century, the Bhutias from Kham area of Tibet came to the state. They believed in Buddhism of the Mahayana sect. The Nepalis were the last to enter Sikkim, in the mid 19th century.</p>\n<p>All communities live in perfect harmony sharing each other’s cultures, ethos and traditions with the result that there is now a Sikkimese culture, which is composite of all the three prominent communities. Most of the people speak Nepali, which is also the state language. It is the harmony of the place that provides justification to the name of the state derived form Sukhim, meaning “happy home, a place of peace.”</p>\n<p>Though Hinduism is equally followed, Buddhism is entrenched in the tradition of the state. The people have faith in the Buddha, the dharma (his teachings), and the sangha (assembly of monks) where religious texts are studied, taught and preserved. Soaked in the religious tradition, the land has a spiritual ambience where prayer flags with inscriptions of Buddhist texts flutter around the boundary of the village to ward off evil spirits, prayer wheels rotate to the currents of water, and chortens and lucky signs are common sights.<br />\n<br />\n</p>\n<p><strong>Entry Formalities</strong><br />\nForeigners require an Inner Line Permit (ILP) in addition to normal Indian visa to enter Sikkim and can visit Gangtok, Rumtek, Phodang and Pemayangtse. No permit is required to enter &amp; stay in Darjeeling &amp; other parts of North Bengal including Kalimpomg.</p>\n<p>All foreigners intending to visit Sikkim can avail of 15 days inner-line permit with a further 15 days extension available in Gangtok. Re-entry into Sikkim is not possible within 3 months of leaving Sikkim. Restricted area permit for individuals &amp; groups for restricted areas i.e., Gangtok. Rumtek, Phodong, Pemagyantse can be obtained in advance from all Indian missions aboard, Sikkim tourism offices at Delhi, Calcutta, Siliguri &amp; Gangtok, after furnishing requisite documents. A standard Permit allows one to visit Gangtok, Rumtek, Phodong and Pemagyantse. The permits are checked and the visas stamped while entering and leaving Sikkim.</p>\n<p>Foreigners without a valid passport and permit are not allowed to enter Sikkim. The best and the easiest way to get the permit is when the individual/group is getting their Indian visa stamp on their passport. All they have to do is express their desire to visit Sikkim &amp; the Indian missions abroad endorses the permit while granting the India visa.</p></p>',NULL,NULL,NULL,'/assets/images/sikkim-cover.jpg',2,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(9,NULL,'Myanmar','myanmar','Golden pagodas, Bagan’s temple plains, Inle Lake leg-rowers and colonial Yangon — a warm, timeless culture by the Irrawaddy.','<p><strong>Myanmar — Grace of the Golden Land</strong></p><p>Myanmar welcomes travelers with gilded pagodas, gentle smiles, and landscapes that feel untouched. Explore the ancient temples of Bagan at sunrise, the floating gardens of Inle Lake, Mandalay’s royal heritage, and Yangon’s Shwedagon Pagoda. Adventure Specialist Travel curates respectful itineraries with licensed guides, river journeys, and boutique stays.</p><p><strong>Highlights</strong></p><ul><li>Bagan archaeological zone and Irrawaddy sunset cruise</li><li>Inle Lake villages, markets, and Intha leg-rowers</li><li>Yangon heritage walk and Shwedagon at twilight</li></ul><p><strong>When to go:</strong> November–February is cool and dry; March–May is hot, June–October is green with fewer visitors. We tailor pace, flights, and community-based experiences.</p>',NULL,NULL,NULL,'/assets/images/destinations/Yangon12.jpg',3,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(10,9,'Myanmar Tour','myanmar-tour','Classic and short-stay tours from Yangon to Bagan, Mandalay and Inle — pagodas, markets, and river life with seamless logistics.','<p><strong>Myanmar Tour — Pagodas, Plains, and Lake Life</strong></p><p>Our Myanmar tours connect the country’s cultural heartlands without rushing. Choose a 4-day Yangon–Bago short program, a 7-day bike route, or full 13–14-day golf and heritage circuits. Every itinerary includes private transport, domestic flights where useful, and guides who explain living Buddhism as well as history.</p><p><strong>Options</strong></p><ul><li>Yangon–Bago–Yangon cultural short stay (Shwedagon, Sule, and Allied Cemetery)</li><li>Mandalay–Bagan by bike and boat with temple cycling</li><li>Golf at Pun Hlaing and Bagan with heritage touring</li></ul><p>We can combine Myanmar with Nepal or Bhutan for a complete Himalayan & Irrawaddy journey.</p>',NULL,NULL,NULL,'/assets/images/destinations/Yangon12.jpg',0,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(11,10,'4 days short program','4-days-short-program','Option 1 : Special Short Program Yangon-Bago-Yangon Day 01 : Yangon Arrival and City Tour Arrived in Yangon and our Guide and car will welcome you at our international airport. Than we will take to…','<p style=\"text-align: center;\"><span style=\"font-size: 18pt;\"><strong>Option 1 : Special Short Program </strong></span></p>\n<p style=\"text-align: center;\"><span style=\"font-size: 18pt;\"><strong>Yangon-Bago-Yangon</strong></span></p>\n<p><strong> </strong></p>\n<p><strong>Day 01 : Yangon Arrival and City Tour </strong></p>\n<p>Arrived in Yangon and our Guide and car will welcome you at our international airport. Than we will take to you the hotel . Overnight in Yangon.</p>\n<p><em> </em></p>\n<p><strong>Day 02 : Yangon –Bago -Yangon</strong></p>\n<p>After breakfast we will drive to Bago. Bago, also known as Pegu, was the capital of the Mon Kingdom in the 15th century and is a town steeped in legend. The sites in Bago are spread out around the town and you’ll spend time exploring with your guide, learning about the history and myths of the city. Stops include the 55-metre long reclining Shwethalyaung Buddha, the four seated Buddhas at Kyaikpun and the old palace of Kambozathadi. The Mon-style Shwemawdaw Pagoda is the most outstanding religious monument in Bago. This golden temple stands at 114 metres tall, higher than Yangon’s Shwedagon Pagoda, and can be seen from around 10 kilometres outside of the city.While in Bago we’ll also take time to visit the city’s local sites, including the town market and a Mon neighborhood where the locals once produced woven textiles.From Bago we’ll return to Yangon this afternoon. Before reaching the city limits, stop in Htaukkyan township to visit the Allied War Cemetery. This beautifully-landscaped, peaceful area is the final resting place for more than 27,000 Allied Soldiers who perished during the World War II campaign in Myanmar. Overnight in Yangon</p>\n<p><strong> </strong></p>\n<p><strong>Day 03 : Yangon Sightseeing</strong></p>\n<p>After breakfast we will Start excursion to city center, colonial style buildings and Sule Pagoda - a landmark in downtown Yangon. Proceed visit the Shwedagon Pagoda- described by Somerset Maugham: \"The Shwedagon rose superb, glistening with its gold, like a sudden hope in the dark night of the soul of which the mystics write, glistening against the fog and smoke of the thriving city.\" This massive bell-shaped stupa rises nearly 100 meters above its hill-top surroundings. Wander through this magnificent structure and its courtyards, stupas, bells, temples, and Buddha images, and see religious and secular visitors from all parts of the globe. Shwedagon has become the symbol of Myanmar. Overnight in Yangon</p>\n<p><em> </em></p>\n<p><strong>Day 04 : Yangon Departure</strong></p>\n<p>Breakfast at hotel. Leisure on your own time. On the way to Airport, visit “Kyauktawgyi Pagoda and Royal White Elephant”. Kyauktawgyi Pagoda is also known as Lawka Chanthar Arbayar Laba Muni Buddha Image. Within the walking distance from Minn Dhamma Hill, there is an Elephant house where the three white elephants are kept. Than depart your flight. Have a nice day.</p>\n<p>&nbsp;</p>\n<p>ACCOMODATION 3*** Hotels</p>\n<table width=\"604\">\n<tbody>\n<tr>\n<td width=\"97\">\n<p>City</p>\n</td>\n<td width=\"321\">\n<p>Hotel</p>\n</td>\n<td width=\"185\">\n<p>Room Type</p>\n</td>\n</tr>\n<tr>\n<td width=\"97\">\n<p>Yangon</p>\n</td>\n<td width=\"321\">\n<p>Hotel Accord/Summit</p>\n</td>\n<td width=\"185\">\n<p>Deluxe</p>\n</td>\n</tr>\n</tbody>\n</table>\n<p>&nbsp;</p>\n<p><strong>Quotation for Myanmar tour</strong></p>\n<p><strong>2 PAX                                    : USD 545 per person on double sharing basis</strong></p>\n<p>&nbsp;</p>\n<p><strong>Package price includes:</strong></p>\n<p>+ Private door-to-door pick-up &amp; drop-off services<br />\n + All private transportation<br />\n + Accommodation shared in Double/Twin room with daily breakfast<br />\n + Experienced English Speaking Guide<br />\n + Meals as stated in the itinerary (B: Breakfast; L: Lunch; D: Dinner)<br />\n + All sightseeing tickets<br />\n + Tissues and water on coach<br />\n + Services charges and government tax<br />\n + No extra charge after services confirmation<br />\n + Guaranteed 24/7 hotline support</p>\n<p><strong>Package price excludes:</strong></p>\n<p>+ Personal expenses, tips and gratuities<br />\n + Travel insurance<br />\n + Beverages<br />\n + Myanma Visa stamp fee <br />\n + Peak season or Public holidays surcharge if any<br />\n + Compulsory Gala dinner on X-Mas or New Year if any<br />\n + Other services not mentioned above</p>\n<p>&nbsp;</p>\n<p style=\"text-align: center;\"><span style=\"font-size: 18pt;\"><strong>Option 2 : Special Short Program</strong></span></p>\n<p style=\"text-align: center;\"><span style=\"font-size: 18pt;\"><strong>Yangon-Golden Rcok-Bago-Yangon</strong></span></p>\n<p>&nbsp;</p>\n<p><strong>Day 01 : Yangon Arrival and Shwe Dagon Sightseeing</strong></p>\n<p>Arrival at Yangon International Airport. Welcome by our well-experienced guide. Upon arrival, transfer to your hotel. Start excursion to city center, colonial style buildings and Sule Pagoda - a landmark in downtown Yangon. Proceed visit the Shwedagon Pagoda- described by Somerset Maugham: \"The Shwedagon rose superb, glistening with its gold, like a sudden hope in the dark night of the soul of which the mystics write, glistening against the fog and smoke of the thriving city.\" This massive bell-shaped stupa rises nearly 100 meters above its hill-top surroundings. Wander through this magnificent structure and its courtyards, stupas, bells, temples, and Buddha images, and see religious and secular visitors from all parts of the globe. Shwedagon has become the symbol of Myanmar. Overnight in Yangon</p>\n<p><strong> </strong></p>\n<p><strong>Day 02 : Yangon-Golden Rock and Sightseeing </strong></p>\n<p>Depart Yangon early this morning for a journey by road to Kyaikhtiyo, the Golden Rock. Late morning, arrive at Kyaikhtiyo base camp (approximately 5 hrs). Travel by local, open-air truck along a winding road (45 minutes) where you will be dropped off a short 5 minutes walk from Golden Rock.  A huge boulder covered by gold leaf and delicately balanced on the edge of a cliff, Golden Rock is one of Myanmar\'s main pilgrimage sites.  The pagoda here is said to hold a hair of the Buddha and Buddhists from across the country come here to pay homage.  Overnight near Golden Rock. </p>\n<p><strong> </strong></p>\n<p><strong>Day 03 : Golden Rock – Bago Sightseeing- Yangon</strong></p>\n<p>After breakfast, return to the base camp by open-air truck and begin the return journey to Yangon. En route, stop in Bago. Bago, also known as Pegu, was the capital of the Mon Kingdom in the 15th century and is a town steeped in legend. The sites in Bago are spread out around the town and you’ll spend time exploring with your guide, learning about the history and myths of the city. Stops include the 55-metre long reclining Shwethalyaung Buddha, the four seated Buddhas at Kyaikpun and the old palace of Kambozathadi. The Mon-style Shwemawdaw Pagoda is the most outstanding religious monument in Bago. This golden temple stands at 114 metres tall, higher than Yangon’s Shwedagon Pagoda, and can be seen from around 10 kilometres outside of the city. While in Bago we’ll also take time to visit the city’s local sites, including the town market and a Mon neighborhood where the locals once produced woven textiles. From Bago we’ll return to Yangon this afternoon. Before reaching the city limits, stop in Htaukkyan township to visit the Allied War Cemetery. This beautifully-landscaped, peaceful area is the final resting place for more than 27,000 Allied Soldiers who perished during the World War II campaign in Myanmar.</p>\n<p>&nbsp;</p>\n<p><strong>Day 04 : Fly Back to Yangon and See you again </strong><strong>(B)</strong></p>\n<p>Morning take a flight back to Yangon. Upon arrival in Yangon, free time at leisure to discover Yangon on your own until the departure time to the airport for the flight home.</p>\n<p>&nbsp;</p>\n<p>&nbsp;</p>\n<p>ACCOMODATION 3*** Hotels</p>\n<table width=\"626\">\n<tbody>\n<tr>\n<td width=\"120\">\n<p>City</p>\n</td>\n<td width=\"321\">\n<p>Hotel</p>\n</td>\n<td width=\"185\">\n<p>Room Type</p>\n</td>\n</tr>\n<tr>\n<td width=\"120\">\n<p>Yangon</p>\n</td>\n<td width=\"321\">\n<p>Hotel Accord/Summit  or Similar</p>\n</td>\n<td width=\"185\">\n<p>Deluxe</p>\n</td>\n</tr>\n<tr>\n<td width=\"120\">\n<p>Golden Rock</p>\n</td>\n<td width=\"321\">\n<p>Mountain Top</p>\n</td>\n<td width=\"185\">\n<p>Deluxe</p>\n</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Quotation for Myanmar tour</strong></p>\n<p><strong>2 PAX                                    : USD 575 per person on double sharing basis</strong></p>\n<p>&nbsp;</p>\n<p><strong> </strong><strong> </strong></p>\n<p><strong>Package price includes:</strong></p>\n<p>+ Private door-to-door pick-up &amp; drop-off services<br />\n + All private transportation<br />\n + Accommodation shared in Double/Twin room with daily breakfast<br />\n + Experienced English Speaking Guide<br />\n + Meals as stated in the itinerary (B: Breakfast; L: Lunch; D: Dinner)<br />\n + All sightseeing tickets<br />\n + Tissues and water on coach<br />\n + Services charges and government tax<br />\n + No extra charge after services confirmation<br />\n + Guaranteed 24/7 hotline support</p>\n<p><strong>Package price excludes:</strong></p>\n<p>+ Personal expenses, tips and gratuities<br />\n + Travel insurance<br />\n + Beverages<br />\n + Myanma Visa stamp fee <br />\n + Peak season or Public holidays surcharge if any<br />\n + Compulsory Gala dinner on X-Mas or New Year if any<br />\n + Other services not mentioned above</p>\n<p>&nbsp;</p>\n<p style=\"text-align: center;\"><span style=\"font-size: 18pt;\"><strong>Option 3 : Special Short Program</strong></span></p>\n<p style=\"text-align: center;\"><span style=\"font-size: 18pt;\"><strong>Yangon-Golden Rock-Yangon</strong></span></p>\n<p><strong>Day 01: Yangon arrival</strong></p>\n<p>Welcome at Yangon international airport by our guide and car . Than we will take you to the hotel for your check-in. After check-in hotel we will arrange sightseeing upon your arrival flight time. Overnight in Yangon</p>\n<p>&nbsp;</p>\n<p><strong>Day 02: Yangon – Drive to Kyaikhityo</strong></p>\n<p>Golden Rock (Kayiktiyo) is one the most important pilgrimage sites for Myanmar Buddhist and maybe one of the strangest sites (miracle) for foreign visitors. A rock (gold gilded) with a small stupa (15th feet) built on top of it, is balancing on the edge of a mountain and looks as if it could tumble down into the ravine below at any moment. Buddhist believe due to some hairs of Buddha brought by a holy hermit enshrined into that hermit’s head shape rock prevent the rock from falling. People who want to get a hiking can do there and the site can be reached after a short walk (1.5 hours from Hermit Hill base camp or a long walk (about 6-7 hours from the first base camp. Surrounding the Golden Rock are many local souvenirs shops, pagoda accessories selling shops and shops selling Burmese traditional medicinal products made off indigenous animals found by the hunters living in the jungle in this region.</p>\n<p>&nbsp;</p>\n<p><strong>Day 03: Kyaikhtiyo – Bago – Yangon</strong></p>\n<p>Breakfast at hotel. Early risers may enjoy returning to the Golden Rock; about 10 minutes walk from the Kyaikto Hote l or 60 minutes from the Golden Rock Hotel, to watch the sunrise. After breakfast, walk down the mountain and return by truck to your car/minibus, or alternatively walk all the way down to the base camp at Kinpun. Drive back to Bago and visit SHWEMAWDAW PAGODA, which has a stupa inlaid with diamonds and is Bago\'s golden landmark. See SHWETHALYAUNG Buddha, which dates from 994 and is revered throughout Myanmar as the most beautiful Reclining Buddha. Lunch at a local restaurant in Bago. Just outside Bago, visit KYAIKPUN Pagoda with four 30-meter high Buddha figures seated back to back. An optional visit is included on the way back to Yangon at the British War Cemetery near Htauk Kyan. Arrive Yangon in the evening and transfer to your hotel.</p>\n<p>&nbsp;</p>\n<p><strong>Day 04: Yangon departure</strong></p>\n<p>Free program until our guide and car pick up for your international airport. You can have a walk around the lake which is famous lake in Yangon.</p>\n<p>&nbsp;</p>\n<p>&nbsp;</p>\n<p>ACCOMODATION Myanmar Luxury Hotel</p>\n<table width=\"620\">\n<tbody>\n<tr>\n<td width=\"113\">\n<p>City</p>\n</td>\n<td width=\"321\">\n<p>Hotel</p>\n</td>\n<td width=\"185\">\n<p>Room Type</p>\n</td>\n</tr>\n<tr>\n<td width=\"113\">\n<p>Yangon</p>\n</td>\n<td width=\"321\">\n<p>Kandaw Gyi Palace Resort</p>\n</td>\n<td width=\"185\">\n<p>Deluxe</p>\n</td>\n</tr>\n<tr>\n<td width=\"113\">\n<p>Yangon</p>\n</td>\n<td width=\"321\">\n<p>Kandaw Gyi Palace Resort</p>\n</td>\n<td width=\"185\">\n<p>Lake Front</p>\n</td>\n</tr>\n<tr>\n<td width=\"113\">\n<p>Golden Rock</p>\n</td>\n<td width=\"321\">\n<p>Mountain Top</p>\n</td>\n<td width=\"185\">\n<p>Deluxe</p>\n</td>\n</tr>\n</tbody>\n</table>\n<p>&nbsp;</p>\n<p><strong>Quotation for Myanmar tour</strong></p>\n<p><strong>2 PAX                                    : USD 670 per person on double sharing basis</strong></p>\n<p>&nbsp;</p>\n<p><strong><br />\nPackage price includes:</strong><strong> </strong></p>\n<p>+ Private door-to-door pick-up &amp; drop-off services<br />\n + All private transportation<br />\n + Accommodation shared in Double/Twin room with daily breakfast<br />\n + Experienced English Speaking Guide<br />\n + All sightseeing tickets<br />\n + Tissues and water on coach<br />\n + Services charges and government tax<br />\n + No extra charge after services confirmation<br />\n + Guaranteed 24/7 hotline support</p>\n<p><strong>Package price excludes:</strong></p>\n<p>+ Personal expenses, tips and gratuities<br />\n + Travel insurance<br />\n + Beverages<br />\n + Myanma Visa stamp fee <br />\n + Peak season or Public holidays surcharge if any<br />\n + Compulsory Gala dinner on X-Mas or New Year if any<br />\n + Other services not mentioned above</p>\n<p>&nbsp;</p></p>',NULL,NULL,NULL,'/assets/images/destinations/Yangon12.jpg',0,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(12,10,'Biking Tour (7D/6N)','biking-tour-7d6n','Myanmar Bike Tour - from Mandalay to Bagan Day 1: Yangon- Mandalay (-/L) After breakfast, you will be picked up at your hotel by our driver to transfer to the airport for the flight to Mandalay, the…','<p style=\"text-align: center;\"><span class=\"fontstyle0\"><span style=\"font-size: 18pt;\"><strong>Myanmar Bike Tour - from Mandalay to Bagan</strong></span><br />\n </span></p>\n<p><span class=\"fontstyle0\"><br />\n <strong>Day 1: Yangon- Mandalay (-/L)</strong><br />\n </span><span class=\"fontstyle2\">After breakfast, you will be picked up at your hotel by our driver to transfer to the airport for the flight to Mandalay, the last Capital City of the 3</span><span class=\"fontstyle2\">rd </span><span class=\"fontstyle2\">Myanmar Dynasty.Upon arrival at Mandalay airport, drive to Mandalay City. Lunch at Local Restaurant. Then drive to your hotel for check-in.In the afternoon, taste your biking visiting the Kuthodaw Pagoda which is known as the world biggest<br />\n book of the world, Golden Palace Monastery where you can see the best wood-carvings. The monastery was at first in the Palace City wall and 5 years before the British Annexation, it was dismantled and reassembled to the present site to be donated to the venerable monks. The<br />\n Golden Palace so called because the interior and exterior surfaces of wood structure have been gilt with millions of Gold Leaves that are fabricated in Mandalay. Finally, go up Mandalay Hill to enjoy the panoramic view of the city with sunset.<br />\n </span><strong><span class=\"fontstyle3\">Overnight at Mandalay<br />\n </span><span class=\"fontstyle0\">Estimate Biking Distance 10 KM</span></strong></p>\n<p><span class=\"fontstyle0\"><br />\n <strong>Day 2: Mandalay – Amarapura – Sagaing – Mingun-Mandalay (B/L/-)</strong><br />\n </span><span class=\"fontstyle2\">Today Excursion is by Bike to the Ancient capitals of Amarapura aka the Southern City, the ancient Royal Capital before Mandalay. In Amarapura, visit one of the biggest monasteries with more than 1200 Buddhist monks where under the strict tight-scheduled Rules the monks study very hard the<br />\n Buddhist Canons day and night in order to be able to carry on the Buddha’s teachings verbally like the Noble Thera did after the Buddha’s demise in the 6</span><span class=\"fontstyle2\">th </span><span class=\"fontstyle2\">Century B.C. Then visit the Silk-Weaving workshop. Here, Amarapura hand-weaving silk Designs are very famous as Lun Yar Kyaw Cheik, More-than hundred Loom Design, in which many small colorful silk threads looms wave through the weft creating the unique Myanmar Ceremonial silk longyis. Depending on the designs, to finish a longyi with a hundred or so looms, it can take at least a month! Then drive to U Bein Bridge believed to be the longest wooden bridge in the world that spans Taung Thaman Lake. Take a walk on the bridge and enjoy a photo. And then ride the bike to Sagaing crossing over newly-opened bridge paralleling the first British- built Span side by side.Lunch at Local Restaurant.Sagaing, the capital city of Sagaing Division, has been quite a few times Royal Capital and now stands as a Buddhist Center.And then continue by bike to Mingun where the World’s Biggest Mingun Bell, weighing over 90 Metric Tons that is believed to be the world heaviest hanging bell in the world and<br />\n Migun Stupa unfinished due to the mysterious beliefs of its builder. Then, visit the very first Home for Aged founded purely by a Burmese Lady. Meeting with the long-term nurse who speaks fair<br />\n English at the Center of Old Age pays a lot. Finally visit Mya Thein Dan Pagoda which represents famous Mt. Meru according to Buddhist Cosmology.After that, take the boat back to Mandalay<br />\n along Ayeyarwaddy River relaxing on chairs provided on board.<br />\n </span><strong><span class=\"fontstyle3\">Overnight at Mandalay<br />\n </span><span class=\"fontstyle0\">Estimate Biking Distance 40 KM</span></strong></p>\n<p><br />\n <span class=\"fontstyle0\"><strong>Day 3: Mandalay – Monywa – Pho Win Taung Caves (B/L/-)</strong><br />\n </span><span class=\"fontstyle2\">After breakfast, drive to Sagaing crossing over newly-opened bridge paralleling the first Britishbuilt Span side by side. Sagaing, the capital city of Sagaing Division, has been quite a few times Royal Capital and now stands as a Buddhist Center. Visit Sagaing Hills filled with Meditation Centers, Monasteries, and Nunneries. The view from the platform of Sun Oo Punya Shin Pagoda that takes the overwhelming hilltop is really breath-taking.Then, drive to Monywa (approx; 2.5 hours), the second biggest city after Mandalay in the central Myanmar. Monywa is the major trade center whose surroundings are filled with the fertile fields yielding the best crops such as rice, beans, vegetables and also tobacco. One the way to the town, visit Thanbude Temple with its more than half million Buddha Images inside and outside of the main temple. In the afternoon, drive to the jetty of Chindwin River which is the third longest river to take a ferry to the other side to do the countryside Bike Tour to Pho Win Taung Cave Pagodas. Upon arrival, walk all the way up the Sandstone Caves build from 16</span><span class=\"fontstyle2\">th </span><span class=\"fontstyle2\">to 19</span><span class=\"fontstyle2\">th </span><span class=\"fontstyle2\">century. Monkey food sellers will accompany you all the way of the loop. Then, drive back to Monywa, cross the river to the town and check-in at the hotel.<br />\n </span><strong><span class=\"fontstyle3\">Overnight in Monywa<br />\n </span><span class=\"fontstyle0\">Estimate Biking Distance 25 KM</span></strong></p>\n<p><span class=\"fontstyle0\"><br />\n <strong>Day 4: Monywa- Pakokku- Bagan (B/L/-)</strong><br />\n </span><span class=\"fontstyle2\">After breakfast, visit Bodhi Tahtaung Buddhas so named after one-thousand Sitting Buddha under one thousand Bo Trees. Then, visit the second largest Reclining Buddha and the tallest standing Buddha which measures 413 feet in height.Then drive to Chaung U junction where you can start<br />\n your biking up to Ma U village to feel the village life with home industries such as Bamboo Scales Making, Incense Stick and so on. Talk a walk among the 16</span><span class=\"fontstyle2\">th </span><span class=\"fontstyle2\">to 18</span><span class=\"fontstyle2\">th </span><span class=\"fontstyle2\">century Pagoda Complex nearby. You can also drop in at one of the pit-stops where you can see the Myanmar Traditional<br />\n Cosmetic, Thanaka plantations. Continue driving to Pakokku, which is known as the Tobacco Trade Center. In Pakokku, if the time permits, you can visit some Myanmar Home Industries such as Cheroot or Myanmar Cigar factory, Paper-Mache factory, slipper factory, all hand-made home factories located at the Pakokku City. Then continue to Ancient city Bagan. Hundreds of Ancient Stupas, Temples, Monasteries, Libraries and Buddhist Universities welcome you to the then Heart of Buddhism. On arrival, continue to your hotel for Check-in.<br />\n </span><strong><span class=\"fontstyle3\">Overnight in Bagan<br />\n </span><span class=\"fontstyle0\">Estimate Biking Distance 35 KM</span></strong></p>\n<p><br />\n <span class=\"fontstyle0\"><strong>Day 5: Bagan Sightseeing (B/L/-)</strong><br />\n </span><span class=\"fontstyle2\">After breakfast, start your full-day biking tour with a climb up to a temple to have a glimpse of Bird’s eye view tasting a bit of its marvel. Then you may visit Nyaung U morning market which is known as Market On The Floor with a variety of local vegetables and products such as typical snacks, food, Handicrafts, Thanakha the most adorned Burmese Make-up, and so on. Then, visit the most sacred stupa Shwe Zi Gon built in 11</span><span class=\"fontstyle2\">st </span><span class=\"fontstyle2\">Century by the most outstanding Buddhist King,<br />\n Anawrahta, Gu Byauk Gyi Temple to see the mural from 12</span><span class=\"fontstyle2\">nd </span><span class=\"fontstyle2\">Century, the massive red-colored Htilominlo Temple</span><span class=\"fontstyle0\">, </span><span class=\"fontstyle2\">and lastly before check-in at the hotel, visit most beautiful Ananda Temple built in late 11</span><span class=\"fontstyle2\">st </span><span class=\"fontstyle2\">Century housing giant Standing Buddhas which give the viewers illusion of Smiling-or-Serious facial expression of the Enlightened One.In the afternoon, bike to New Bagan where you may pay a visit to famous Lacquer Wares Workshop is worth enough to see its hand-made black products that come in a variety of household items from the smallest one of tea-cup to the Giant Sun Oak, the food container to be sent to the Buddhist monasteries in the yester years.<br />\n Biking around the New Bagan until the sunset over the one of temple.<br />\n </span><strong><span class=\"fontstyle3\">Overnight in Bagan<br />\n </span><span class=\"fontstyle0\">Estimate Biking Distance 20 KM</span></strong></p>\n<p><span class=\"fontstyle0\"><br />\n <strong>Day 6: Bagan - Mt.Popa (half-way by bike) – Bagan (B/L/-)</strong><br />\n </span><span class=\"fontstyle2\">Today, start your biking adventure up to the Myanmar’s Nat paradise of Mt.Popa. Enjoy the landscape of Upper Myanmar with hundreds of Toddy Palms that can be seen along the fence line of the farms where the local farmers grow peanuts, sesame, peas, cotton and many more crops. After an hour or more biking, you will get to the Palm Tree Hut where you can study how the<br />\n Myanmar people from Upper Myanmar make good use of Toddy palm trees; the branches for furniture, the wood from the stem to make stools and tables and house beams and the leaf for roofing, and the palm juice to make several drinks including distilling the strong country spirit.After a short break, continue to Mt.Popa. Make some stops on the way from time to time to make photos and talk to the local people. After one and a half hour of biking, you will arrive at the town of Mt.Popa.Enjoy your lunch at Yangon Restaurant.After lunch, you can visit the Nat Museum located at the foot of Popa Taung Kalat. There are 37 Nats altogether officially recognized by the<br />\n authorities, and of course there are millions of Nats that are not registered. Mt.Popa is the abode of all the official nats and the museum is the place where you can see the Life-size statues of Registered Nats.It is optional to ascend the 800-step Mt.Popa on top of which, from the pagoda and shrines, you can enjoy the panoramic view of the Oasis area looking out west, you can see the plain of Bagan. Along the staircase, you will see many pilgrims, shops selling the souvenirs of Mt.Popa, and lastly the Mt.Popa monkeys. Then continue your way back to Bagan either by car or on a bike.<br />\n </span><strong><span class=\"fontstyle3\">Overnight at Bagan.<br />\n </span><span class=\"fontstyle0\">Total Biking Distance 50 KM</span></strong></p>\n<p><br />\n <span class=\"fontstyle0\"><strong>Day 7: Bagan departure (B/-/-)</strong><br />\n </span><span class=\"fontstyle2\">After breakfast, transfer to Bagan Nyaung U Airport for the flight onwards! </span><span class=\"fontstyle3\">End of Program. Have a Nice Trip!!!<br />\n </span><span class=\"fontstyle2\">Exploring Burma by bike will allow you to see and experience the very best of the country, and you’ll have the opportunity to meet the friendly locals along the way. Myanmar, as it is now known, has a varied landscape and rich cultural history, a real sense of which you can discover on a cycling tour. If you’re keen to discover this country in South East Asia by bike then Orchid Myanmar Travel has a range of cycling tour holidays to choose from. Our Cycling Day Tour focuses on Yangon, while we also operate another day tour around the Inle Lake. If you want a longer, fuller cycling tour then our ‘Best Bike Tour’ allows you to see most of the important tour sites in Myanmar, including the cities of Mandalay and Bagan. Myanmar is a territory previously unexplored by outsiders, but it is now on many peoples’ ‘must-see’ destination lists. Much of Myanmar has been closed off to travelers for at least the last forty years, but now you can explore the best of what this country has to offer – and it doesn’t get much better than seeing it by bike.</span></p>\n<p>&nbsp;</p>\n<p><strong> <span class=\"fontstyle0\">Tour at a glance<br />\n Tour Cost                                : </span><span class=\"fontstyle2\">starts from US$ 1085<br />\n </span><span class=\"fontstyle0\">Bike Hire                                 : </span><span class=\"fontstyle2\">included see our bikes here<br />\n </span><span class=\"fontstyle0\">Tour Grade                             : </span><span class=\"fontstyle2\">4 out of 5<br />\n </span><span class=\"fontstyle0\">Number of Cycling Days    : </span><span class=\"fontstyle2\">4 full days / 2 half days<br />\n </span><span class=\"fontstyle0\">Tour Ends                               : </span><span class=\"fontstyle2\">Bagan<br />\n </span><span class=\"fontstyle0\">Group Size                              : </span><span class=\"fontstyle2\">Minimum 2Pax. Maximum 6Pax.<br />\n </span><span class=\"fontstyle0\">Accommodation                   : </span><span class=\"fontstyle2\">6 Nights in 2-3* hotels<br />\n </span><span class=\"fontstyle0\">Meals                                        : </span><span class=\"fontstyle2\">breakfast and lunches except day 7<br />\n </span><span class=\"fontstyle0\">Single Supplement              : </span><span class=\"fontstyle2\">US$ 202<br />\n </span><span class=\"fontstyle0\">Total Cycling Distance       : </span><span class=\"fontstyle2\">180 kilometers<br />\n </span><span class=\"fontstyle0\">Tour Meets                             : </span><span class=\"fontstyle2\">Yangon<br />\n </span><span class=\"fontstyle0\">Minimum age                        : </span><span class=\"fontstyle2\">18 years old<br />\n </span><span class=\"fontstyle0\">Entrance Fees                        : </span><span class=\"fontstyle2\">included<br />\n </span><span class=\"fontstyle0\">Vehicle Support                    : </span><span class=\"fontstyle2\">Full vehicle support</span> </strong></p></p>',NULL,NULL,NULL,'/assets/images/destinations/Yangon12.jpg',1,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(13,10,'Golf (14D/13N)','golf-14d13n','Special Golf Tour Yangon-Bagan-Mandalay-Pyin Oo Lwin-Inle Lake-Yangon Day 1: Yangon On arrival at Yangon airport in the morning meet your guide and transfer to the hotel. Spiritual Shwedagon Pagoda -…','<span class=\"fontstyle0\"><strong>Special Golf Tour Yangon-Bagan-Mandalay-Pyin Oo Lwin-Inle Lake-Yangon</strong><br />\n<br />\n<strong>Day 1: Yangon</strong><br />\n</span><span class=\"fontstyle2\">On arrival at Yangon airport in the morning meet your guide  and transfer to the hotel. Spiritual Shwedagon Pagoda - Half Day Tour .So what\'s behind the golden façade of the Shwedagon Pagoda? During this interactive half day tour we take you through the back door and show you the full history of the pagoda, the daily life of all people living in the immediate surroundings of the pagoda and a deeper insight in the Buddhist religion and how the spiritual belief is mixed with the belief in nats - the Myanmar spirits. An intriguing half day tour starting from the bottom of the hill and passing the workshops, markets and monasteries which will be useful or even essential to understand more of the country during the rest of your journey. The tour includes offerings to monks and the pagoda, a visit to a fortune teller and a Burmese lunch.<br />\n</span></p>\n<p><span class=\"fontstyle0\"><strong>Day 2: Golf at Pun Hlaing Golf Club</strong><br />\n</span><span class=\"fontstyle2\">Breakfast at the hotel. Golf at Pun Hlaing Golf Club - </span><span class=\"fontstyle3\">The Pun Hlaing Golf Club was established in 2000 and is located northwest part of Yangon, about 45 minutes\' drive from city center. Pun Hlaing<br />\nGolf Club encompasses 18 holes championship golf course expertly designed by the renowned Gary Player, one of the world\'s legendary golf players.<br />\n</span></p>\n<p><strong><span class=\"fontstyle0\">Day 3: Yangon </span><span class=\"fontstyle4\">– </span></strong><span class=\"fontstyle0\"><strong>Bagan</strong><br />\n</span><span class=\"fontstyle2\">Breakfast at the hotel.Transfer to Yangon airport for flight to Bagan.Upon arrival Bagan, start orientation tour. A full day tour by car, with an experienced guide through Bagan will show you the best known temples of the area. We start the day climbing Buledi Pagoda to get a first (impressive) view over the whole area. From here the guide plans his way to some of the other amazing temples that have been here for hundreds of years. Places like the Ananda, Dhammayangyi, Sulamani, and Thatbyinnyu will certainly impress you. Lunch will be taken at a local restaurant and around 4pm we continue the tour by horse cart to Pyathada pagoda for sunset with some refreshing drinks served! Oh… we forgot to mention the best part of this tour; whenever you see a temple you like just ask you guide to stop to have a look at it - simply pick your own favorite temple.</span></p>\n<p><span class=\"fontstyle0\"><strong>Day 4: Golf at Bagan Golf Course</strong><br />\n</span><span class=\"fontstyle2\">Breakfast at the hotel. Golf at Bagan Golf Resort - </span><span class=\"fontstyle3\">The Bagan Golf course was established in 1996 and is located next to Amazing hotel at the back of the archaeological zone- and some of the holes play among the pagodas. Unlike other golf courses, it is located in the middle of the world-famous Bagan temples and pagodas. Surely is an oasis in the dry zone as the relaxing garden next to 11th<br />\ncentury ruins and the Ayeyarwaddy river stretching out beyond. The 18 holes Bagan golf course wanders in between some of the ancient pagodas.<br />\n</span></p>\n<p><span class=\"fontstyle0\"><strong>Day 5: Bagan - Mandalay - Pyin Oo Lwin</strong><br />\n</span><span class=\"fontstyle2\">Breakfast at the hotel. Morning transfer to airport &amp; take the flight to Mandalay.Upon arrival to transfer to Pyin Oo Lwin, the former summer capital for the British colonial administration by private car.Visit the botanical gardens in Pyin Oo Lwin (Maymyo) which was established in 1915. You are expected to meet Mr Cameron at his antique shop at the Maymyo market (Gandamar land shop AA-5/6). A native from Pyin Oo Lwin who will show you around his home town by horse cart and tell you everything about the history of the colonial buildings in Pyin Oo Lwin. Mr Cameron and his colleagues are the experts on colonial antiquities in Pyin Oo Lwin and will bring you<br />\nto places like the secret society building, the colonial Candacraig hotel, the former Japanese police station, the former swimming pool for the British, the old coffee factory, the church of England, the Governors house, the private house of Mr Burnet\'s son (Mr Burnet used to be the famous chef at Candacraig Hotel) and a local colonial house where the residents are happy to tell their family\'s history. During this 2.5 hour tour you will get to know the intimate side of the colonial history of this former British hill station.<br />\n</span></p>\n<p><span class=\"fontstyle0\"><strong>Day 6: Golf in Pyin Oo Lwin</strong><br />\n</span><span class=\"fontstyle2\">Breakfast at the hotel. Morning transfer to Golf club - </span><span class=\"fontstyle3\">This 18 holes course is considered to be one of the most popular courses in Myanmar. The weather is good at this hilly summer retreat; it gives the best playing condition in the country. </span><span class=\"fontstyle2\">Evening back to Mandalay by private car<br />\n</span></p>\n<p><span class=\"fontstyle0\"><strong>Day 7: Mandalay</strong><br />\n</span><span class=\"fontstyle2\">Breakfast at the hotel. Mandalay Orientation: Mahamuni &amp; Amarapura half day sightseeing<br />\ntour(preferable afternoon) This tour is the perfect introduction to Mandalay. We start with the<br />\nMahamuni pagoda and have a look at this century\'s old Buddha statue originating from Mrauk Oo. It is a very lively temple compound where men are sticking gold leaves to the Buddha statue. The Mahamuni is also an excellent place to shop around for the perfect Buddha statue (bronze or wood). Can\'t find what you are looking for? Find a marble statue at the next stop which is the marble carving street. The old capital of Amarapura is a very quiet village nowadays where<br />\nyou only hear the sound of the weaving machines. We walk through the famous Mahagandayon monastery </span><span class=\"fontstyle2\">complex with hundreds of monks, visit one of the small weaving factories and walk over U-Bein Bridge and take a boat ride before heading back to your hotel. The rest of the day car and guide are available for additional visits<br />\n</span></p>\n<p><span class=\"fontstyle0\"><strong>Day 8: Golf in Mandalay</strong><br />\n</span><span class=\"fontstyle2\">Breakfast at the hotel. Transfer to Yaytagun Taung Golf club - </span><span class=\"fontstyle3\">The golf course is located about 25<br />\nminutes\' drive from downtown Mandalay. It is 18 - holes course of 6386 yards and design by Mandalay City Development Committee and opened in 1996. It is located at the foot of the Yaytagon Taung (Water Fall Mountain)<br />\n</span></p>\n<p><span class=\"fontstyle0\"><strong>Day 9: Mandalay - Heho - Golf in Kalaw</strong><br />\n</span><span class=\"fontstyle2\">Breakfast at the hotel. Morning transfer to airport and take the flight to Heho. Upon arrival, drive to Kalaw, the former British hill station Kalaw has a bit of a colonial atmosphere with the old villas, churches and schools. The town is inhabited by Burmese, Nepal and Indian as well as several hill tribes like the Padaung and the PaOh. Kalaw is the starting point for rewarding treks. Play golf at Kalaw golf course - </span><span class=\"fontstyle3\">The 18-hole golf course in Kalaw is one of the oldest ones in the country where golf is a popular sport. In the mountains, surrounded by pine trees at an attitude of more than 1100 meters above sea level a cool breeze in the morning makes the temperature perfect for a round of golf. During a half day excursion we bring you to the green to enjoy a relaxing game of golf with<br />\nyour friends.<br />\n</span></p>\n<p><span class=\"fontstyle0\"><strong>Day 10: Kalaw - Inle Lake</strong><br />\n</span><span class=\"fontstyle2\">Breakfast at the hotel. Transfer to Inle Lake and start the following excursion: Inle Lake in southern Shan State is a vast natural lake surrounded by traditional Shan villages. On the lake itself the Intha people have been living for many centuries in village built entirely on stilts on the lake. Today we will take you by private motorboat around the lake to discover the natural beauty of the lake, visit the floating gardens, hopefully see some of the famous leg rowers and have some tea at a<br />\nlocal family\'s house. On and around the lake traditional markets are held in different villages according to a 5- day rotating schedule and today we will take you to visit a colourful market, frequented by Shan and PaO people living nearby. We will certainly also visit a local cheroot factory (where the Burmese cigars are made), floating tomato gardens, Intha Heritage house where the Burmese cats are bred and if wanted we visit a weaving factory. We return to the hotel around 4 PM, in time for sunset. </span></p>\n<p><span class=\"fontstyle0\">Accommodation: </span><span class=\"fontstyle2\">View Point Lodge - Cottage </span><span class=\"fontstyle4\">• Meals: </span><span class=\"fontstyle2\">Breakfast, lunch • </span><span class=\"fontstyle0\">Transport: </span><span class=\"fontstyle2\">Private car / boat<br />\n</span></p>\n<p><span class=\"fontstyle0\"><strong>Day 11: Inle Lake - Golf at Aye Tharyar Golf Resort</strong><br />\n</span><span class=\"fontstyle2\">Breakfast at the hotel. Golf at Aye Thar Yar Golf Resort - </span><span class=\"fontstyle3\">Drive to Ayetharyar golf resort, perfect set up amidst the Shan Plateau which was established in 1995. This course has a challenging per 72 with 7380 yards with perfect cut of Bhamuda grass with rather large greens. </span><span class=\"fontstyle2\">Continue to the hotel in Nyaung Shwe</span><br />\n<span class=\"fontstyle0\"><strong>Day 12: Inle Lake - Nyaung Shwe (Biking)</strong><br />\n</span><span class=\"fontstyle2\">Breakfast at the hotel. Nyaung Shwe and surrounding by bike &amp; peddle boat - full day (from<br />\n09:30 till 15:30). Nyaung Shwe is a very lively little town which used to be the home of the Shan prince of Nyaung Shwe (Mr Sao Shwe Thaike, who later became the first prime minister of Myanmar after independence). Nowadays the town\'s market still functions as a busy trading Centre for all surrounding villages. During this day excursion on a bicycle starting from the Centre of Nyaung Shwe we visit the local Mingala market, bike through some gorgeous scenery to the ancient teak wooden Shwe Yan Pyay monastery with the oval windows and visit the former palace of the last Shan prince. We have a Shan lunch at the Viewpoint restaurant. In the afternoon we first going to peddle ourselves in small boats (2 persons per boat) through the small canals and floating gardens to see local life from the water and then continue to visit the picturesque pagoda near Nanthe village. We end the tour with a visit and some wine tasting of the excellent wines at the Red Mountain winery in Nyaung Shwe. Total biking distance: around 8 km.Suitable for anybody with a normal health condition<br />\n</span></p>\n<p><strong><span class=\"fontstyle0\">Day 13: Nyaung Shew - Heho </span><span class=\"fontstyle4\">– </span></strong><span class=\"fontstyle0\"><strong>Yangon</strong><br />\n</span><span class=\"fontstyle2\">Breakfast at the hotel. Morning transfer to airport and take the flight to Yangon. Upon arrival to Yangon, transfer to your hotel. Car &amp; guide available for you to make your own excursion.<br />\n</span></p>\n<p><strong><span class=\"fontstyle0\">Day 14: Yangon </span><span class=\"fontstyle4\">– </span></strong><span class=\"fontstyle0\"><strong>Departure</strong><br />\n</span><span class=\"fontstyle2\">Breakfast at the hotel. Transfer to airport and take your onward flight<br />\n</span></p>\n<p><span class=\"fontstyle2\"><strong>Price per person (based on 2 persons travelling together) based on 4 star hotels: USD 3,803 per person</strong></span></p>\n<p><span class=\"fontstyle2\"><br />\n</span><span class=\"fontstyle0\"><strong>Golf Package Inclusions:</strong><br />\n</span><span class=\"fontstyle5\">x </span><span class=\"fontstyle2\">English speaking guide during sightseeing (different guide in each location)<br />\n</span><span class=\"fontstyle5\">x </span><span class=\"fontstyle2\">Accommodation including breakfast at the hotels mentioned<br />\n</span><span class=\"fontstyle5\">x </span><span class=\"fontstyle2\">Tour and transfers as indicated on the itinerary including entrance fees<br />\n</span><span class=\"fontstyle5\">x </span><span class=\"fontstyle2\">Meals as mentioned in the program<br />\n</span><span class=\"fontstyle5\">x </span><span class=\"fontstyle2\">Sightseeing and excursion as mentioned including admission fees<br />\n</span><span class=\"fontstyle5\">x </span><span class=\"fontstyle2\">Private boat for Inle Lake trips<br />\n</span><span class=\"fontstyle5\">x </span><span class=\"fontstyle2\">Domestic flights<br />\n</span><span class=\"fontstyle0\"><strong>Golf Package Exclusions:</strong><br />\n</span><span class=\"fontstyle5\">x </span><span class=\"fontstyle2\">Personal Expenses<br />\n</span><span class=\"fontstyle5\">x </span><span class=\"fontstyle2\">Other meals and drinks<br />\n</span><span class=\"fontstyle5\">x </span><span class=\"fontstyle2\">Tips<br />\n</span><span class=\"fontstyle5\">x </span><span class=\"fontstyle2\">Any other fees<br />\n</span><span class=\"fontstyle5\">x </span><span class=\"fontstyle2\">Visa</span><br />\n<span class=\"fontstyle0\">Special Package Features / Add-ons:<br />\n</span><span class=\"fontstyle5\">x </span><span class=\"fontstyle2\">Fully customizable<br />\n</span><span class=\"fontstyle5\">x </span><span class=\"fontstyle2\">Choose how many rounds of golf suits you<br />\n</span><span class=\"fontstyle5\">x </span><span class=\"fontstyle2\">Amazing sightseeing options on non-golf days<br />\n</span><span class=\"fontstyle5\">x </span><span class=\"fontstyle2\">4 and 5 star accommodation options available<br />\n</span><span class=\"fontstyle5\">x </span><span class=\"fontstyle2\">Discounts for group bookings<br />\n</span><span class=\"fontstyle0\">Hotels<br />\n</span><span class=\"fontstyle5\">x </span><span class=\"fontstyle2\">Traders Hotel - Yangon<br />\n</span><span class=\"fontstyle5\">x </span><span class=\"fontstyle2\">Tharabar Gate Hotel - Bagan<br />\n</span><span class=\"fontstyle5\">x </span><span class=\"fontstyle2\">Kandawgyi Hill Resort - Mandalay<br />\n</span><span class=\"fontstyle5\">x </span><span class=\"fontstyle2\">Amara Resort – Kalaw<br />\n</span><span class=\"fontstyle5\">x </span><span class=\"fontstyle2\">Serenity Hotel - Nyaung Shwe</span> </p></p>',NULL,NULL,NULL,'/assets/images/destinations/Yangon12.jpg',2,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(14,10,'Golf (6D/5N)','golf-6d5n','Special Golf Tour in Yangon - Bagan – Yangon Day 1: Yangon On arrival at Yangon airport in the morning meet your guide and transfer to the hotel. Spiritual Shwedagon Pagoda - Half Day Tour So what\'s…','<p style=\"text-align: center;\"><span class=\"fontstyle0\" style=\"font-size: 18pt;\"><strong>Special Golf Tour in</strong><br />\n<strong>Yangon - Bagan – Yangon</strong></span></p>\n<p><strong>Day 1: Yangon</strong><br />\n<span class=\"fontstyle2\">On arrival at Yangon airport in the morning meet your guide and transfer to the hotel. Spiritual Shwedagon Pagoda - Half Day Tour So what\'s behind the golden façade of the Shwedagon Pagoda?<br />\nDuring this interactive half day tour we take you through the back door and show you the full history of the pagoda, the daily life of all people living in the immediate surroundings of the pagoda and a deeper insight in the Buddhist religion and how the spiritual belief is mixed with the belief in nats - the Myanmar spirits. An intriguing half day tour starting from the bottom of the hill and passing the workshops, markets and monasteries which will be useful or even essential to understand more of the country during the rest of your journey. The tour includes offerings to<br />\nmonks and the pagoda, a visit to a fortune teller and a Burmese lunch.<br />\n</span></p>\n<p style=\"text-align: left;\"><span class=\"fontstyle0\"><strong>Day 2: Yangon – Bagan</strong><br />\n</span><span class=\"fontstyle2\">Breakfast at the hotel. Transfer to Yangon airport for flight to Bagan.Upon arrival Bagan, start orientation tour.A full day tour by car, with an experienced guide through Bagan will show you the best known temples of the area. We start the day climbing Buledi Pagoda to get a first (impressive)<br />\nview over the whole area. From here the guide plans his way to some of the other amazing temples that have been here for hundreds of years. Places like the Ananda, Dhammayangyi, Sulamani, and Thatbyinnyu will certainly impress you. Lunch will be taken at a local restaurant and around 4pm we continue the tour by horse cart to Pyathada pagoda for sunset with some refreshing drinks served! Oh… we forgot to mention the best part of this tour; whenever you see a temple you like just ask you guide to stop to have a look at it - simply pick your own favorite temple.<br />\n</span></p>\n<p style=\"text-align: left;\"><span class=\"fontstyle0\"><strong>Day 3: Golf at Bagan Golf Course</strong><br />\n</span><span class=\"fontstyle2\">Breakfast at the hotel.Golf at Bagan Golf Resort - </span><span class=\"fontstyle3\">The Bagan Golf course was established in 1996 and is located next to Amazing hotel at the back of the archaeological zone- and some of the holes play among the pagodas. Unlike other golf courses, it is located in the middle of the world-famous Bagan temples and pagodas. Surely is an oasis in the dry zone as the relaxing garden next to 11th century ruins and the Ayeyarwaddy river stretching out beyond. The 18 holes Bagan golf course wanders in between some of the ancient pagodas.</span></p>\n<p style=\"text-align: left;\"><span class=\"fontstyle0\"><strong>Day 4: Bagan - Heho - Taunggyi (Golf at Aye Tharyar)</strong><br />\n</span><span class=\"fontstyle2\">Breakfast at the hotel; Transfer to airport for flight to Heho.Golf at Aye Thar Yar Golf Resort - </span><span class=\"fontstyle3\">Drive to Ayetharyar golf resort, perfect set up amidst the Shan Plateau which was established in 1995. This course has a challenging per 72 with 7380 yards with perfect cut of Bhamuda grass with rather large greens. </span><span class=\"fontstyle2\">Continue to the hotel in Inle Lake.<br />\n</span></p>\n<p style=\"text-align: left;\"><span class=\"fontstyle0\"><strong>Day 5: Taunggyi - Inle Lake</strong><br />\n</span><span class=\"fontstyle2\">Breakfast at the hotel.Start the following excursion: Inle Lake in southern Shan State is a vast natural lake surrounded by traditional Shan villages. On the lake itself the Intha people have been living for many centuries in village built entirely on stilts on the lake. Today we will take you by private motorboat around the lake to discover the natural beauty of the lake, visit the floating gardens, hopefully see some of the famous leg rowers and have some tea at a local family\'s house.<br />\nOn and around the lake traditional markets are held in different villages according to a 5-day rotating schedule and today we will take you to visit a colorful market, frequented by Shan and<br />\nPaOh people living nearby. We will certainly also visit a local cheroot factory (where the Burmese cigars are made), floating tomato gardens, Innthar Heritage house where the Burmese cats are bred and if wanted we visit a weaving factory. We return to the hotel around 4 PM, in time for sunset.<br />\n</span></p>\n<p style=\"text-align: left;\"><span class=\"fontstyle0\"><strong>Day 6: Inle Lake – Yangon</strong><br />\n</span><span class=\"fontstyle2\">Breakfast at the hotel Morning transfer to airport and take the flight to Yangon. Upon arrival to Yangon airport, car and guide available for the rest of the day till transfer to the International airport. </span></p>\n<p style=\"text-align: left;\"><span class=\"fontstyle2\"><strong>Price per person (based on 2 persons travelling together) based on 4 star hotels: USD 1620 per person</strong></span></p>\n<p style=\"text-align: left;\"><span class=\"fontstyle2\"><br />\n</span><span class=\"fontstyle0\"><strong>Golf Package Inclusions:</strong><br />\n</span><span class=\"fontstyle4\"> </span><span class=\"fontstyle2\">English speaking guide for sightseeing (one guide at each destination)<br />\n</span><span class=\"fontstyle4\"> </span><span class=\"fontstyle2\">Accommodation including breakfast at the hotels<br />\n</span><span class=\"fontstyle4\"> </span><span class=\"fontstyle2\">Tour and transfers as indicated on the itinerary<br />\n</span><span class=\"fontstyle4\"> </span><span class=\"fontstyle2\">Golf course green-fees and caddy fees<br />\n</span><span class=\"fontstyle4\"> </span><span class=\"fontstyle2\">Meals as mentioned in the program<br />\n</span><span class=\"fontstyle4\"> </span><span class=\"fontstyle2\">Domestic airfares (Yangon-Bagan-Heho-Yangon)<br />\n</span><span class=\"fontstyle4\"> </span><span class=\"fontstyle2\">Entrance fees<br />\n</span><span class=\"fontstyle0\"><strong>Golf Package Exclusions:</strong><br />\n</span><span class=\"fontstyle4\"> </span><span class=\"fontstyle2\">Personal Expenses<br />\n</span><span class=\"fontstyle4\"> </span><span class=\"fontstyle2\">Other meals and drinks<br />\n</span><span class=\"fontstyle4\"> </span><span class=\"fontstyle2\">Tips<br />\n</span><span class=\"fontstyle4\"> </span><span class=\"fontstyle2\">Any other fees<br />\n</span><span class=\"fontstyle4\"> </span><span class=\"fontstyle2\">Visa</span></p>\n<p style=\"text-align: left;\"><span class=\"fontstyle0\"><strong>Special Package Features / Add-ons:</strong><br />\n</span><span class=\"fontstyle4\"> </span><span class=\"fontstyle2\">Fully customizable<br />\n</span><span class=\"fontstyle4\"> </span><span class=\"fontstyle2\">Choose how many rounds of golf suits you<br />\n</span><span class=\"fontstyle4\"> </span><span class=\"fontstyle2\">Amazing sightseeing options on non-golf days<br />\n</span><span class=\"fontstyle4\"> </span><span class=\"fontstyle2\">4 and 5 star accommodation options available<br />\n</span><span class=\"fontstyle4\"> </span><span class=\"fontstyle2\">Discounts for group bookings<br />\n</span><span class=\"fontstyle0\"><strong>Hotels</strong><br />\n</span><span class=\"fontstyle4\"> </span><span class=\"fontstyle2\">Sedona Hotel - Yangon<br />\n</span><span class=\"fontstyle4\"> </span><span class=\"fontstyle2\">Tharabar Gate Hotel - Bagan<br />\n</span><span class=\"fontstyle4\"> </span><span class=\"fontstyle2\">Serenity Hotel - Nyaung Shwe</span></p></p>',NULL,NULL,NULL,'/assets/images/destinations/Yangon12.jpg',3,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(15,NULL,'Nepal','nepal','Himalayan heartland — eight of the world’s 14 eight-thousanders, living heritage, and warm hospitality from Kathmandu to the high passes.','<p><strong>Nepal — Land of Himalaya and Heritage</strong></p><p>From the UNESCO World Heritage sites of Kathmandu, Patan and Bhaktapur to the serene lakes of Pokhara, the jungles of Chitwan, and the great Himalayan trails, Nepal offers rare variety in a compact country. Eight of the world’s fourteen 8,000m peaks rise here, alongside subtropical forests, alpine meadows, and vibrant Newar, Tharu, and Sherpa cultures.</p><p><strong>What we arrange</strong></p><ul><li>Cultural tours: Kathmandu Valley, Lumbini (birthplace of Buddha), Pokhara and Chitwan</li><li>Trekking & peak climbing: Everest, Annapurna, Langtang, Manaslu, Dolpo and Rara</li><li>Adventure: rafting, paragliding, jungle safari, mountain flights and meditation treks</li></ul><p>We operate year-round with seasonal guidance and responsible practices. Explore our Nepal Tours, Treks and Peak Climbing sections to craft your trip.</p>',NULL,NULL,NULL,'/assets/images/nepal-cover.jpg',5,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(16,15,'Nepal Tour','nepal-tour','Comfortable cultural touring for first-time and returning visitors — temples, palaces, lakes, Jungles and mountain views without high-altitude trekking.','<p><strong>Nepal Tour — Culture Without Compromise</strong></p><p>Our Nepal tours are designed for travelers who want great Himalayan scenery with comfortable accommodations and gentle pacing. Discover Kathmandu’s durbar squares, Bhaktapur’s woodcarvings, Patan’s artisans, Pokhara’s lakeside calm, Chitwan’s wildlife, Lumbini’s peace, and Halesi’s sacred caves — all with private guides and vehicles.</p><p><strong>Sample themes</strong></p><ul><li>Kathmandu–Pokhara–Chitwan classic, Lumbini pilgrimage, and Kathmandu Valley heritage circuits</li><li>Unplugged villages, food, and artisan workshops tailored to your interests</li><li>Seamless add-ons: mountain flight, jungle safari, or a short hike</li></ul><p>Tell us your dates, pace, and interests — we’ll propose a clear itinerary with transparent inclusions.</p>',NULL,NULL,NULL,'/assets/images/nepal-cover.jpg',0,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(17,16,'Pokhara Tour','1-week-pokhara-tour','&nbsp; POKHARA CITY TOUR POKHARA TOUR Pokhara city is the second largest city of Nepal after Kathmandu. This city is 200 Km fat a distance from the capital city Kathmandu. By its name, means a city…','&nbsp;</p>\n<div class=\"sec-title clearfix\">\n<h2 class=\"heading-text\">POKHARA CITY TOUR</h2>\n</div>\n<div class=\"post-desc\">\n<p><strong><u>POKHARA TOUR</u></strong></p>\n<p>Pokhara city is the second largest city of Nepal after Kathmandu. This city is 200 Km fat a distance from the capital city Kathmandu. By its name, means a city of ponds as well as called the home to numerous lakes and caves, The lakes in Pokhara includes Fewa lake, Begnash Lake, Rupa lake, Gude lake, Neurani lake and Maidi lake among many others. The notable caves here are Bat Cave, Mahendra Cave and Gupteshwor Cave among others. The peaks can be closely observed from Pokhara including Annapurna, Dhaulagiri, Machhapuchre( Fish Tail) and Manaslu, and all these peaks are above 8000 m from the sea level.</p>\n<p>There are two major notable hilltops in Pokhara that serve as a perfect getaway, the World Peace Pagoda at the southern shore of Fewa lake and Sarangkot, a beautiful hill at the north-west part of Pokhara. The newest attraction of Pokhara is Paragliding. Now you can paraglide from Sarangkot over the famous Fewa Lake and land at the bottom of the city. Other adventure sports in Pokhara include canyoning, base diving, kayaking, mountain biking and rock climbing. </p>\n<p><strong>Tour Highlights</strong></p>\n<ul>\n	<li>Trip Duration: 7 days 6 nights</li>\n	<li>Starts Point: Kathmandu</li>\n	<li>Destination: Pokhara</li>\n	<li>Ends Point: Kathmandu</li>\n	<li>Accommodation: Lodge/Camp</li>\n	<li>Transportation: Private Vehicle/ Flight</li>\n</ul>\n<p>&nbsp;</p>\n<p><strong> Program</strong></p>\n<p><strong>Day 01 : Arrival in Kathmandu</strong></p>\n<p>Upon our arrival at the Tribhuwan International Airport (TIA) in Kathmandu, you will be received at Kathmandu airport by our representative holding your name plate just in front of the exit door of an airport. After formal meeting, you will be drive to the Hotel.</p>\n<p><strong>Day 02 : City tour of Kathmandu valley</strong></p>\n<p>Today after breakfast we will be introduced to our local tour guide and start a guided tour to several of the most historical and spiritual attractions in Kathmandu.</p>\n<p><strong>Sightseeing places</strong></p>\n<ul>\n	<li><strong>Pashupatinath Temple: </strong>This temple is situated 5 km east of Kathmandu, the temple of Lord Shiva; Pathupatinath with two tired golden roof and silver doors is considered one of the holiest shrines of Hindus.</li>\n	<li><strong>Boudhanath Stupa</strong>:This Stupa lays 8kms east of Kathmandu. This ancient colossal Stupa is one of the biggest in the world and the center of Buddhism in the world. It was listed in the UNESCO Heritage Monument in 1979.</li>\n	<li><strong>Swoyambunath Stupa</strong>: Swoyambhunath Stupa, atop the hillock is one of the holiest Buddhist sites in Nepal enlisted in the World Heritage Site.</li>\n	<li><strong>Durbar Square </strong>:Later proceed for city tour of Kathmandu visiting <strong>Durbar Square</strong>, complex of palaces, courtyard and temples, built between the 12th and 18th centuries, use to be the seat of the ancient Malla kings of Kathmandu.</li>\n</ul>\n<p>&nbsp;</p>\n<p>In the afternoon, there will be a pre-trip discussion where we can meet our trek leader and other team members and over night in Kathmandu.</p>\n<p><strong>Day 03 : City tour of Bhaktapur and Patan </strong></p>\n<p>Today you are going to explore Bhaktapur and Patan Durbar Square. After taking breakfast you will be guided around Bhaktapur and Patan.</p>\n<ul>\n	<li><strong>Patan Durbar Square</strong> is situated at the centre of the city of Lalitpur in Nepal. It is one of the three Durbar Squares in the Kathmandu Valley, all of which are UNESCO World Heritage Sites. One of its attraction is the ancient royal palace where the Malla Kings of Lalitpur resided. There are many temples and idols in the area. The main temples are aligned opposite of the western face of the palace.  The Square also holds old Newari residential houses. </li>\n</ul>\n<p><strong> </strong></p>\n<ul>\n	<li><strong>Bhaktapur</strong> literally translates to <strong>Place of devotees. </strong>Bhaktapur has the best preserved palace courtyards and old city center in Nepal, and is listed as a World Heritage Site by UNESCO for its rich culture, temples, and wood, metal and stone artworks. It is the home of traditional art and architecture, historical monuments and craft works, magnificent windows, pottery and weaving industries, excellent temples, beautiful ponds, rich local customs, culture, religion, festivals, and musical mystic and so on. Bhaktapur is still an untouched as well as preserved ancient city that is itself a world to explore for tourists. After Visiting Bhaktapur drive back to Kathmandu.</li>\n</ul>\n<p>&nbsp;</p>\n<p><strong>Day 04 : Fly/ Drive from Kathmandu to Pokhara</strong></p>\n<p>We will set the morning Domestic flight to Pokhara or Private vehicle and it takes 45 min to reach in pokhara by flight and 5-6 hours from vehicle. Then drop you to the Hotel at pokhara. After that visit around lake side and boat ride to Tal Barahi Temple which is lies center of the Fewa Lake. This temple is also known as the lake temple / Overnight at Pokhara.</p>\n<p><strong>Day 05 : Full Day Sighseeing in Pokhara Valley</strong></p>\n<p>Today after breakfast take a short hike to World Peace Pagoda. Take a boat and cross the lake then start short hike from pumdhi village. </p>\n<p><strong>Sight Seeing Places</strong></p>\n<ul>\n	<li><strong>World peace Pagoda</strong></li>\n</ul>\n<p>Standing on top of the Ananda hill, Shanti Stupa adds more beauty to Pokhara Valley. It is a perfect holiday place providing a clear view of the Himalayan range, Fewa Lake and Pokhara city.  One of the popular and adventurous hiking trails is by crossing the Phewa Lake by a local boat and climb uphill through the local villages that takes about an hour to reach the hilltop</p>\n<ul>\n	<li><strong>Devis Fall</strong></li>\n</ul>\n<p>The water forms an underground tunnel after reaching the bottom. This tunnel is approximately 500 feet (150 m) long and runs 100 feet below ground level. After exiting the tunnel, the water passes through a cave called Gupteshwor Mahadev or \"cave beneath the ground\". The Phewa Lake dam is the water source.</p>\n<ul>\n	<li><strong>Bat Cave</strong></li>\n</ul>\n<p>The cave is made of up the limestone and there is the provision of the torch and the emergency lights for the view of the cave and bats. Also, there is the provision of the guides for the assistance. Apart from it’s attraction, it is also rich in greenery as the surroundings of the cave is covered by the forest.</p>\n<ul>\n	<li><strong>Mahendra Cave</strong></li>\n</ul>\n<p>Mahendra cave is also one of the major tourist attraction in Pokhara.  it is named after the name of the Late king Mahendra Bir Bikram Shah Dev. The cave itself is amazing and we can see the various natural shapes and images of the various hindu god and goddess on the stone made of the lime. Here, for the safety measures, electricity is provided through out the cave and additional torch and emergency lights can be taken for the convenience. The area is surrounded by the community forest at the hillside and at the end of road there flows the small river called the Kali Khola /Overnight at pokhara</p>\n<p><strong>Day 06 : Fly/ Drive back to Kathmandu</strong></p>\n<p>We set a morning flight to Kathmandu. On arrival in Kathmandu our representative will pick you from an airport and drop you to your hotel in Kathmandu.</p>\n<p><strong>Day 07 : Departure</strong></p>\n<p>Our representative from Adventure Specialist Travel will pick you from your hotel and drop you to Tribhuvan International Airport or spare some quality days to visit Bhutan or India or Tibet or Myanmar.</p>\n<p><strong><br />\n Above cost includes:</strong></p>\n<ul>\n	<li>Airport picks up and drops.</li>\n	<li>guided sightseeing with entrance fee in private vehicle as per itinerary</li>\n	<li>Accommodation with breakfast daily</li>\n	<li>Airfares for sector KTM/PKR and PKR/KTM</li>\n	<li>English speaking tour guide </li>\n</ul>\n<p>&nbsp;</p>\n<p><strong>Above cost excludes:</strong></p>\n<ul>\n	<li>International flight</li>\n	<li>Visa to Nepal</li>\n	<li>Daily Lunch or dinner</li>\n	<li>Expenses of personal nature such as beverage bills, laundry bills, phone bills etc.</li>\n	<li>Personal tour gears</li>\n	<li>Personal insurance</li>\n	<li>Expenses incurred due to flight delays or cancellation, road blockade, political strikes, natural disaster or anything that is beyond our control.</li>\n	<li>Tips for guide</li>\n</ul>\n</div></p>',NULL,NULL,NULL,'/assets/images/nepal-cover.jpg',0,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(18,16,'Lumbini Tour','lumbini-tour','Lumbini is the birthplace of Lord Buddha and fountain of world peace. Situated in western Nepal, Lumbini is an ancient town where old ruins of ancient city are well preserved. Lumbini has been a holy…','<div class=\"sec-title clearfix\">\n<h2 class=\"heading-text\"> </h2>\n</div>\n<div class=\"post-desc\">\n<p>Lumbini is the birthplace of Lord Buddha and fountain of world peace. Situated in western Nepal, Lumbini is an ancient town where old ruins of ancient city are well preserved. Lumbini has been a holy ground for Buddhists all over the world. The peace garden and international Monastics Zone are the other attraction of Lumbini after the Mayadevi Temple, puskarini pond and the historic Ashok Pillar. There are different archaeological sites around Lumbini in the lakes of Tilaurakot, Kudan,Ramagrama, Niglihawa and others.</p>\n<p><strong>Tour Highlights</strong></p>\n<ul>\n	<li>Trip Duration: 6 days 5 nights</li>\n	<li>Starts Point: Kathmandu</li>\n	<li>Destination: Lumbini (Tilaurakoy, Kudan, Niglihawa)</li>\n	<li>Ends Point: Kathmandu</li>\n	<li>Accommodation: Lodge</li>\n	<li>Transportation: Private Vehicle/ Flight</li>\n</ul>\n<p>Day 01: Arrival in Kathmandu and transfer to hotel.</p>\n<p>Day 02: City tour of Kathmandu valley.</p>\n<p>Day 03: City tour of Bhaktapur and Paten</p>\n<p>Day 04: Fly / Drive to Lumbini</p>\n<p>Day 05: Sightseeing arond Lumbini ( Birth place of lord Gautam Buddha )</p>\n<p>Day 06: Fly/Drive back to Kathmandu</p>\n<p>Day 07: Departure or spare some quality days to visit Bhutan or India or Tibet or Myanmar.</p>\n<p><strong>Above cost includes:</strong></p>\n<ul>\n	<li>Airport picks up and drops.</li>\n	<li>guided sightseeing with entrance fee in private vehicle as per itinerary</li>\n	<li>Accommodation with breakfast daily</li>\n	<li>Airfares for sector KTM/BWA and BWA/KTM</li>\n	<li>English speaking tour guide </li>\n</ul>\n<p><strong>Above cost excludes:</strong></p>\n<ul>\n	<li>International flight</li>\n	<li>Visa to Nepal</li>\n	<li>Daily Lunch or dinner</li>\n	<li>Expenses of personal nature such as beverage bills, laundry bills, phone bills etc.</li>\n	<li>Personal tour gears</li>\n	<li>Personal insurance</li>\n	<li>Expenses incurred due to flight delays or cancellation, road blockade, political strikes, natural disaster or anything that is beyond our control.</li>\n	<li>Tips for guide</li>\n</ul>\n</div></p>',NULL,NULL,NULL,'/assets/images/nepal-cover.jpg',1,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(19,16,'Chitwan Tour','chitwan-tour','&nbsp; Chitwan valley is located in the sub tropical inner terrain region of south-central Nepal. Royal Chitwan National Park is the first national park of Nepal is lies in this valley. Which is…','&nbsp;</p>\n<p>Chitwan valley is located in the sub tropical inner terrain region of south-central Nepal. Royal Chitwan National Park is the first national park of Nepal is lies in this valley. Which is established in 1973 AD and granted the status of horld heritage site in 1984 AD.</p>\n<p>The outdoor adventure allows you to see wild animals, birds and natural beauty. You ride on an elephant’s back or on a four wheeler jeep accompanied by a fully trained guide (also known as expert Naturalists) for the love of nature and animals.</p>\n<p><strong>Tour Highlights</strong></p>\n<ul>\n	<li>Trip Duration:  7 days 6 night</li>\n	<li>Starts Point: Kathmandu</li>\n	<li>Destination: Chitwan ( Chitwan National park)</li>\n	<li>Accommodation: Lodge/Camp</li>\n	<li>Transportation: Private Vehicle/ Domestic Flight</li>\n</ul>\n<p style=\"text-align: center;\"><span style=\"font-size: 24pt;\"><strong><u>Program</u></strong></span></p>\n<p style=\"text-align: left;\"><strong>Day 01: Arrival in Kathmandu</strong></p>\n<p>You will meet our representative from Adventure Specialist Travel at the Tribhuwan International airport, holding your name plate in front of the arrival gate. After meeting you will be drop at your hotel in Kathmandu. Remaining free time there is an option to explore the place near your hotel.</p>\n<p style=\"text-align: left;\"><strong>Day 02: City tour of Kathmandu valley</strong></p>\n<p>Today after breakfast we will be introduced to our local tour guide and start a guided tour to several of the most historical and spiritual attractions in Kathmandu.</p>\n<p><strong>Sightseeing places</strong></p>\n<ul>\n	<li><strong>Pashupatinath Temple: </strong>This temple is situated 5 km east of Kathmandu, the temple of Lord Shiva; Pathupatinath with two tired golden roof and silver doors is considered one of the holiest shrines of Hindus.</li>\n</ul>\n<p></p>\n<ul>\n	<li><strong>Boudhanath Stupa</strong>:This Stupa lays 8kms east of Kathmandu. This ancient colossal Stupa is one of the biggest in the world and the center of Buddhism in the world. It was listed in the UNESCO Heritage Monument in 1979.</li>\n</ul>\n<p><img class=\"size-medium wp-image-471 aligncenter\" src=\"/assets/images/boudhanath-stupa-300x200.jpg\" alt=\"\" width=\"300\" height=\"200\" /></p>\n<ul>\n	<li><strong>Swoyambunath Stupa</strong>: Swoyambhunath Stupa, atop the hillock is one of the holiest Buddhist sites in Nepal enlisted in the World Heritage Site.</li>\n</ul>\n<p><img class=\"size-medium wp-image-226 aligncenter\" src=\"/assets/images/swoyambhunath-stupa-300x225.jpg\" alt=\"\" width=\"300\" height=\"225\" /></p>\n<ul>\n	<li><strong>Durbar Square </strong>:Later proceed for city tour of Kathmandu visiting <strong>Durbar Square</strong>, complex of palaces, courtyard and temples, built between the 12th and 18th centuries, use to be the seat of the ancient Malla kings of Kathmandu.</li>\n</ul>\n<p><img class=\" wp-image-527 aligncenter\" src=\"/assets/images/kathmandu-durbar-square-300x182.jpg\" alt=\"\" width=\"308\" height=\"187\" /></p>\n<p style=\"text-align: left;\"><strong>Day 03: City tour of Bhaktapur and Patan</strong></p>\n<p>Today you are going to explore Bhaktapur and Patan Durbar Square. After taking breakfast you will be guided around Bhaktapur and Patan.</p>\n<p><strong>Patan Durbar Square</strong> is situated at the centre of the city of Lalitpur in Nepal. It is one of the three Durbar Squares in the Kathmandu Valley, all of which are UNESCO World Heritage Sites. One of its attraction is the ancient royal palace where the Malla Kings of Lalitpur resided. There are many temples and idols in the area. The main temples are aligned opposite of the western face of the palace.  The Square also holds old Newari residential houses. </p>\n<p><strong> <img class=\"size-medium wp-image-220 aligncenter\" src=\"/assets/images/patan-durbar-square-300x225.jpg\" alt=\"\" width=\"300\" height=\"225\" /></strong></p>\n<p><strong>Bhaktapur</strong> literally translates to <strong>Place of devotees. </strong>Bhaktapur has the best preserved palace courtyards and old city center in Nepal, and is listed as a World Heritage Site by UNESCO for its rich culture, temples, and wood, metal and stone artworks. It is the home of traditional art and architecture, historical monuments and craft works, magnificent windows, pottery and weaving industries, excellent temples, beautiful ponds, rich local customs, culture, religion, festivals, and musical mystic and so on. Bhaktapur is still an untouched as well as preserved ancient city that is itself a world to explore for tourists. After Visiting Bhaktapur drive back to Kathmandu.</p>\n<p style=\"text-align: left;\"><strong>Day 04: Fly/Drive to Chitwan</strong></p>\n<p>Your tour begins in the early morning with fly to Chitwan that departs from Tribhuwan International airport and it takes 30 min to reach in chitwan. When you reach the national park, enter a lost world of towering trees and twisting vines that is home to rhinos, elephants, crocodiles and deer. Meet your hotel representative for accommodation, where a brief orientation session will be held. After lunch, take a ride in a bullock cart, the local form of transport, to visit a nearby tribal village and museum dedicated to the culture and history of the indigenous Tharu people. Return to your hotel for a pre-dinner cultural show performed by a local troupe.</p>\n<p><img class=\"size-medium wp-image-528 aligncenter\" src=\"/assets/images/chepang-museum-chitwan-300x169.jpg\" alt=\"\" width=\"300\" height=\"169\" /></p>\n<p style=\"text-align: left;\"><strong>Day 05: Enjoy jungle activities</strong></p>\n<p>Spend the morning at your leisure, then after an early lunch embark on a jeep safari to the Chitwan wetlands. Your wildlife safari leads you deep into the jungle, where you might spot one-horned rhinos, deer, bison and monkeys. Keep a look out for less commonly sighted animals such as bears, leopards and Bengal tigers. Return to your hotel for an informative slide presentation on Chitwan’s vegetation and wildlife conducted by a naturalist with a wealth of knowledge about Nepal. Enjoy dinner at your hotel and spend the remainder of the evening relaxing.</p>\n<p><img class=\"size-medium wp-image-529 aligncenter\" src=\"/assets/images/chitwan-elephant-bathing-300x200.jpg\" alt=\"\" width=\"300\" height=\"200\" /></p>\n<p style=\"text-align: left;\"><strong>Day 06: Fly/Drive back to Kathmandu</strong></p>\n<p style=\"text-align: left;\">Spend the morning at your leisure, and then we will set you afternoon flight or drive to Kathmandu. Our representative from Adventure Specialist Travel Company will meet you at the airport and drop you to your hotel.</p>\n<p style=\"text-align: left;\"><strong>Day 07: Depart from Nepal</strong></p>\n<p style=\"text-align: left;\">Departure or spare some quality days to visit Bhutan or India or Tibet or Myanmar</p>\n<p><strong>Above cost includes:</strong></p>\n<ul>\n	<li>Airport picks up and drops.</li>\n	<li>guided sightseeing with entrance fee in private vehicle as per itinerary</li>\n	<li>Accommodation with breakfast daily</li>\n	<li>Airfares for sector KTM/BHR and BHR/KTM</li>\n	<li>English speaking tour guide </li>\n</ul>\n<p><strong>Above cost excludes:</strong></p>\n<ul>\n	<li>International flight</li>\n	<li>Visa to Nepal</li>\n	<li>Daily Lunch or dinner</li>\n	<li>Expenses of personal nature such as beverage bills, laundry bills, phone bills etc.</li>\n	<li>Personal tour gears</li>\n	<li>Personal insurance</li>\n	<li>Expenses incurred due to flight delays or cancellation, road blockade, political strikes, natural disaster or anything that is beyond our control.</li>\n	<li>Tips for guide</li>\n</ul></p>',NULL,NULL,NULL,'/assets/images/pasupatinath-night-300x185.jpg',2,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(20,16,'Halesi Tour','halesi-tour','Among the most ancient and holiest places of Nepal, it is very popular as The Pashupatinath of the eastern Nepal. It is situated at the hilly region of the country in between the holy rivers Dudh…','<div class=\"sec-title clearfix\">\n<h2 class=\"heading-text\"> </h2>\n</div>\n<div class=\"post-desc\">\n<p>Among the most ancient and holiest places of Nepal, it is very popular as The Pashupatinath of the eastern Nepal. It is situated at the hilly region of the country in between the holy rivers Dudh Koshi to the right and Sunkoshi to the left. The temple is situated at the top of a small hill inside a beautiful cave. There lie other numerous small beautiful caves too. Importance. Here, the image of the god is inside the cave, which is full of natural beauty. Inside the cave is dark and there are bats flying here and there. It is also a kind of pride for the people living there, as it is as famous as other temples like the Pashupatinath, the Lumbini etc. even internationally. It is the natural cave, which lies in 4th remote hilly region and is believed to be in existence since 6000 years. It is the place full of natural beauty and cultural inheritance. It is popular among the Hindus as well as the Buddhists all over the world</p>\n<p>Lord Vishnu was the first ever devotee to pay homage to the Haleshi Mahadeva in the Satya Yuga, the golden age where as Balaram did in the third age called Dwapar Yuga. Afterwards, many kings, sages, devotees, philosophers, thinkers, hermits, abbots, ascetics and shankaracharya have been paying homage to this sacred place.</p>\n<p>During the homage hours, kettledrum, cymbal, clarinet etc, there is a custom of performing special ceremonial rites of the Haleshor Mahadeva during some festivals such as Bala Chaturdashi, Shiva Ratri, Ram Nawami and Teez etc. In between, devotees perform various other religious performances like fire sacrifice and recitals of the Rudri, the Chandi and the Vedas, our religious epics, burning of 10 millions holy threads and offering millions of wood apple leaves etc. The Haleshwor Mahadeva is taken as the god of fulfilling wishes and giving boons to the real devotees. So devotees vow solemnly and act accordingly as their wishes has been fulfilled.We believe this is only the place for the people all over the world to visit once in a life time and watch the beautiful, mysterious amazing and purely religious place where the people are traditionally rich in their culture.</p>\n<p><strong>Program</strong></p>\n<p><strong>Day 01: Arrival in Kathmandu</strong></p>\n<p>You will meet our representative from Adventure Specialist Travel at the Tribhuwan International airport, holding your name plate in front of the arrival gate. After meeting you will be drop at your hotel in Kathmandu. Remaining free time there is an option to explore the place near your hotel.</p>\n<p><strong>Day 02: Kathmandu Sightseeing</strong></p>\n<p>Today after breakfast we will be introduced to our local tour guide and start a guided tour to several of the most historical and spiritual attractions in Kathmandu.</p>\n<p><strong>Sightseeing places</strong></p>\n<ul>\n	<li><strong>Pashupatinath Temple: </strong>This temple is situated 5 km east of Kathmandu, the temple of Lord Shiva; Pathupatinath with two tired golden roof and silver doors is considered one of the holiest shrines of Hindus.</li>\n	<li><strong>Boudhanath Stupa</strong>:This Stupa lays 8kms east of Kathmandu. This ancient colossal Stupa is one of the biggest in the world and the center of Buddhism in the world. It was listed in the UNESCO Heritage Monument in 1979.</li>\n	<li><strong>Swoyambunath Stupa</strong>: Swoyambhunath Stupa, atop the hillock is one of the holiest Buddhist sites in Nepal enlisted in the World Heritage Site.</li>\n	<li><strong>Durbar Square </strong>:Later proceed for city tour of Kathmandu visiting <strong>Durbar Square</strong>, complex of palaces, courtyard and temples, built between the 12th and 18th centuries, use to be the seat of the ancient Malla kings of Kathmandu.</li>\n</ul>\n<p>In the afternoon, there will be a pre-trip discussion where we can meet our tour leader and other team members and over night in Kathmandu.</p>\n<p><strong>Day 03: Drive to Halesi</strong></p>\n<p>Wake up early in the morning have breakfast and get ready to drive to Halesi Mahadev. It is around 325 kilometers from Kathmandu to Halesi Mahadev. It will take around 11 - 12 hours to reach to Halesi Mahadev. We will drive from Kathmandu via Dhulikhel, Nepalthok, Khurkot all the way to Ghurmi, Okhaldhunga, Jayaram ghat to Halesi. Upon reaching Halesi check in at guest house. Overnight at Halesi.</p>\n<p><strong>Day 04: Visit around Halesi</strong></p>\n<p>Breakfast in the lodge at early morning. Then drive further short distance to reach Haleshi Mahadev. Reaching temple, perform puja and have darshan with visiting temples, caves and different self built entry-pass (dwar) inside Haleshi Mahadev Temple. Overnight at Haleshi in local hotel.</p>\n<p><strong>Day 05: Drive Back to Kathmandu</strong></p>\n<p>Wake up early in the morning have breakfast and get ready to drive to Halesi Mahadev. We take same route to back and drop you to your hotel at Kathmandu.</p>\n<p><strong>Day 06: City tour of Bhaktapur and Patan</strong></p>\n<p>Today you are going to explore Bhaktapur and Patan Durbar Square. After taking breakfast you will be guided around Bhaktapur and Patan.</p>\n<p><strong>Patan Durbar Square</strong> is situated at the centre of the city of Lalitpur in Nepal. It is one of the three Durbar Squares in the Kathmandu Valley, all of which are UNESCO World Heritage Sites. One of its attraction is the ancient royal palace where the Malla Kings of Lalitpur resided. There are many temples and idols in the area. The main temples are aligned opposite of the western face of the palace.  The Square also holds old Newari residential houses. </p>\n<p><strong>Bhaktapur</strong> literally translates to <strong>Place of devotees. </strong>Bhaktapur has the best preserved palace courtyards and old city center in Nepal, and is listed as a World Heritage Site by UNESCO for its rich culture, temples, and wood, metal and stone artworks. It is the home of traditional art and architecture, historical monuments and craft works, magnificent windows, pottery and weaving industries, excellent temples, beautiful ponds, rich local customs, culture, religion, festivals, and musical mystic and so on. Bhaktapur is still an untouched as well as preserved ancient city that is itself a world to explore for tourists. After Visiting Bhaktapur drive back to Kathmandu.</p>\n<p><strong>Day 07: Departure</strong></p>\n<p>Our representative from Adventure Specialist Travel will pick you from your hotel and drop you to Tribhuvan International Airport or spare some quality days to visit Bhutan or India or Tibet or Myanmar.</p>\n<p><strong>Above cost includes:</strong></p>\n<ul>\n	<li>Airport picks up and drops.</li>\n	<li>guided sightseeing with entrance fee in private vehicle as per itinerary</li>\n	<li>Accommodation with breakfast daily</li>\n	<li>English speaking tour guide </li>\n</ul>\n<p><strong>Above cost excludes:</strong></p>\n<ul>\n	<li>International flight</li>\n	<li>Visa to Nepal</li>\n	<li>Daily Lunch or dinner</li>\n	<li>Expenses of personal nature such as beverage bills, laundry bills, phone bills etc.</li>\n	<li>Personal tour gears</li>\n	<li>Personal insurance</li>\n	<li>Expenses incurred due to road blockade, political strikes, natural disaster or anything that is beyond our control.</li>\n	<li>Tips for guide</li>\n</ul>\n</div></p>',NULL,NULL,NULL,'/assets/images/nepal-cover.jpg',3,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(21,16,'Kathmandu Tour','kathmandu-tour','Kathmandu city is the capital city of Nepal, Located in the foothills of the Himalayas. This city is cultural center of Nepal is framed for its natural beauty and historic places. It is the most…','Kathmandu city is the capital city of Nepal, Located in the foothills of the Himalayas. This city is cultural center of Nepal is framed for its natural beauty and historic places. It is the most popular sightseeing tours in Nepal.</p>\n<p>The Kathmandu Valley World Heritage property is inscribed as seven Monument Zones. These monument zones are the Durbar squares or urban centers with their palaces, temples and public spaces of the three cities of Kathmandu (Hanuman Dhoka), Patan and Bhaktapur, and the religious ensembles of Swayambhu, Bauddhanath, Pashupati and Changu Narayan. The religious ensemble of Swayambhu includes the oldest Buddhist monument (a stupa) in the Valley; that of Bauddhanath includes the largest stupa in Nepal; Pashupati has an extensive Hindu temple precinct, and Changu Narayan comprises traditional Newari settlement, and a Hindu temple complex with one of the earliest inscriptions in the Valley from the fifth century AD. The unique tiered temples are mostly made of fired brick with mud mortar and timber structures. The roofs are covered with small overlapping terracotta tiles, with gilded brass ornamentation. The windows, doorways and roof struts have rich decorative carvings. The stupas have simple but powerful forms with massive, whitewashed hemispheres supporting gilded cubes with the all-seeing eternal Buddha eyes.</p>\n<p><strong>Tour Highlights</strong></p>\n<ul>\n	<li>Trip Duration: 7 days 6 nights</li>\n	<li>Starts Point: Kathmandu</li>\n	<li>Destination:  Around Kathmandu , Nagarkot,  Patan, Bhaktapur, Namobuddha and Bungmati</li>\n	<li>Ends Point: Kathmandu</li>\n	<li>Accommodation: Lodge</li>\n	<li>Transportation: Private Vehicle</li>\n</ul>\n<p><strong>Program </strong></p>\n<p>Day 01: Arrival in Kathmandu and transfer to hotel</p>\n<p>Day 02:City tour of Kathmandu</p>\n<p>Day 04:Hike to namo budha and drive back to Bhaktapur</p>\n<p>Day 03:Drive to Nagarkot for Sunrise and Sunset view</p>\n<p>Day 05: Bhaktapur Visit drive back to kathamndu</p>\n<p>Day 06: City tour of Patan, Bungmati and Khokana village</p>\n<p>Day 07:Departure or spare some quality days to visit Bhutan or Tibet or India or Myanmar.</p>\n<p><strong><u> </u></strong></p>\n<p><strong>Above cost includes:</strong></p>\n<ul>\n	<li>Airport picks up and drops.</li>\n	<li>guided sightseeing with entrance fee in private vehicle as per itinerary</li>\n	<li>Accommodation with breakfast daily</li>\n	<li>English speaking trek guide </li>\n</ul>\n<p><strong>Above cost excludes:</strong></p>\n<ul>\n	<li>International flight</li>\n	<li>Visa to Nepal</li>\n	<li>Daily Lunch or dinner</li>\n	<li>Expenses of personal nature such as beverage bills, laundry bills, phone bills etc.</li>\n	<li>Personal  gears</li>\n	<li>Personal insurance</li>\n	<li>Expenses incurred due to  road blockade, political strikes, natural disaster or anything that is beyond our control</li>\n	<li>Tips for guide  </li>\n</ul></p>',NULL,NULL,NULL,'/assets/images/nepal-cover.jpg',4,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(22,15,'Peak Climbing','peak-climbing','Peak Climbing in Nepal is adventurous. Nepal is a country of mountains and Himalayas that surrounds. It has got 33 Himalayas summit weighing up to 6000meters where you can take pleasure of both…','<p>Peak Climbing in Nepal is adventurous. Nepal is a country of mountains and Himalayas that surrounds. It has got 33 Himalayas summit weighing up to 6000meters where you can take pleasure of both trekking and peak climbing. Trekking and Peak climbing is the most enjoyable and adventurous things to do among all the adventure lovers and nature admirers of the world. In order to make the program more advantageous more than 33 minor trekking peaks for Alpine climbing continued under Nepal Mountaineering Association .For climbing these mountains one should take certain permission and an experienced Climbing guide from the certified trekking agencies. There is no need of previous experience to climb these mountains rather one should be mentally and physically prepared to explore this speculating climb.</p>\n<p>Adventure Nepal Eco Trekking provide mere embodied and beneficial service as we consider the Adventure travelers. We are fully ready to offer every kind of help during the time of climbing peaks and acquiring permissions. There is provision of high altitude climbing assistants, porters and cooks in our team. Your assortment is made in such a manner that we are prepared to accept your every details as per your will and time schedule.</p>\n<h2>Group ‘A’ NMA Peaks</h2>\n<table border=\"0\" width=\"523\" cellspacing=\"1\" cellpadding=\"0\">\n<tbody>\n<tr>\n<th valign=\"top\" width=\"55\">\n<p>S.N.</p>\n</th>\n<th valign=\"top\" width=\"144\">\n<p>Name</p>\n</th>\n<th valign=\"top\" width=\"72\">\n<p>Altitude</p>\n</th>\n<th valign=\"top\" width=\"120\">\n<p>Region</p>\n</th>\n<th valign=\"top\" width=\"132\">\n<p>Location</p>\n</th>\n</tr>\n<tr>\n<td valign=\"top\" width=\"55\">\n<p>1<br />\n 2<br />\n 3<br />\n 4<br />\n 5<br />\n 6<br />\n 7<br />\n 8<br />\n 9<br />\n 10<br />\n 11<br />\n 12<br />\n 13<br />\n 14<br />\n 15</p>\n<p>&nbsp;</p>\n</td>\n<td valign=\"top\" width=\"144\">\n<p>Mt. Cholatse<br />\n Mt.Machermo<br />\n Mt. Kyazo Ri<br />\n Mt. Phari Lapcha<br />\n Mt. Nirekha<br />\n Mt. Langsisa Ri<br />\n Mt. Ombigaichen<br />\n Mt. Bokta<br />\n Mt. Chekigo<br />\n Mt. Lobuje west<br />\n Mt. Larkya peak<br />\n Mt. ABI<br />\n Mt. Yubra Himal<br />\n Mt. Chhukung Ri<br />\n Mt. Yala peak</p>\n</td>\n<td valign=\"top\" width=\"72\">\n<p>6440 m<br />\n 6273 m<br />\n 6186 m<br />\n 6017 m<br />\n 6159 m<br />\n 6427 m<br />\n 6340 m<br />\n 6143 m<br />\n 6257 m<br />\n 6145 m<br />\n 6010 m<br />\n 6097 m<br />\n 6035 m<br />\n 5550 m<br />\n 5732 m</p>\n</td>\n<td valign=\"top\" width=\"120\">\n<p>Khumbu<br />\n Mahalangur<br />\n Mahalangur<br />\n Mahalangur<br />\n Mahalangur<br />\n Jugal<br />\n Mahalangur<br />\n Kanchenjunga<br />\n Gaurishankar<br />\n Khumbu<br />\n Manaslu<br />\n Mahalangur<br />\n Langtang<br />\n Himal<br />\n Khumbu<br />\n Langtang</p>\n</td>\n<td valign=\"top\" width=\"132\">\n<p>North east<br />\n North east<br />\n North east<br />\n North east<br />\n North east<br />\n North east<br />\n North east<br />\n Far north east<br />\n Central east<br />\n Far north east<br />\n West</p>\n<p>North east</p>\n<p>Far north east<br />\n North east</p>\n</td>\n</tr>\n</tbody>\n</table>\n<p>&nbsp;</p>\n<h2>Group ‘B’ NMA peaks</h2>\n<table border=\"0\" width=\"655\" cellspacing=\"1\" cellpadding=\"0\">\n<tbody>\n<tr>\n<th valign=\"top\" width=\"55\">\n<p>S.N.</p>\n</th>\n<th valign=\"top\" width=\"228\">\n<p>Name</p>\n</th>\n<th valign=\"top\" width=\"96\">\n<p>Altitude</p>\n</th>\n<th valign=\"top\" width=\"144\">\n<p>Region</p>\n</th>\n<th valign=\"top\" width=\"132\">\n<p>Location</p>\n</th>\n</tr>\n<tr>\n<td valign=\"top\" width=\"55\">\n<p>1<br />\n 2<br />\n 3<br />\n 4<br />\n 5<br />\n 6<br />\n 7<br />\n 8<br />\n 9<br />\n 10<br />\n 11<br />\n 12<br />\n 13<br />\n 14<br />\n 15<br />\n 16<br />\n 17<br />\n 18</p>\n</td>\n<td valign=\"top\" width=\"228\">\n<p>Chulu West<br />\n Chulu West<br />\n Mera Peak<br />\n Khongma Tse(Mera Peak)<br />\n Singuchuli (Fluted Peak)<br />\n Khusum Kangru<br />\n Huinchuli<br />\n Pharchemuche<br />\n Kwangde<br />\n Imja Tse (Island Peak)<br />\n Lobuje<br />\n Pisang Peak<br />\n Ramdung Peak<br />\n Paldor Peak<br />\n Ganjala Chuli (Naya Kanga)<br />\n Pokhalde Peak<br />\n Mardi Himal<br />\n Tharpu chuli (Tent Peak)</p>\n</td>\n<td valign=\"top\" width=\"96\">\n<p>6,419 m<br />\n 6,584 m<br />\n 6,654 m<br />\n 5,849 m<br />\n 6,501 m<br />\n 6,367 m<br />\n 6,441 m<br />\n 6,187 m<br />\n 6,011 m<br />\n 6,160 m<br />\n 6,119 m<br />\n 6,091 m<br />\n 5,925 m<br />\n 5,896 m<br />\n 5,844 m<br />\n 5,806 m<br />\n 5,587 m<br />\n 5,663 m</p>\n</td>\n<td valign=\"top\" width=\"144\">\n<p>Manang<br />\n Manang<br />\n Khumbu Himal<br />\n Khumbu Himal<br />\n Annapurna Himal<br />\n Khumbu Himal<br />\n Annapurna Himal<br />\n Rolwaling Himal<br />\n Khumbu Himal<br />\n Khumbu Himal<br />\n Khumbu Himal<br />\n Manang<br />\n Rolwaling Himal<br />\n Langtang Himal<br />\n Langtang Himal<br />\n Khumbu Himal<br />\n Annapurna Himal<br />\n Annapurna Himal</p>\n</td>\n<td valign=\"top\" width=\"132\">\n<p>Centre-west<br />\n Centre-west<br />\n East<br />\n East<br />\n Centre-west<br />\n East<br />\n Centre-west<br />\n Centre-west<br />\n East<br />\n East<br />\n Centre-west<br />\n Centre-west<br />\n Centre<br />\n Centre<br />\n East<br />\n Centre-west<br />\n Centre-west</p>\n</td>\n</tr>\n</tbody>\n</table>\n<p>Note: Maximum number of members in a team is 12.</p></p>',NULL,NULL,NULL,'/assets/images/destinations/DSC00475.jpg',1,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(23,22,'Meera Peak Climbing','meera-peak-climbing','Mera peak is placed in the east of Khumbu trekking trail of Everest region. It is somewhat challenging and for the first timers it can be the exhilarating experience. Though the climbing here does…','Mera peak is placed in the east of Khumbu trekking trail of Everest region. It is somewhat challenging and for the first timers it can be the exhilarating experience. Though the climbing here does not require technical knowledge but you should have good immunity to adapt in such a high altitude of 6,654m and some preliminary skill concerning climbing instruments such as ice axe and crampons.the trial winds in the original Everest expedition route from Jiri. We cross high ridges and enthralling deep gorges in Everest region the native soil of legendary climbers ‘Sherpas’ before entering to the isolated wilderness of Hinku Valley. Annually 700 foreigners make an attempt to climb Mera peak which demands preliminary mountaineering experience and a special permit from Nepal Mountaineering Association. J.O.M Roberts, Sir Edmund Hillary and Tenzing Norgay where the first masters who got victory over Mera peak in 20 May 1953.</p>\n<p>Before we start our climb to Mera peak we organize a basic climbing course instructed by professional sherpa climbers such that all of our climbers have basic climbing knowledge so they get confidence to get triumph over the summit. In the weather condition is good we can climb the peak and descend back in the same day. From the pinnacle of Mera peak we can view the outstanding view of Everest, Lhotse, Makalu, Kanchanjunga and Cho Oyu. Mera peak climbing is a complete tented camping trek where our kitchen staffs will serve you with fresh, hygienic and delicious food.   </p>\n<h2>Fact File</h2>\n<p><em>Elevation: </em>6,654m/21,825 ft.</p>\n<p><em>Region:</em> Everest/ Khumbu Himal</p>\n<p><em>The Route:</em> KTM- Lukla- Mera Peak Base Camp</p>\n<p><em>Best Season:</em> Sept-Nov. &amp; April to june.</p>\n<p><em>Duration:</em> 17 Days</p>\n<p><em>Trek type:</em> Camping+Teahouse</p>\n<p><em>Max Altitude:</em> 6654 m.</p>\n<p><em>Mode of Travel:</em> Flight</p>\n<p><em>Grade:</em> Adventure Climbing</p>\n<p><em>Duration:</em> 18 days</p>\n<p>&nbsp;</p>\n<p style=\"text-align: center;\"><span style=\"font-size: 24pt;\"><strong>Program</strong></span></p>\n<p style=\"text-align: left;\"> </p>\n<p><strong><em>Day 01: </em></strong>You will be transferred to your hotel room after receiving you from airport. Spend overnight at hotel.</p>\n<p><strong><em>Day 02: </em></strong>After having breakfast we will do some sightseeing which includes Pashupatinath, Swoyambhunath and Bouddhanath.</p>\n<p><strong>Day 03: </strong>Experience a 35minutes scenic flight to Lukla. After landing there you will have enough time to walk around while the camp is being set up. After camp is being setup have lunch and explore the area and observe traditional Sherpa lifestyle. Overnight at tented camp.</p>\n<p><strong>Day 04: </strong>Trek to Chutanga (3,430m). Our first day of trekking is quite easy which takes us to eastwards. Passing through number of villages and dense forests we come across Nau Lekh also known as Kalo Himal Ridge. On this portion we will closely follow our guide as there are number of paths leading away from the main trail. The whole area is known as Chutanga which literally means summer pasture. Overnight at tented camp.</p>\n<p><strong>Day 05</strong><em>: </em>Today we will trek for around five to six hours from Chutanga to reach Tuli Kharka. We begin our walk with the steep climbing to cross Kalo Himal Ridge in Nau Lekh Range which separates Khumbu valley from Hinku Valley. Further uphill climbing will bring us to the small pass called Zatrwa Og(4450m), from here the path transeverses a boulder slope, rounds a corner and climbs once again to the Zartwa La at an altitude of 4600m. in fine weather the one can witness the outstanding vista across the Dudh Koshi towards Karyolung and Lumding Himal and in foothills of Hinku Valley. From here we will climb downhill for less than hour that will bring us to large boulder at Tuli Kharka where we will spend overnight.</p>\n<p><strong>Day 06</strong><em>: </em>Trek to Mausan Kharka (3430m). Trek for about 3 to 4 hours from Tuli Kharka to get Mausam Kharka. We have a short trek on a downhill slope where we can see the terrific vista of Peak 43 and Kusum Kanguru before we reach to Hinku valley from where we can see the majestic view of South face of Mera Peak. Continuing the walk we drop steeply into the Hinku valley. A pleasant and fine walk through the Himalayan Pine and Rhododendron forest take us to Mausam Kharka by Hinku Drangka River and overnight at tented camp.</p>\n<p><strong>Day 07:</strong><em> </em>From Mausan Kharka trek toThagnan(4360m) which takes around 5 to 6 hours. We walk along the west bank of Hinku Drangka eventually leaving the forests. We cross the small bridge to reach Gondishung(4350m) which is the summer settlement of Thagnag. Gondishung has a enthralling 200 year old monastery beneath a rock overhang. The trek continues for another hour passing Lungasamba as the valley narrows between the flanks of Kusum Kanguru(6369m) to the west and shortened far western peak of Meera(6255m). Finally we reach at Thagnag, which is a small settlements made by Yak herders. Here we find few tea house cartering the needs of travelers and porters.</p>\n<p><strong>Day 08</strong><em>: </em>Today we acclimatize at Thagnan and explore the area. We too can do some local hikes in these stunning peaks especially Peak 43 which rises to 6769. In the north of the camp there is moraine behind where is beautiful glacial lake known as Sabai Tsho into which plummets the hanging Sabai Glacier.</p>\n<p><strong>Day 09: </strong>Trek to Khare(5000m) which takes 4 to 5 hours via Charpatti Tal, Dig Kharka.</p>\n<p><strong>Day 10 : </strong>Trek to Meera High Camp(5800m) which takes 5 to 6 hours. The path is zigzag which bring us to the Meera Glacier. From here, we must use crampons for 15 minutes to climb the 30 to 35 degree ice to reach the plateau that leads us to Meera La. From Meera La, we continue our trek for another 3 hours which take us to High Camp beneath Meera Peak. From here, one can see the spectacular vista of Makalu, Everest, Nuptse. If the weather is fair from High Camp, we will have the panorama of Kanchanjunga in the far east. Overnight camping at High Camp.</p>\n<p><strong>Day 11: </strong>Early in the morning after having breakfast, we will conquer the summit of Meera(6476m) . Though the distance does not look far the climb requires much of a hard work and all the preparation and positive attitude will pay off here. It takes 4 to 6 hours for summit. For the summit, we start to trek from 2 am to 5 am in the morning. As the sun rises we can see the incredible vista across to Baruntse(7129m) , Nau Lekh(6360m) and Makalu(8481m). After conquering the summit, we climb down to Khare. The exact schedule depends on many factors including the weather, condition of the route and condition of the members.</p>\n<p><strong>Day 13: </strong>Today is another day for ice climbing and spend one more night in the village on the way back to Lukla.</p>\n<p><strong>Day 14: </strong>After a successful expedition on Meera Peak we climb down through Hinku valley to Gothey(3600m). On the way, we can see the panoramic vista of Himalayan valley and majestic mountains. Overnight at Gothey in the camp.</p>\n<p><strong>Day 15: </strong>Trek to Tuli Kharka(4250m). Early in the morning after having breakfast, we climb uphill through the lush forest on the west side of Hinki to the Valley of Tuli Kharka. Overnight at camping.</p>\n<p><strong>Day 16: </strong>Trek to Lukla(4600m). After having breakfast, we climb uphill to the top of Zatrwa La and climb downhill to the village of Lukla. Overnight at teahouse in Lukla.</p>\n<p><strong>Day 17: </strong>Fly back to Kathmandu.</p>\n<p><strong>Day 18: </strong>Departure for your onward flight.</p></p>',NULL,NULL,NULL,'/assets/images/cover-all.jpg',0,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(24,22,'Island Peak Climbing','island-peak-climbing','Island peak climbing is the most popular trekking peak in Everest region Khumbu Himalaya of Nepal; it’s imposing and extremely glaciated west face that rises from Lhotse Glacier. The peak is itself a…','<b>Island peak climbing</b> is the most popular trekking peak in Everest region Khumbu Himalaya of Nepal; it’s imposing and extremely glaciated west face that rises from Lhotse Glacier. The peak is itself a south part of Lhotse shar divided by a small col. Though re-baptized as Imja Tse in 80s it is popular by its original name. It got its name in 1952 AD because of its placement in the middle of Chukung valley giving appearance like an island in a sea of ice. It is located in the top of Chukung valley between Ama Dablan and Lhotse Mountains at an altitude of 6,189m. The most challenging section of this climb is ice wall at slope of 45 degrees which is followed by slender summit ridge.</p>\n<p>One full day walking from Chunking will lead to Base Camp and get prepared to climb the peak. To get victory over the summit it will take one or two days depending upon the weather conditions. From the summit we can view the outstanding mountain panorama of Mt Everest, Lhotse, Nuptse and Makalu with Hodgepodge of many others. Climbing Island peak is comparatively easy and common due to which many visitors desire to go there. Your<b> island peak expedition</b> begin from Lukla uphill to island peak top and walking back at Lukla from here you will fly back to Kathmandu.</p>\n<p>&nbsp;</p>\n<h2>Fact File</h2>\n<p>Region Everest Khumbu valley (6189m.)</p>\n<p>Best Season: Sept. to Nov. &amp; March - June</p>\n<p>Duration: 14 Days</p>\n<p>Trek type:  Tea House+Camping</p>\n<p>Max Altitude: 6189 m.</p>\n<p>Mode of Travel: Flight</p>\n<p>Grade: Strenuous</p>\n<p>Duration: 16 days</p>\n<p>&nbsp;</p>\n<p style=\"text-align: center;\"><span style=\"font-size: 24pt;\"><strong>Program</strong></span></p>\n<p style=\"text-align: left;\"> </p>\n<p><strong>Day 01: </strong>From Tribhuban International Airport you will be transferred to your hotel room. In the afternoon, we will invite you to our office for briefing about the each day program.</p>\n<p><strong>Day 02:</strong> After having breakfast we will do some sightseeing which includes Pashupatinath, Swoyambhunath and Bouddhanath.</p>\n<p><strong>Day 03: </strong>Enjoy the most scenic 30minutes flight to Lukla from Kathmandu. As you reach Lukla start the Everest Base Camp Trek to Phakding via Chaurikharka and Chhuplung. Overnight at Phakding(2640m).</p>\n<p><strong>Day 04: </strong>Early in the morning after having breakfast trek to the Sherpa capital of Namche Bazaar(3435m) via Jhorsalle. From Namche we can see the first glance of Everest.</p>\n<p><strong>Day 05: </strong>Today we will acclimatize at Namche Bazaar. Today we may rest or hike through the village of Khunde and Khumjung. Khumjung is the largest village of Khumbu region. After having lunch we will hike back to Namche Bazaar.</p>\n<p><strong>Day 06: </strong>Trek to Tengboche(3890m) via Sanasa and Fungethaga. We will have our lunch at the edge of Dudhkoshi river. From Tengboche we can see the captivating vista of Gokyo Ri, Amadablam, Thamserku and Island Peak. Tengboche is known for the highest monastery in the world.</p>\n<p><strong>Day 07: </strong>Trek to Dingboche (4450m). After having breakfast we leave for Dingboche via Deboche village, Minlinggo, Pangboche and Imjastse. Thoughout the trail we can see the spectacular vista of Ama Dablam, Island Peak, Kantega, Nuptse and Lhotse. Dingboche is a beautiful village enclosed by stone wall. Overnight at teahouse.</p>\n<p><strong>Day 08: </strong>Today we acclimatize at Dingboche. From Dingboche we can see some breathtaking views of North face of Ama Dablam and Lhotse-Nuptse ridge as we explore the valley that take us to Island peak. Another option can be hike to Nagarjun hill from where we can see the vista of Island peak with many others.</p>\n<p><strong>Day 09:</strong> Trek for 4 hours to get to Chhukung Valley. Overnight at Chhukung.</p>\n<p><strong>Day 10:</strong> Trek from Chhukung Valley to Island Base Camp.</p>\n<p><strong>Day 11:</strong>  Climb to Island peak and trek down to Dingboche.</p>\n<p><strong>Day 12: </strong>Trek from Dingboche to Tengboche.</p>\n<p><strong>Day 13: </strong>Trek from Tengboche to Manjoo (2900m). Walk downhill cross the bridge near Phungitenga near Sahansa. The trail from Namche to Manjoo is one of the most scenic path in the whole trail. In the way we will visit traditional village of Khumjung and Khunde. Overnight at Manjoo.</p>\n<p><strong>Day 14: </strong>Trek from Manjoo to Lukla (2886m). Today the trek will be quite easy except some uphill climbs and then down to Bhote Koshi River crossing it three times.</p>\n<p><strong>Day 15: </strong>Fly from Lukla to Kathmandu.</p>\n<p><strong>Day 16:</strong> Departure for your onward flight.</p></p>',NULL,NULL,NULL,'/assets/images/cover-all.jpg',1,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(25,22,'Pisang Peak Climbing','pisang-peak-climbing','Pisang peak is relatively one of easy climbing peaks and is the most popular one in the Annapurna region. Among the peaks of Nepal, Pisang demands for technical knowledge about climbing. It is on the…','Pisang peak is relatively one of easy climbing peaks and is the most popular one in the Annapurna region. Among the peaks of Nepal, Pisang demands for technical knowledge about climbing. It is on the way to the highest pass of the world and offers the spectacular expedition for adventure lovers. The western portion of the mountain is protected by draped glacier and the end of the ridge has ice blocks making the climb challenging. The first successful climb over Pisang was done in 1955 by a German team. The climb starts from Pisang village and the path which is sparsely forested and is pastured ultimately leads us to Kharka(4,380m) which the best location for setting base camp. High camp will be placed at an altitude of 5,400m on one arm of west ridge. From the end of November to the end of March high camp will be covered by snow. This slender ridge at the west which is followed by steep and challenging snow slopes ultimately lead us to summit.Pisang peak is usually considered as sightseeing peak which bestows climbers miraculous view of Annapurna associates including Tilicho peak, Annapurna II, Annapurna IV, Gangapurna and Glacier dome.</p>\n<p>After a successful victory over the Pisang peak we will return back through the same route. We will continue our trek to Manang valley and further up to Thorang fedi. Next morning we will cross Thorang La pass and reach to the sacred Muktinath. From Muktinath we will do downhill trek to beautiful village of Jharkot, Kagbeni which is a door to Upper Mustang and reach Jomsom which is capital of Mustang. Jomsom has a small airstrip on the bank of Kaligandaki River from where we will take our morning flight back to Pokhara.</p>\n<h2>Fact File</h2>\n<p>Destination: Pisang Peak</p>\n<p>Elevation: 6,091m</p>\n<p>Region: Annapurna/ Manang valley</p>\n<p>Route: Kathmandu-Pokhara-Beshishahar - Pisang</p>\n<p>Best season: Sept. to Nov. &amp; April to june</p>\n<p>Facility: Teahouse lodges- on the way of trekking route &amp; camping in the period of climbing</p>\n<p>Duration: 21 Days</p>\n<p style=\"text-align: center;\"><span style=\"font-size: 24pt;\"><strong>Program</strong></span></p>\n<p>Day 01:From Tribhuban International Airport you will be transferred to your hotel room. In the afternoon we will invite you to our office for briefing about the each day program.</p>\n<p>Day 02:After having breakfast we will do some sightseeing which includes Pashupatinath Swoyambhunath and Bouddhanath.</p>\n<p>Day 03:Drive from Kathmandu to Besisahar. It takes around 7 to 8 hours from the starting point of the trek. Overnight at guesthouse in Beshisahar.</p>\n<p>Day 04:Trek for around five to six hours for Bahundanda. The walk involves crossing few suspension bridge, waterfalls and across rice field and sub tropical forest. You eventually ascend to Bahundanda for overnight. Bahundanda is a small village set on a long ridge at 1310m,</p>\n<p>Day 05:Trek to Chamje (1430m) which takes 5-6hours. After having breakfast we trek downhill passing different villages, forest, suspension bridge over Marshyangdi River and get to Jagat where we have our lunch. After having lunch trek for one and half hour to reach Chamje. Spend overnight at Chamje in guesthouse.</p>\n<p>Day 06:Trek to Dharapani (1950m) which takes 5-6 hours. Crossing the suspension bridge over Marshyangdi River we left Chamje and left Manang district. After walking uphill and crossing Tal through the cliffy way right above the river and reach Dharapani. Overnight at guesthouse.</p>\n<p>Day 07:Trek from Dharapani to Chame(2630m) which takes for around 5 to 6 hours. In the trail you can observe ironic landscapes along with the mind blowing vista of Himalaya’s. Chame is the districts headquarter of Manang which offers the spectacular vista of Mt Lamjung and Annapurna II. Overnight at guesthouse.</p>\n<p>Day 08:Today we will climb a steep uphill to Upper Pisang (3,700m) which takes around 5-6 hours. As the trail opens up you will be surrounded by Himalayan Peaks all the way to Pisang. From Pisang you have to climb another half an hour towards a big hill for Upper Pisang. Overnight at Guesthouse.</p>\n<p>Day 09:Today we rest and get acclimatized. Whole day you will be bestowed by the magnificent vista of Annapurna, Gangapurna and Tilicho.</p>\n<p>Day 10:Today we will trek to Pisang Peak Base Camp (4,380m) after resting a day in Upper Pisang which takes around 3 to 4 hours. From Upper Pisang the path is uphill which passes through the sparse woods and pasture to the Kharka at an altitude of 4380m. Kharka is the best place for setting camp as it is in flat section along the trail. Overnight at tent.</p>\n<p>Day 11:Today we will trek for around 4 -5 hours to Pisang Peak (5400m). We set our camp after climbing the shoulder on the south west ridge hich will be covered by snow from the end of November to March. Overnight at tent.</p>\n<p>Day 12:Today we will trek to the summit6091m) of Pisang peak and climb back to the base camp. We will trek for 7 to 9 hours. After successful ascend to summit we will walk down to the base camp. Overnight at tent.</p>\n<p>Day 13:Today from Pisang Peak Base Camp we will trek to Manang valley (3450m) which takes for around 5 to 6 hours via Pisang village walking across the riverside. Overnight at guesthouse in Manang.</p>\n<p>Day 14:Trek to Yak Kharka(4110m) from Manang leaving the trail off to Tilicho Lake which takes around 3 to 4 hours. Yak Kharka is a small village. Overnight at guesthouse.</p>\n<p>Day 15:Today we will trek to Thorang Phedi(4600m) from Yak Kharka which takes 3 to 4 hours. Thorang Phedi is a small village catering the needs of trekkers and climbers. Overnight at guesthouse.</p>\n<p>Day 16:Cross Thorang La early in the morning and get to Muktinath which takes around 8 to 10 hours. Crossing Thorang La (5416m) pass will be a amazing as well as thrilling experience. The mountain vista seen from the trail and pass are outstanding. After crossing the pass walk downhill to another part of Annapurna and halt the walk at Muktinath (3800m). Overnight at guesthouse.</p>\n<p>Day 17:After visiting Muktinath Temple early in the morning we will walk downhill for around 3 to 4 hours to Kagbeni via Jharkot. Overnight at guesthouse.</p>\n<p>Day 18:Trek to Jomsom (2800m). Walk for around 3 to 4 hours through the sand bar of Kali Gandaki river we will be at Jomsom. Jomsom is head quarter of Mustang and Thakali people inhibit here. Overnight at guesthouse.</p>\n<p>Day 19:Early in the morning after having breakfast enjoy the scenic flight to Pokhara. In the afternoon you can explore Pokhara city. Overnight at hotel in Pokhara.</p>\n<p>Day 20:We will have a scenic drive from Pokhara to Kathmandu. Overnight at hotel in Kathmandu.</p>\n<p>Day 21:Departure for your onward flight.</p></p>',NULL,NULL,NULL,'/assets/images/cover-all.jpg',2,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(26,22,'Yala Peak Climbing','yala-peak-climbing','Yala Peak Climbing is the well known trekking peak in Langtang region in the north of Kathmandu valley. Placed at the height of 5,550m Yala peak is classified as an easy climbing peak suited for with…','\n<p>Yala Peak Climbing is the well known trekking peak in Langtang region in the north of Kathmandu valley. Placed at the height of 5,550m Yala peak is classified as an easy climbing peak suited for with good physical fitness.We will drive from Kathmandu to Dhunche or Syabru Besi and trek uphill for three days to the valley. We will make our base camp at the end of trial and a high camp a further half day trek beyond base camp in a meadow at an altitude of 4,800m. The last 400 m of the trek is on ice so we will carry ice axe, rope and crampons.</p>\n<p>The trek on Yala peak is often done as the warm up for Naya kanga which is situated on the other side of the valley. From the summit grants us the extravagant vista of, Langtang Lirung( 7,235m) , Lenpo Gang(7,063m) , Dorje Lakpa(6,975m), Ganesh Himal, Naya kagna, Gangchempo(6,388m) and the mighty Shishapangma(8,020m) along with the hodgepodge of many others.</p>\n<p>&nbsp;</p>\n<h2>Facts of File</h2>\n<p>Elevation      : 5,500m</p>\n<p>Region           : Langtang</p>\n<p>Duration       :13 days</p>\n<p>Best Season  : Sept. to Nov.&amp; April to May.</p>\n<p>Facility          : Tea house lodges &amp; camping while on climbing </p>\n<p>Duration       : 12 days</p>\n<p>&nbsp;</p>\n<p style=\"text-align: center;\"><span style=\"font-size: 24pt;\"><strong>Program</strong></span></p>\n<p style=\"text-align: center;\"> </p>\n<p><strong>Day 01:</strong> From Tribhuban International Airport you will be transferred to your hotel room. In the afternoon we will invite you to our office for briefing about the each day program.</p>\n<p><strong>Day 02:</strong> Early in the morning after having breakfast we will drive to Dhunche (2020m). While crossing Trishuli River we can see glimpse of Ganesh Himal.</p>\n<p><strong>Day 03:</strong> Trek to Lama hotel (2475m) via Syaphru Besi Ghopche Khola and Rimche. On the route if we are lucky we can see Red Pandas, Wild Monkey and Bear.</p>\n<p><strong>Day 04: </strong>Trek up to Langtang village (3,430m) via Ghora Tabela this is the head quarter of Langtang national park is located. In the trail we can see the glimpse of Langtang Lirung.</p>\n<p><strong>Day 05:</strong> We climb up slowly passing the dense forest and pasture land to Kyangjin (3,870m). Kyangjin has a vivid setting as it is surrounded by snow capped mountain from all side. From here we can see the panoramic vista of Dorje Lakpa, Langtang Lirung and Langtang Ri.</p>\n<p><strong>Day 06:</strong> Acclimatize at Kyangjin Gompa. Explore Kyangjin Ri and Tserko Ri as they offer the spectacular vista of Langtang range, Kinshung, Yansa Tsenji and the foot of Lirung Glacier.</p>\n<p><strong>Day 07:</strong> Trek to Yala Peak Base Camp (4800m).</p>\n<p><strong>Day 08:</strong> Climb to Yala Peak summit (5500m). Return back to Kyangjing Gompa.</p>\n<p><strong>Day 09:</strong> Trek to Lama hotel from Kyangjing following the Langtang Khola to Langtang village and to Ghora Tabela. After having lunch in Ghora Tabela we will climb down toLama Hotel.</p>\n<p><strong>Day 10: </strong>Trek downhill to Syabru Beshi (1480m). In Syabru Beshi there is hydro Project called Chilime power plant.</p>\n<p><strong>Day 11:</strong> Drive to Kathmandu from Syabru Besi bus. It takes nine hours.</p>\n<p><strong>Day 12:</strong> Departure for your onward flight.</p></p>',NULL,NULL,NULL,'/assets/images/yala-peak-summit-300x200.jpg',3,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(27,22,'Tharpu Chuli','tharpu-chuli-trek','Tharpu Chuli is placed at Annapurna Sanctuary in Annapurna Himal and the pet name Tent Peak was given by Jimmy Roberts in 1956. Tharpu chuli is situated at the hub of the Annapurna region at the…','Tharpu Chuli is placed at Annapurna Sanctuary in Annapurna Himal and the pet name Tent Peak was given by Jimmy Roberts in 1956. Tharpu chuli is situated at the hub of the Annapurna region at the height of 5,663m above the sea level. The original route winds around North West ridge ultimately leading to the summit; nevertheless it can also be climbed through South East Ridge as well as South West portion. Tent peak climb is followed by Annapurna Base camp trek which is the best.Tent peak is regarded as the ideal destination for the first timers who are panicked to start with high mountains. It is the fraction of the ridgeline and is placed in the south of the glacier dome.</p>\n<p>Tent peak acts as separator between the semicircles of peak wrapping the sanctuary. This climb offers panoramic view of Annapurna Himal along with glaciers, pass and moraines surrounded by some high peaks. The climb over Tent peak also bestows the travelers with unparalleled and undisturbed view of Annapurna Sanctuary.</p>\n<p>&nbsp;</p>\n<h2>Fact File</h2>\n<p>Destination               : Annapurna Region (5663m.)</p>\n<p>Maximum altitude  : 5663m.</p>\n<p>Season                       : Spring &amp; Autumn</p>\n<p>Transportation        : private car/Flight</p>\n<p>Duration                   : 17 Days</p>\n<p>Grade                        : Strenuous</p>\n<p>Duration                   : 17 days</p>\n<p>&nbsp;</p>\n<p style=\"text-align: center;\"><span style=\"font-size: 24pt;\"><strong>Program</strong></span></p>\n<p style=\"text-align: center;\"> </p>\n<p><strong>Day 01:</strong> From Tribhuvan International Airport you will be transferred to your hotel room. In the afternoon we will invite you to our office for briefing about the each day program.</p>\n<p><strong>Day 02:</strong> After having breakfast we will do some sightseeing in Kathmandu which includes Pashupatinath, Bouddhanath and Swoyambhunath.</p>\n<p><strong>Day 03:</strong> Take a 35 minutes scenic flight to Pokhara and trek to Dhampus (1700m). As we reach Pokhara we will take a bus ride to Phedi. From Phedi we start trekking in Annapurna mountain range. After walking for 3 hours we will be at Gurung village of Dhampus. Overnight at guesthouse.</p>\n<p><strong>Day 04:.</strong> Trek to Landrung(1550m) via Pothana and Deorali. Walking through the side of Modi Khola and witnessing spectacular views of Annapurna south and Huinchuli, we will trek to Landrung. Overnight at guesthouse.</p>\n<p><strong>Day 05:</strong> Trek to Chomrong (2040m). From Landrung the path is steep and passing through the villages, crossing the suspension bridge we will arrive to Jhinu where we have our drink or snacks. After having tea, we will trek downhill to Daaulu and continue the walk for five hours to Chomrong. From Chomrong, we can have compelling view of Machhapuchhare. Overnight at guesthouse.</p>\n<p><strong>Day 06: </strong>Crossing the Chomrong Khola we will continue our trek to steep stones passing the Rhododendron forest and witnessing the outstanding vista os Annapuran we will trek to Himalaya Hotel (2680m). During our five hour walk we cross Modi Khola and finally reach Himalaya Hotel.</p>\n<p><strong>Day 07: </strong>Trek to Machhapuchhare Base Camp (3480m) for 3 to 4 hours via Hinku Cave where we can find small lodge. Futher ahead we will pass through Deorali and Bagar and after that we arrive at the level and grassy moraine platform known as Machhapuchhare Base Camp. Therefore we set up camp in there.</p>\n<p><strong>Day 08: </strong>Trek to Annapurna Base Camp (3900m). Walking gently uphill to through the tranquil meadows to get Annapurna Base Camp. In the trail we can see the spectacular vista of majestic Himalayan peaks. After having trekked for 2 hours, we reach base camp. From there we can see the spectacular views of Annapurna I.</p>\n<p><strong>Day 09: </strong>Today we acclimatized at Annapurna base camp and enjoy the unparallel beauty of the towering peaks of Nepal.</p>\n<p><strong>Day 10: </strong>Trek to high camp, following the trail leading to Tent peak high camp. Struggling against the glaciated mountain passes we finally reach our target destination.</p>\n<p><strong>Day 11: </strong>Ascent of Tent Peak (5600m). Early in the morning after having breakfast we climb to the peak. After a very hardship ascent we finally reach to the summit of Tent peak. From the altitude of 5600m, we can see the miraculous vista of Annapurna range. After seeing this we return to Annapurna Base Camp.</p>\n<p><strong>Day 12: </strong>Trek back to Himalaya Hotel (2680m) which takes about 4 hours.</p>\n<p><strong>Day 13: </strong>Trek to Tadapani (2650m). After descending to the village of Khumnu and crossing the Khumnu Khola the trail lead us to the Melanche which ultimately takes us to Tadapani. From our campsite, we can see the excellent vista of Annapurna South, Hiunchuli and Machapuchhre.</p>\n<p><strong>Day 14: </strong>Walking through the zigzag path we trek to Ghorepani (2775m) via Banthanti and Deorali. In Ghorepani you can lodges which provide food and accomodation to traveller.</p>\n<p><strong>Day 15: </strong>Today early in the morning, we climb to Poon Hill to see the sunrise. After that we march ahead in the village of Ulleri we reach Nayapool. Further walking takes us to Birethanti. From Birethanti we catch a bus for Pokhara.</p>\n<p><strong>Day 16: </strong>Fly back to Kathmandu.</p>\n<p><strong>Day 17: </strong>Departure for your onward flight.</p></p>',NULL,NULL,NULL,'/assets/images/cover-all.jpg',4,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(28,15,'Langtang Region','langtang-region','Closest Himalayan wilderness to Kathmandu — Tamang heritage, rhododendron forests, and Langtang Lirung panoramas just north of the valley.','<p><strong>Langtang Region — Valley of Glaciers</strong></p><p>A short drive from Kathmandu brings you to Langtang National Park, home to Tamang villages, yak pastures, and the glaciated Langtang Lirung massif. Rebuilt warmly after the 2015 earthquake, the valley now welcomes trekkers with improved lodges and community spirit.</p><p><strong>Highlights</strong></p><ul><li>Kyanjin Gompa, Langsisa glaciers, and Yala Peak options</li><li>Tamang hospitality, cheese factories, and forest trails</li><li>Easy access: 7–10 days ideal for limited time</li></ul><p>Best in spring (March–May) and autumn (September–November). Pair with Gosaikunda or Helambu for a longer circuit.</p>',NULL,NULL,NULL,'/assets/images/cover-all.jpg',2,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(29,15,'Manaslu Region Trek','manaslu-region-trek','Remote wilderness circling Manaslu (8,156m) — Tibetan culture, Larkya La (5,135m) and unspoiled valleys recently opened to trekkers.','<p><strong>Manaslu Region Trek — Around the Eighth Highest Peak</strong></p>\n<p>Manaslu (8,156m), the world’s eighth-highest peak, anchors a trek that remains wilder and quieter than Annapurna or Everest. Straddling the Gorkha district bordering Tibet, the region blends subtropical gorges, rhododendron forests, Tibetan mani walls and monasteries — still restricted until recently and now carefully opened with permits and local stewardship.</p>\n<p><strong>Why Trek Manaslu</strong></p>\n<ul>\n<li>Circling Manaslu: From the Buri Gandaki gorge (700m) to Larkya La (5,135m) — a complete 360° of the massif</li>\n<li>Tibetan culture: Samagaun, Samdo, and Tsum’s Mu Gompa (3,700m) with warm homestay and monastery hospitality</li>\n<li>Wilderness: Less crowded than Annapurna, with pristine forests, waterfalls, and chances for blue sheep and Himalayan flora</li>\n<li>Flexible variants to match time and grade</li>\n</ul>\n<p><strong>Choose Your Variant</strong></p>\n<ul>\n<li><strong>Lower Manaslu Eco Trek (12 days, 3,220m, Moderate)</strong> — Barpak, Laprak and Dharche homestays, no high pass</li>\n<li><strong>Manaslu Rupin La Pass Trek (20 days, 4,610m, Moderate–Strenuous)</strong> — Quiet Rupin La crossing via Gorkha forests</li>\n<li><strong>Manaslu Larkya La Pass Circuit Trek (21 days, 5,135m, Moderate–Strenuous)</strong> — The classic tea-house circuit</li>\n<li><strong>Tsum Valley Combine Manaslu Round (26 days, 4,480m+)</strong> — Sacred hidden valley + full circuit via Mu Gompa and Larkya La</li>\n</ul>\n<p><strong>Logistics</strong> All treks start/end in Kathmandu, with bus/private vehicle to Machha Khola or Arughat. Accommodation is hotel in Kathmandu + tea-house/lodge or camping where needed, with full meals on trek. Special Manaslu + Annapurna + TIMS permits (and Tsum permit where needed) are included — we handle paperwork.</p>\n<p><strong>Best Seasons:</strong> March–May (rhododendron bloom, stable days) and September–November (clear skies, festivals). Winter is cold at Larkya La; monsoon (June–August) is for rain-shadow variants only.</p>\n<p>Explore each variant below for day-by-day itineraries, or contact us to tailor days, pace and comfort.</p>',NULL,NULL,NULL,'/assets/images/nepal-cover.jpg',3,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(30,29,'Lower Manaslu Eco Trek','lower-manaslu-eco-trek','Eco-cultural trek to Barpak, Laprak and Dharche — Gurung heritage, Himalayan views and community homestays at 3,220m.','<p><strong>Lower Manaslu Eco Trek — Culture and Community (12 Days)</strong></p>\n<p>Lower Manaslu is a gentle, community-focused introduction to the Manaslu region — terraced hills, historic Gorkha, and Gurung villages rebuilt with pride after 2015. Without high passes, you’ll enjoy rhododendron forests, Himalchuli views, and warm homestays in Barpak, Laprak and Dharche.</p>\n<table style=\"width: 100%;\" border=\"1\" cellspacing=\"1\" cellpadding=\"8\">\n<tbody>\n<tr><td><strong>Duration</strong></td><td>12 days</td><td><strong>Altitude</strong></td><td>3,220m</td></tr>\n<tr><td><strong>Start/End</strong></td><td>Kathmandu / Kathmandu</td><td><strong>Grade</strong></td><td>Moderate</td></tr>\n<tr><td><strong>Accommodation</strong></td><td>Hotel/Guest house</td><td><strong>Meals</strong></td><td>Breakfast/Lunch/Dinner</td></tr>\n<tr><td><strong>Transport</strong></td><td>Bus/Private vehicle</td><td><strong>Group</strong></td><td>Min 2 pax</td></tr>\n</tbody>\n</table>\n<h2>Highlights</h2>\n<ul>\n<li>Barpak (1,920m) and Laprak — model villages with community homestays and craft</li>\n<li>Dharche Ridge (3,220m) panorama: Manaslu, Himalchuli, Ganesh Himal</li>\n<li>Gorkha Durbar and historic unification sites</li>\n<li>Rhododendron forests, terrace farms, and warm Gurung hospitality</li>\n</ul>\n<h2>Short Itinerary</h2>\n<p><strong>Day 1:</strong> Kathmandu arrival.<br/>\n<strong>Day 2:</strong> Drive Kathmandu–Gorkha (140km), hike to Barpak.<br/>\n<strong>Day 3–4:</strong> Barpak–Laprak–Dharche ridge, homestays.<br/>\n<strong>Day 5–7:</strong> Trek via Tallo Thotneri and Sita Cave to Tatopani.<br/>\n<strong>Day 8–9:</strong> Trek to Barpak, drive to Gorkha and Kathmandu.<br/>\n<strong>Day 10–12:</strong> Kathmandu heritage + departure.</p>\n<p><em>We tailor pacing and can combine Lower Manaslu with the main Manaslu Circuit or Tsum Valley.</em></p>',NULL,NULL,NULL,'/assets/images/destinations/Manaslu-Trek.jpg',0,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(31,29,'Manaslu Rupin La Pass Trek','manaslu-rupin-la-pass-trek','Wild Rupin La (4,610m) crossing — from Gorkha’s forests to the Tibetan plateau, a quiet alternative to Larkya La.','<p><strong>Manaslu Rupin La Pass Trek — Quiet High Pass (20 Days)</strong></p>\n<p>Rupin La (4,610m) is Manaslu’s hidden, less-traveled crossing — a pristine alternative to busy Larkya La. From Gorkha’s bazaars through pine and rhododendron forests to yak pastures and the Tibetan plateau, the trail offers solitude, close Manaslu–Himalchuli views, and authentic villages.</p>\n<table style=\"width: 100%;\" border=\"1\" cellspacing=\"1\" cellpadding=\"8\">\n<tbody>\n<tr><td><strong>Duration</strong></td><td>20 days</td><td><strong>Altitude</strong></td><td>4,610m</td></tr>\n<tr><td><strong>Start/End</strong></td><td>Kathmandu / Kathmandu</td><td><strong>Grade</strong></td><td>Moderate–Strenuous</td></tr>\n<tr><td><strong>Accommodation</strong></td><td>Hotel/Lodge/Camp</td><td><strong>Meals</strong></td><td>All meals during trek</td></tr>\n<tr><td><strong>Transport</strong></td><td>Bus/Private vehicle</td><td><strong>Group</strong></td><td>Min 2 pax</td></tr>\n</tbody>\n</table>\n<h2>Highlights</h2>\n<ul>\n<li>Rupin La (4,610m) — wilderness pass with Himalayan panorama</li>\n<li>Gorkha–Arughat–Philim trail through forests and Tibetan-style villages</li>\n<li>Less crowded than Larkya La — ideal for experienced trekkers seeking solitude</li>\n<li>Combine with Tsum Valley for extended cultural immersion</li>\n</ul>\n<h2>Short Itinerary</h2>\n<p><strong>Day 1–2:</strong> Kathmandu arrival + heritage.<br/>\n<strong>Day 3:</strong> Drive to Arughat–Soti Khola.<br/>\n<strong>Day 4–8:</strong> Trek via Machha Khola, Jagat, Deng to Prok and Namrung.<br/>\n<strong>Day 9–12:</strong> Via Lho–Shyala to Samagaun, acclimatization at Birendra Lake.<br/>\n<strong>Day 13–15:</strong> Cross Rupin La (4,610m) to the plateau and descend to Chumling.<br/>\n<strong>Day 16–20:</strong> Return via Philim–Arughat–Kathmandu, departure.</p>\n<p><em>We provide camping where lodges thin, plus full crew and permits.</em></p>',NULL,NULL,NULL,'/assets/images/cover-all.jpg',1,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(32,29,'Manaslu Larkya La Pass Circuit Trek','manaslu-larkya-la-pass-circuit-trek','Classic Manaslu Circuit via Larkya La (5,135m) — 21-day tea-house trek circling Manaslu (8,156m), the eighth-highest peak.','<p><strong>Manaslu Larkya La Pass Circuit Trek — The Classic Circuit (21 Days)</strong></p>\n<p>The classic Manaslu Circuit circles the world’s eighth-highest peak (8,156m) from the sub-tropical Buri Gandaki gorge to the stark Larkya La (5,135m). Hindu villages give way to Buddhist mani walls, monasteries and yak pastures, with daily views of Himalchuli, Ngadi Chuli and Himlung.</p>\n<table style=\"width: 100%;\" border=\"1\" cellspacing=\"1\" cellpadding=\"8\">\n<tbody>\n<tr><td><strong>Duration</strong></td><td>21 days</td><td><strong>Altitude</strong></td><td>5,135m</td></tr>\n<tr><td><strong>Start/End</strong></td><td>Kathmandu / Kathmandu</td><td><strong>Grade</strong></td><td>Moderate–Strenuous</td></tr>\n<tr><td><strong>Accommodation</strong></td><td>Hotel/Lodge</td><td><strong>Meals</strong></td><td>Breakfast in Kathmandu / All meals on trek</td></tr>\n<tr><td><strong>Transport</strong></td><td>Bus/Private vehicle</td><td><strong>Group</strong></td><td>Min 2 pax</td></tr>\n</tbody>\n</table>\n<h2>Highlights</h2>\n<ul>\n<li>Larkya La (5,135m) — high, wind-swept pass with 360° Himalayan views</li>\n<li>Buri Gandaki gorge, waterfalls, and rhododendron forests</li>\n<li>Samagaun, Samdo and Tibetan culture near the border</li>\n<li>Tea-house lodges + experienced acclimatization</li>\n</ul>\n<h2>Short Itinerary</h2>\n<p><strong>Day 1–2:</strong> Kathmandu arrival + heritage.<br/>\n<strong>Day 3:</strong> Drive to Machha Khola.<br/>\n<strong>Day 4–7:</strong> Trek to Jagat–Deng–Namrung–Lho.<br/>\n<strong>Day 8–10:</strong> Shyala–Samagaun–Samdo, acclimatization.<br/>\n<strong>Day 11:</strong> Cross Larkya La (5,135m) to Bhimtang.<br/>\n<strong>Day 12–14:</strong> Trek via Tilje–Chamje to Pokhara/Kathmandu.<br/>\n<strong>Day 15–21:</strong> Return, buffer days, and departure.</p>\n<p><em>Best Mar–May & Sep–Nov. We handle permits (Manaslu, Annapurna, TIMS) and pacing.</em></p>',NULL,NULL,NULL,'/assets/images/cover-all.jpg',2,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(33,29,'Tsum Valley Combine Manaslu Round Trekking','tsum-valley-combine-manaslu-round-trekking','Hidden Tsum Valley + Manaslu Circuit — Mu Gompa, Rachhen Gompa and Larkya La in one 26-day cultural odyssey.','<p><strong>Tsum Valley Combine Manaslu Round Trekking — Sacred Hidden Valley (26 Days)</strong></p>\n<p>Tsum Valley, opened only in 2008, is a sacred hidden valley where Tibetan Buddhism thrives in Mu Gompa (3,700m) and Rachhen Nunnery. Combined with the Manaslu Circuit and Larkya La, this 26-day journey is the deepest cultural immersion in the region — from subtropical gorges to the stark Tibetan plateau.</p>\n<table style=\"width: 100%;\" border=\"1\" cellspacing=\"1\" cellpadding=\"8\">\n<tbody>\n<tr><td><strong>Duration</strong></td><td>26 days</td><td><strong>Altitude</strong></td><td>4,480m (Mu Gompa) / 5,160m Larkya La</td></tr>\n<tr><td><strong>Start/End</strong></td><td>Kathmandu / Kathmandu</td><td><strong>Grade</strong></td><td>Moderate–Strenuous</td></tr>\n<tr><td><strong>Accommodation</strong></td><td>Hotel/Tea house</td><td><strong>Meals</strong></td><td>All meals on trek</td></tr>\n<tr><td><strong>Transport</strong></td><td>Bus/Private vehicle</td><td><strong>Group</strong></td><td>Min 2 pax</td></tr>\n</tbody>\n</table>\n<h2>Highlights</h2>\n<ul>\n<li>Mu Gompa (3,700m) and Rachhen Nunnery (3,240m) — Tibetan monastic life</li>\n<li>Mile-long mani walls, Chhokang Paro, and Milarepa cave</li>\n<li>Larkya La (5,160m) and Manaslu–Himlung–Cheo Himal views</li>\n<li>Sacred, restricted valley — special Tsum permit included</li>\n</ul>\n<h2>Short Itinerary</h2>\n<p><strong>Day 1–2:</strong> Kathmandu arrival + heritage.<br/>\n<strong>Day 3:</strong> Drive to Machha Khola.<br/>\n<strong>Day 4–6:</strong> Trek to Jagat–Lokpa–Chumling (Tsum entry).<br/>\n<strong>Day 7–10:</strong> Chhokang Paro–Nile–Mu Gompa (3,700m), Rachhen Gompa.<br/>\n<strong>Day 11–14:</strong> Return to Chumling, trek to Deng–Namrung–Lho.<br/>\n<strong>Day 15–18:</strong> Samagaun–Samdo, cross Larkya La to Bhimtang.<br/>\n<strong>Day 19–26:</strong> Trek out via Tilje to Kathmandu, departure.</p>\n<p><em>We arrange Tsum + Manaslu permits, local guides from Tsum, and flexible pacing.</em></p>',NULL,NULL,NULL,'/assets/images/cover-all.jpg',3,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(34,15,'Dolpo Region','dolpo-region','Dolpo region is a high altitude and culturally Tibetan region in the upper part of the Dolpo district of western, Nepal. Phoksundo and Mugu Karnali valley lies in the north west and the sixth highest…','<h1><span style=\"font-size: 14pt;\"><strong>Dolpo region is a high altitude and culturally Tibetan </strong></span><span style=\"font-size: 12pt;\"><span style=\"font-size: 14pt;\"><strong>region in the upper part of the Dolpo district of western, Nepal. Phoksundo and Mugu Karnali valley lies in the north west and the sixth highest mountain</strong></span> <span style=\"font-size: 14pt;\"><strong>in the world Mt. Dhaulagiri (8172mtr.) lies in the south west of this region.Dolpo region is a home to some of the highest villages on earth, almost 90% of the region lies above 3500mtr. It is one of the least densely populated area of Nepal. Only five thousand</strong></span></span><span style=\"font-size: 14pt;\"><strong> population live in this region. Agriculture, Animal husbandry and trade are the main source of income of this Dolpo region. For travelers who cannot get enough the adventures and cultures of Dolpo, there is a longer route that takes them through several village. This is an opportunity for travelers to soak in more of the culture of Himalayan trips, and to challenge their physical capacity</strong></span></h1>\n<div class=\"top-entry\">\n<p><span style=\"font-size: 14pt;\">More than 90% population of this region lives under the poverty line, literacy rate of Dolpo district is 54% where women literacy is even worse. This region is divided into Lower and Upper Dolpo. His majesty’s government of Nepal has referred as a ‘upper’ Dolpo, a destination which has restricted for foreigners from traveling extensively in this area.</span></p>\n<p><span style=\"font-size: 14pt;\">The dominion of the western Tibetan dynasties over Dolpo was eclipsed during the fourteenth century by the principality of Lo (present day Mustang District ‘Lomangthang’, Nepal). Thereafter, Dolpo villagers paid tributes to the kingdom of Lo in forms of grains, labor, painting thangka and carving mani walls. Tenzein Norbu Sherpa counts among his ancestors painters paintings at Thubchen and Jampa monasteries. The 1999 French-Nepalese movie Himalaya, which gives insight into the local customs, was the first Nepalese film to be nominated for an Oscar award and also a huge success in Nepal itself, drawing the country’s attention to the region.</span></p>\n</div></p></p>',NULL,NULL,NULL,'/assets/images/destinations/dolpo-trek-300x105-1.jpg',4,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(35,34,'Lower Dolpo Trek','lower-dolpo-trek','Turquoise Phoksundo Lake, Bon villages and Himalayan passes — Lower Dolpo’s wild, accessible trek without Upper’s restricted permits.','<p><strong>Lower Dolpo Trek — Phoksundo Lake and Beyond</strong></p>\n<p>Lower Dolpo offers the wild beauty of Dolpo without the high restricted-area costs of the Upper region. Centered on Shey Phoksundo National Park (3,555 sq. km), the trail winds through pine and juniper forests to the turquoise Phoksundo Lake (3,620m, 145m deep — Nepal’s deepest), Bon villages like Ringmo, and passes with views of Kanjiroba Himal.</p>\n<table style=\"height: 55px; width: 851px;\">\n<tbody>\n<tr>\n<td style=\"width: 71px;\"><span style=\"font-size: 10pt;\">Duration</span></td>\n<td style=\"width: 71px;\"><span style=\"font-size: 10pt;\">Altitude</span></td>\n<td style=\"width: 72.0625px;\"><span style=\"font-size: 10pt;\">Start at</span></td>\n<td style=\"width: 71.9375px;\"><span style=\"font-size: 10pt;\">End at</span></td>\n<td style=\"width: 72px;\"><span style=\"font-size: 10pt;\">Grade</span></td>\n<td style=\"width: 72px;\"><span style=\"font-size: 10pt;\">Group Size</span></td>\n<td style=\"width: 72px;\"><span style=\"font-size: 10pt;\">Accommodation</span></td>\n<td style=\"width: 72px;\"><span style=\"font-size: 10pt;\">Meal</span></td>\n<td style=\"width: 72px;\"><span style=\"font-size: 10pt;\">Transport</span></td>\n</tr>\n<tr>\n<td style=\"width: 71px;\"><span style=\"font-size: 10pt;\">18 days</span></td>\n<td style=\"width: 71px;\"><span style=\"font-size: 10pt;\">5,318m</span></td>\n<td style=\"width: 72.0625px;\"><span style=\"font-size: 10pt;\">Kathmandu</span></td>\n<td style=\"width: 71.9375px;\"><span style=\"font-size: 10pt;\">Kathmandu</span></td>\n<td style=\"width: 72px;\"><span style=\"font-size: 10pt;\">Difficult</span></td>\n<td style=\"width: 72px;\"><span style=\"font-size: 10pt;\">Min 2 pax</span></td>\n<td style=\"width: 72px;\"><span style=\"font-size: 10pt;\">Hotel/Tent</span></td>\n<td style=\"width: 72px;\"><span style=\"font-size: 10pt;\">Breakfast/Lunch/Dinner</span></td>\n<td style=\"width: 72px;\"><span style=\"font-size: 10pt;\">Flights/Ground vehicles</span></td>\n</tr>\n</tbody>\n</table>\n<h2>TRIP HIGHLIGHTS</h2>\n<ul class=\"trek-features\">\n<li>Phoksundo Lake and 107m Phoksundo Waterfall — sacred and spectacular</li>\n<li>Ringmo Bon village, Bon religion (older than Buddhism) and Shey Gompa day</li>\n<li>Forests of pine, spruce, juniper and bamboo — blue sheep and Himalayan flora</li>\n<li>Scenic flights Kathmandu–Nepalgunj–Juphal and authentic Dolpo villages</li>\n</ul>\n<h2>TRIP OVERVIEW</h2>\n<p>Lower Dolpo is the perfect introduction to Dolpo’s culture and wilderness without the extended permits of the Upper region. The trek begins with flights to Juphal (2,475m) then descends to the Thuli Bheri River and climbs through Shey Phoksundo National Park. You’ll follow the Suli Khola past Dhaulagiri views, taste fresh honey in local villages, and camp by Phoksundo’s turquoise waters.</p>\n<p>The region is home to Bon and Buddhist communities who practice ancient traditions. Ringmo village, perched above the lake, offers a glimpse into Bon culture founded 18,000 years ago. The trail then loops via Tarakot (ancient fort) and Dunai, completing a circuit rich in geology, wildlife and warm hospitality.</p>\n<h2>SHORT ITINERARY</h2>\n<p><strong>Day 1:</strong> Kathmandu arrival & briefing.<br/>\n<strong>Day 2:</strong> Heritage sightseeing (Pashupatinath, Boudhanath, Swayambhunath, Kathmandu Durbar Square).<br/>\n<strong>Day 3:</strong> Fly Kathmandu–Nepalgunj.<br/>\n<strong>Day 4:</strong> Fly Nepalgunj–Juphal (2,475m), trek to Dunai.<br/>\n<strong>Day 5:</strong> Trek Dunai–Chhepka (2,838m) via Shey Phoksundo National Park gate.<br/>\n<strong>Day 6:</strong> Trek Chhepka–Palam (3,820m) via Rechi and Amchi Hospital.<br/>\n<strong>Day 7:</strong> Trek Palam–Phoksundo Lake (3,620m) via waterfall and Ringmo.<br/>\n<strong>Day 8:</strong> Explore Phoksundo Lake and Bon villages.<br/>\n<strong>Day 9–14:</strong> Trek via Salla Ghari, Lar Tsa and Shey Gompa with gradual acclimatization.<br/>\n<strong>Day 15–18:</strong> Return via Tarakot–Dunai–Juphal, fly to Kathmandu.</p>\n<h2>INCLUDES AND EXCLUDES</h2>\n<h3>Includes</h3>\n<ul class=\"trek-features\">\n<li>Airport transfers, domestic flights (Kathmandu–Nepalgunj–Juphal return) with tax</li>\n<li>National park fees, TIMS, and trekking permits</li>\n<li>Hotel in Kathmandu (BB) + full camping support (tents, mattresses, kitchen, toilet)</li>\n<li>Guide, cook, porters, insurance, and all meals during trek</li>\n</ul>\n<h3>Excludes</h3>\n<ul class=\"trek-features\">\n<li>Nepal visa, international flights, personal expenses, tips, and travel insurance (helicopter evacuation recommended)</li>\n</ul>\n',NULL,NULL,NULL,'/assets/images/destinations/lower-dolpa-trekking.jpg',0,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(36,34,'Upper Dolpo Trek','upper-dolpo-trek','Remote trans-Himalayan trek to Phoksundo Lake, Shey Gompa and Crystal Mountain — wild Dolpo with Tibetan culture and high passes.','<p><strong>Upper Dolpo Trek — Wild West of the Himalaya</strong></p>\n<p>Upper Dolpo is Nepal’s most remote and culturally intact Himalayan region — a rain-shadow desert behind Dhaulagiri, where Bon and Buddhist traditions thrive. Opened to trekkers only in the late 1980s and still restricted, it rewards the few who venture with turquoise Phoksundo Lake, 11th-century Shey Gompa beneath Crystal Mountain, and passes over 5,350m.</p>\n<table style=\"height: 106px;\" width=\"874\">\n<tbody>\n<tr>\n<td style=\"width: 77.8409px; text-align: center;\"><span style=\"font-size: 10pt;\">Duration</span></td>\n<td style=\"width: 78.75px; text-align: center;\"><span style=\"font-size: 10pt;\">Altitude</span></td>\n<td style=\"width: 82.3864px; text-align: center;\"><span style=\"font-size: 10pt;\">Start at</span></td>\n<td style=\"width: 82.3864px; text-align: center;\"><span style=\"font-size: 10pt;\">End at</span></td>\n<td style=\"width: 80.5682px; text-align: center;\"><span style=\"font-size: 10pt;\">Grade</span></td>\n<td style=\"width: 78.75px; text-align: center;\"><span style=\"font-size: 10pt;\">Group Size</span></td>\n<td style=\"width: 96.9318px; text-align: center;\"><span style=\"font-size: 10pt;\">Accommodation</span></td>\n<td style=\"width: 147.841px; text-align: center;\"><span style=\"font-size: 10pt;\">Meal</span></td>\n<td style=\"width: 92.3864px; text-align: center;\"><span style=\"font-size: 10pt;\">Transport</span></td>\n</tr>\n<tr>\n<td style=\"width: 77.8409px; text-align: center;\"><span style=\"font-size: 10pt;\">25 days</span></td>\n<td style=\"width: 78.75px; text-align: center;\"><span style=\"font-size: 10pt;\">5,350m</span></td>\n<td style=\"width: 82.3864px; text-align: center;\"><span style=\"font-size: 10pt;\">Kathmandu</span></td>\n<td style=\"width: 82.3864px; text-align: center;\"><span style=\"font-size: 10pt;\">Kathmandu</span></td>\n<td style=\"width: 80.5682px; text-align: center;\"><span style=\"font-size: 10pt;\">Difficult</span></td>\n<td style=\"width: 78.75px; text-align: center;\"><span style=\"font-size: 10pt;\">Min 2 pax</span></td>\n<td style=\"width: 96.9318px; text-align: center;\"><span style=\"font-size: 10pt;\">Hotel and Lodge / Camping</span></td>\n<td style=\"width: 147.841px; text-align: center;\"><span style=\"font-size: 10pt;\">Breakfast/Lunch/Dinner</span></td>\n<td style=\"width: 92.3864px; text-align: center;\"><span style=\"font-size: 10pt;\">Flights/Ground vehicle</span></td>\n</tr>\n</tbody>\n</table>\n<h2>TRIP HIGHLIGHTS</h2>\n<ul class=\"trek-features\">\n<li>Phoksundo Lake (3,620m) — Nepal’s deepest lake (145m), turquoise and sacred</li>\n<li>Shey Gompa (4,320m) beneath Crystal Mountain — spiritual heart of Dolpo, 11th century</li>\n<li>Kang La (5,350m) and Jeng La (4,850m) high passes with Himalayan panoramas</li>\n<li>Tibetan culture: Bon and Buddhist villages, yak caravans, and salt-trade trails</li>\n<li>Shey Phoksundo National Park (3,555 sq. km) — snow leopard, blue sheep, and alpine desert</li>\n</ul>\n<h2>TRIP OVERVIEW</h2>\n<p>Upper Dolpo’s remoteness is its magic. The trail follows ancient salt-trade routes from Juphal through Suli Khola and Phoksundo, then climbs to the restricted Upper Dolpo via Kang La. You’ll cross arid valleys where barley is coaxed from thin soil, meet Dolpo-pa families who speak Tibetan, and camp by turquoise lakes. Oscar-nominated <em>Himalaya</em> (Caravan) was filmed here — the landscape feels cinematic.</p>\n<p>We provide full camping support, acclimatization, and special restricted-area permits (USD 500 for 10 days + USD 50/day, min 2 trekkers). Best seasons are <strong>March–May</strong> and <strong>September–November</strong>; winter is too snowy.</p>\n<h2>SHORT ITINERARY</h2>\n<p><strong>Day 1–2:</strong> Kathmandu arrival & heritage sightseeing (Pashupatinath, Boudhanath, Swayambhunath, Kathmandu Durbar Square).<br/>\n<strong>Day 3:</strong> Fly Kathmandu–Nepalgunj (150m).<br/>\n<strong>Day 4:</strong> Fly Nepalgunj–Juphal (2,475m), trek to Dunai.<br/>\n<strong>Day 5–7:</strong> Trek via Chhepka and Rechi to Phoksundo Lake (3,620m) — waterfall and Ringmo Bon village.<br/>\n<strong>Day 8:</strong> Rest at Phoksundo Lake.<br/>\n<strong>Day 9–12:</strong> Trek via Salla Ghari and Lar Tsa to Shey Gompa (4,320m) via Kang La (5,350m).<br/>\n<strong>Day 13–18:</strong> Cross Shey La and Jeng La to Saldang, Sibu, and Tarap valley (Dho Tarap).<br/>\n<strong>Day 19–22:</strong> Trek via Tarakot to Dunai and Juphal.<br/>\n<strong>Day 23:</strong> Fly Juphal–Nepalgunj–Kathmandu.<br/>\n<strong>Day 24:</strong> Departure.</p>\n<p><em>Full day-by-day details, permits, and packing list provided on request — we tailor pace and camps to your group.</em></p>\n<h2>INCLUDES AND EXCLUDES</h2>\n<h3>Includes</h3>\n<ul class=\"trek-features\">\n<li>Airport transfers, domestic flights (Kathmandu–Nepalgunj–Juphal return) with tax</li>\n<li>Special restricted permit, national park fees, TIMS</li>\n<li>Hotel in Kathmandu (BB) + guesthouse in Nepalgunj, full camping support (sleeping/dining/kitchen/toilet tents, mattresses, kitchen crew)</li>\n<li>Guide, Sherpa, cook, porters, insurance, and all meals during trek</li>\n<li>Sleeping bag, map, duffel bag, and first-aid support</li>\n</ul>\n<h3>Excludes</h3>\n<ul class=\"trek-features\">\n<li>Nepal visa, international flights, lunch/dinner in Kathmandu, personal expenses, tips, and travel insurance (helicopter evacuation recommended)</li>\n</ul>\n',NULL,NULL,NULL,'/assets/images/destinations/upperdolpo1.jpg',1,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(37,15,'Western Region Nepal','western-region-nepal','Western Region Nepal has a large population of both Hindus and Buddhists, and the countryside is crisscrossed by trails in all direction. It is remote and unknown from the Western viewpoint because…','<b>Western Region Nepal</b> has a large population of both Hindus and Buddhists, and the countryside is crisscrossed by trails in all direction. It is remote and unknown from the Western viewpoint because of its relative inaccessibility and its distance from Kathmandu. As it falls outside of the monsoon\'s influence or else in the rain shadow of Dhaulagiri Himal, this region receives very little rainfall and this determines its versatile vegetation . Another part that discourages trekkers in western Nepal is that many of the culturally and scenically exotic regions are in restricted areas with high permit fees. As most of the places in this region is culturally and scenically exotic, are in restricted areas with high permit fees; a significant number of tourists are lured by this region.Many of the trails in the west continue to the northern side of the Himalayan ranges of Nampa, Saipal and Kanjiroba, making it easy for trekkers to zip up trails along river valleys and into Tibet - a practice that both the Nepalese and Chinese would like to dispirit. Some of these treks, including Shey Gompa to the north of Phoksumdo Lake and Humla to the north-west of Jumla are described in the sector on Restricted Areas.</p>\n<p>The history and anthropology of western Nepal is complex and fascinating. Majority of Peoples\' are Hindu and Tibetans make up only a small part of the population, although they have the significant influence on the area through trading. Tibetan styles home with the flat roofs covered with the packed earth suited in the semiarid conditions of the area behind Dhaulagiri. In many villages the houses are packed closely together one atop another, climbing up the hillside and sharing common roofs with the few stairs inside the dwellings. Tibetan-style houses can be found here where people climb from one level to another on carved log ladders situated outside the house.</p>\n<p>Cultural roots extend north into Tibet and west to Kumaon in India. The Chhetris of western Nepal are categorized into three groups: Thakuris, who are the aristocracy; normal Chhetris as found throughout Nepal; and Matwali Chhetris, \"those who drink liquor\". The status of Matwali Chhetris is fascinating because many Tibetan immigrants long ago masqueraded as Chhetris. For many generations they have evolved their own form of religion that is a peculiar mixture of Hinduism and Buddhism. The trekking season is from late spring and throughout the summer until late October.</p></p>',NULL,NULL,NULL,'/assets/images/nepal-cover.jpg',5,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(38,37,'Saipal Himal Trek','saipal-himal-trek','Saipal Himal Trek is an amazing trekking trail where you will have magnificent mountains views of the Saipal Himal and superb landscape, agreeable ambiance. This trail may be little bit difficult…','<b>Saipal Himal Trek</b> is an amazing trekking trail where you will have magnificent mountains views of the Saipal Himal and superb landscape, agreeable ambiance. This trail may be little bit difficult trekking trail without camping crew so all the trekkers should do their try by Local travel agency in Kathmandu Nepal.  Being with camping crew it will be one of the easiest trials toward Saipal Himal.</p>\n<p>Lying at western part of Nepal, that provides us picturesque views of this region. Our trail will begin form <b>Simikot to the Karnali River</b> bank along the <b>Thankuri Hindu Villages and Humal Tibetan</b> settlements. Where, you could have chance to explore and observe traditional villages, rural life style of the inhabitants, local farmers working on indigenous crop field and the ancient Tibetan Buddhist monasteries, shrines as well as we head towards the majestic view of the Saipal Himal(7,035m) which is look like  a sleeping golden ox. A dazzling valley around the mountain that carries enriches diversity of flora and Fauna which is also the main attraction of this trial. </p>\n<p>&nbsp;</p>\n<p><span style=\"font-size: 24pt;\"><strong>Trek Highlight</strong></span></p>\n<p><b>Trekking Name               : </b>Saipal Himal Trek<br />\n <b>Hotels in Kathmandu   : </b>Budget Hotel, start to 5 stars Hotel as per Guest’s request<br />\n <b>Accommodation             : </b>Mountains Lodges (Guest House)/ Camp<br />\n <b>Transportation               : </b>Land transportation (Car, Van, Local bus, Tourist Bus)<br />\n <b>Domestic flights             : </b>Kathmandu/ Nepalgunj/ Kathmandu<br />\n <b>Attractions                       : </b>you can explore the magnificent views of the mountains like  Saipal          Himal and superb landscape, agreeable ambiance, also can observe  traditional villages, rural life style of the inhabitants, local farmers working on indigenous crop field and the ancient Tibetan Buddhist  monasteries etc.<br />\n <b>Grade                                 : </b>Moderate to strenuous<br />\n <b>Best Season                     : </b>Spring, autumn<br />\n <b>Walking hours               : </b>per day 5 to 7 hours<br />\n <b>Group size                       : </b>2 + members or (we can organize solo travelers private group &amp; Family                                                     group as well)<br />\n <b>Duration                            :</b>22 days</p>\n<p>&nbsp;</p>\n<p style=\"text-align: center;\"><span style=\"font-size: 24pt;\"><strong>Itinerary</strong></span></p>\n<table border=\"1\" width=\"655\" cellspacing=\"0\" cellpadding=\"0\" align=\"none\">\n<tbody>\n<tr>\n<td valign=\"top\"><b>Note:</b></td>\n<td valign=\"top\">Days in the destination itinerary can be increased or decreased. Please contact us for the itinerary according your holiday time.  </td>\n</tr>\n<tr>\n<td><b>Day 01<br />\n </b></td>\n<td>Arrival at Kathmandu, Welcome program by Adventure Specialist Travel and direct transfer to hotel.</td>\n</tr>\n<tr>\n<td><b>Day 02</b></td>\n<td>Kathmandu valley sightseeing / Cultural Day in Kathmandu Valley Half day sightseeing around Kathmandu where your guide will escort you on a tour of Buddhist and Hindu temples, and shrines reflecting ancient local traditions. There is time to explore the city many places of interest on your own or take a rest while trekking permits are finalized.</td>\n</tr>\n<tr>\n<td><b>Day 03<br />\n </b></td>\n<td>We take a flight from Kathmandu to Nepalgunj. Overnight at  hotel</td>\n</tr>\n<tr>\n<td><b>Day 04<br />\n </b></td>\n<td>We drive from Nepalgunj to Mahendranagar by reserve bus &amp; Overnight at hotel.</td>\n</tr>\n<tr>\n<td><b>Day 05<br />\n </b></td>\n<td>We drive from Mahendranagar to Gokuleshwor by reserve bus  &amp; Overnight at  hotel.</td>\n</tr>\n<tr>\n<td><b>Day 06<br />\n </b></td>\n<td>We start trekking from Gokuleshwor to Karkale &amp; Overnight at camp.</td>\n</tr>\n<tr>\n<td><b>Day 07<br />\n </b></td>\n<td>We trek from Karkale to Chiureni &amp; Overnight at camp.</td>\n</tr>\n<tr>\n<td><b>Day 08<br />\n </b></td>\n<td>We trek from Chiureni to Makarighat &amp; Overnight at  camp.</td>\n</tr>\n<tr>\n<td><b>Day 09<br />\n </b></td>\n<td>We trek from Makarighat to Seti &amp; Overnight at camp.</td>\n</tr>\n<tr>\n<td><b>Day 10<br />\n </b></td>\n<td>We trek from Seti to Lawathi &amp; Overnight at camp.</td>\n</tr>\n<tr>\n<td><b>Day 11<br />\n </b></td>\n<td>We trek from Lawathi to Simar &amp; Overnight at camp.</td>\n</tr>\n<tr>\n<td><b>Day 12<br />\n </b></td>\n<td>We trek from Simar to Dhawaliwadar &amp; Overnight at camp.</td>\n</tr>\n<tr>\n<td><b>Day 13<br />\n </b></td>\n<td>We trek from Dhawalidwar to Api Himal Base Camp &amp; Overnight at camp.</td>\n</tr>\n<tr>\n<td><b>Day 14<br />\n </b></td>\n<td>We trek from Api Himal Base Camp to Saheb Bagar &amp; Overnight at  camp.</td>\n</tr>\n<tr>\n<td><b>Day 15</b></td>\n<td>We trek from Saheb Bagar to Makarighat &amp; Overnight at  camp.</td>\n</tr>\n<tr>\n<td><b>Day 16<br />\n </b></td>\n<td>We trek from Makarighat to Bitule &amp; Overnight at  camp.</td>\n</tr>\n<tr>\n<td><b>Day 17<br />\n </b></td>\n<td>We trek from Bitule to Gokuleshwor &amp; Overnight at camp.</td>\n</tr>\n<tr>\n<td><b>Day 18<br />\n </b></td>\n<td>We drive from Gokuleshwor to Mehendranagar &amp; Overnight at hotel.</td>\n</tr>\n<tr>\n<td><b>Day 19<br />\n </b></td>\n<td>We drive from Mahendranagar to Nepalgunj &amp; Overnight at hotel</td>\n</tr>\n<tr>\n<td><b>Day 20<br />\n </b></td>\n<td>We take a flight from Nepalgunj to Kathmandu transferred to hotel</td>\n</tr>\n<tr>\n<td><b>Day 21<br />\n </b></td>\n<td>Free day in Kathmandu, Evening farewell dinner in Typical Nepali Culture and say good bye.</td>\n</tr>\n<tr>\n<td><b>Day 22<br />\n </b></td>\n<td>Departure from Kathmandu to your onward destination.</td>\n</tr>\n</tbody>\n</table>\n<p>&nbsp;</p>\n<p>&nbsp;</p>\n<h3>Service Cost includes:</h3>\n<ul class=\"include\">\n	<li>All Transportation</li>\n	<li>3 meals per day during the trek (Breakfast Lunch Dinner) including Tea or coffee</li>\n	<li>Accommodation on Tea House ( Lodge ) or provided Tents during the trek as mentioned in the trek type.</li>\n	<li>Accommodation in star Hotel in Kathmandu</li>\n	<li>High Experienced Government Licensed Guide and Necessary porter during the trek.</li>\n	<li>All Government local Taxes National park Fees ( TIMS:Trekkers  Information Management System) first Aid kit and general equipment for Porter.</li>\n	<li>Guide and porter salary Staff insurance During the trekking and extra services according to the guest per Demand.</li>\n</ul>\n<h3>Service Cost excludes:</h3>\n<ul class=\"exclude\">\n	<li>Trekking equipment any type of personal expenses such as Alcoholic Beverage drinks,phone and Laundry.</li>\n	<li>Emergency Rescue and Travel Insurance.Trip Cancellation cost accident or Health, Loss Theft or Damage and personal effects. we Advice you to take out personal Travel Insurance.</li>\n	<li>Tips and Gratuities.</li>\n</ul></p>',NULL,NULL,NULL,'/assets/images/cover-all.jpg',0,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(39,15,'Meditational Trek in Lower Khumbu','meditational-trek-lower-khumbu','Trip Highlight: Trip Duration: 9 days Altitude: 2675m Grade: Moderate Start Point: Phaplu End point: Phaplu Region: Lower Khumbu Region Accommodations: 3 star hotel in Kathmandu / Normal lodges or Tea…','<span style=\"font-size: 14pt;\"><strong>Trip Highlight:</strong></span></p>\n<p>Trip Duration: 9 days</p>\n<p>Altitude: 2675m</p>\n<p>Grade: Moderate</p>\n<p>Start Point: Phaplu</p>\n<p>End point: Phaplu</p>\n<p>Region: Lower Khumbu Region</p>\n<p>Accommodations: 3 star hotel in Kathmandu / Normal lodges or Tea houses during trek</p>\n<p>Transportation: Private vehicles and Domestic flight</p>\n<p><span style=\"font-size: 14pt;\"><strong>Itinerary:</strong></span></p>\n<p><strong>Day 1: Arrival in Kathmandu</strong><br />\n Upon your arrival in Tribhuvan International Airport, our representatives from Adventure Specialist Travel will receive you and transfer to the hotel.Hotel staff will complete check in and manage for your accomodation.After short time of period, you can enjoy the place near your hotel and return back to hotel for overnight.</p>\n<p><strong>Day 2: Sightseeing in Kathmandu Valley</strong></p>\n<p>Today after breakfast you will be introduced to our local tour guide and start a guided tour to several of the most historical and spiritual attractions in Kathmandu. Visit to Bouddhanath including the main stupa and to the monasteries which surround this most sacred area.</p>\n<p><strong>Sightseeing places ;</strong></p>\n<ul>\n	<li><strong>Pashupatinath Temple: </strong>This temple is situated 5 km east of Kathmandu, the temple of Lord Shiva; Pathupatinath with two tired golden roof and silver doors is considered one of the holiest shrines of Hindus.</li>\n</ul>\n<ul>\n	<li><strong>Boudhanath Stupa</strong>:This Stupa lays 8kms east of Kathmandu. This ancient colossal Stupa is one of the biggest in the world and the center of Buddhism in the world. It was listed in the UNESCO Heritage Monument in 1979.</li>\n</ul>\n<ul>\n	<li><strong>Swoyambunath Stupa</strong>: Swoyambhunath Stupa, atop the hillock is one of the holiest Buddhist sites in Nepal enlisted in the World Heritage Site.</li>\n</ul>\n<ul>\n	<li><strong>Durbar Square </strong>:Later proceed for city tour of Kathmandu visiting <strong>Durbar Square</strong>, complex of palaces, courtyard and temples, built between the 12th and 18th centuries, use to be the seat of the ancient Malla kings of Kathmandu.</li>\n</ul>\n<p><strong><u>O/N: Accommodation in guest house on sharing, breakfast and bed basis</u></strong></p>\n<p><strong>Day 3: Fly from Kathmandu to Phaplu 2470m</strong><strong>,</strong><br />\nWake up early morning and transfer to domestic airport, then fly to Phaplu.</p>\n<p><strong><u>O/N: Lodge with all meal ( Breakfast, Lunch and Dinner)</u></strong></p>\n<p><strong><u> </u></strong></p>\n<p><strong>Day 4: Trek from Phaplu to Junbesi 2675m,</strong><br />\nIn the morning, after  breakfast we start trek along the Junbesi Khola through the pine and rhododendron forest until reaching picturesque village of Junbesi with viewing Numbur Chuli.</p>\n<p><strong><u>O/N: Lodge with all meal (Breakfast, Lunch and Dinner)</u></strong></p>\n<p><strong>Day 5: Exploring the Thubten Chholing Monastery</strong><br />\nWake up morning, have breakfast and walk towards Thubten Chholing Monastery, a huge Tibetan Buddhist Monastery founded by the revered Lama Trulsik Rinpoche, who fled to <a href=\"https://www.trekking-in-nepal.net/en/destinations/nepal\">Nepal</a> from Rongbuk Gompa in <a href=\"https://www.trekking-in-nepal.net/en/destinations/tibet\">Tibet</a> with a large group of Anis (Nuns) and monks in the 1960s. Whole afternoon free for Meditation inside the Monastery on your own and back to Lodge.</p>\n<p><strong><u>O/N: Lodge with all meal (Breakfast, Lunch and Dinner)</u></strong></p>\n<p><strong><u><br />\n</u></strong><strong>Day 6: Exploring the surrounding hills</strong><br />\nWake up, morning  after breakfast walk around the village and surrounding hill.</p>\n<p><strong><u>O/N: Lodge with all meal (Breakfast, Lunch and Dinner)<br />\n<br />\n</u></strong><strong>Day 7: Trek from Junbesi to Phaplu 2470m</strong><br />\nWake up and after breakfast trek down along the Junbesi Khola until reaching Phaplu.</p>\n<p><strong><u>O/N: Lodge with all meal (Breakfast, Lunch and Dinner)<br />\n</u></strong><br />\n<br />\n<strong>Day 8: Phaplu to Kathmandu by flight</strong></p>\n<p>Early in the morning fly back to Kathmandu and transfer to hotel. Free time you can explore places near hotel.</p>\n<p><strong><u>O/N: Lodge</u></strong></p>\n<p><strong><u> </u></strong></p>\n<p><strong>Day 9: Final Departure from Kathmandu</strong></p>\n<p>Our representative from Adventure Specialist Travel will pick you from your hotel and drop you to Tribhuvan International before your flight departure time.</p>\n<p><span style=\"font-size: 14pt;\"><strong>Our Trek Package Cost includes;</strong></span><br />\n* Airport/Hotel/Airport pick up and transfer by private car/van.<br />\n* Accommodation in twin bed sharing basis with breakfast at 3*** hotel in   Kathmandu.<br />\n* Kathmandu Tour as per above mentioned itinerary and all entry fees.<br />\n* Round trip domestic flight tickets and airport tax,<br />\n* Meals (breakfast, lunch and dinner) with Tea &amp; coffee and hot water during the Lodge trek.<br />\n* Lodge to lodge accommodation during the trek.<br />\n* 1 experienced helpful and friendly guide, porters (1 porter for 2 peoples), their food &amp; accommodation, salary, equipments &amp; insurance.<br />\n* All transportation by private vehicle.<br />\n* All necessary permits.,<br />\n* First Aid Medical Kit Box.<br />\n* Office Service charge<br />\n* All Government Tax.<br />\n<br />\n<span style=\"font-size: 14pt;\"><strong>Our Trek Package doesn\'t include;</strong></span><br />\n* Any meals in Kathmandu other than breakfast.<br />\n* Travel insurance (if you want us to arrange your travel insurance, we would greatly be happy to assist).<br />\n* International air fare to and from <a href=\"https://www.trekking-in-nepal.net/en/destinations/nepal\">Nepal</a>.<br />\n* <a href=\"https://www.trekking-in-nepal.net/en/destinations/nepal\">Nepal</a> Tourist Visa fee.<br />\n* Items and expenses of personal nature.<br />\n* Any kind of alcoholic drinks, cold drinks, laundry, phone call, internet.<br />\n* Personal Trekking Equipments like sleeping bags, jackets (can all be hired in KTM)<br />\n* Emergency Evacuation (Helicopter Rescue).<br />\n* Any costs which arise due to a change of the itinerary, because of landslides, domestic flight delays, political disturbance, and strikes etc.<br />\n* Any other costs whatsoever, that is not mentioned in the cost included.<br />\n* Horse renting and additional porters during the trek.<br />\n* Tips for guide, porters, driver...</p></p>',NULL,NULL,NULL,'/assets/images/nepal-cover.jpg',6,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(40,15,'Rara Lake Trek','rara-lake-trek','Rara Lake lies at an altitude of 2,990 m (9,810 ft) above sea level , has a water surface of 10.8 km 2 (4.2 sq mi), a maximum depth of 167 m (548 ft), is 5.1 km (3.2 mi) long and 2.7 km (1.7 mi)…','<p><span style=\"font-size: 14pt;\">Rara Lake lies at an altitude of 2,990 m (9,810 ft) <a class=\"mw-redirect\" title=\"Above sea level\" href=\"https://en.wikipedia.org/wiki/Above_sea_level\">above sea level</a>, has a water surface of 10.8 km<sup>2</sup> (4.2 sq mi), a maximum depth of 167 m (548 ft), is 5.1 km (3.2 mi) long and 2.7 km (1.7 mi) wide. It drains into the Mugu Karnali River via the Nijar River. Its water quality is characterized by high <a title=\"PH\" href=\"https://en.wikipedia.org/wiki/PH\">pH</a>, <a title=\"Conductivity (electrolytic)\" href=\"https://en.wikipedia.org/wiki/Conductivity_(electrolytic)\">conductivity</a> and total <a class=\"mw-redirect\" title=\"Hardness of water\" href=\"https://en.wikipedia.org/wiki/Hardness_of_water\">hardness</a>.</span></p>\n<p><span style=\"font-size: 14pt;\">Summer is quite pleasant but winter is cold. The best visiting time to the lake is September/October and April to May. From December to March, the temperatures go low below the freezing point, and heavy snowfall occur up to one meter, blocking the way to the lake. April to June is warm in this region.</span></p>\n<p><span style=\"font-size: 14pt;\">Monsoon season, which in this region occurs between the months of July to October, is short. The average rainfall during the ten-year period 1994–2003 was 800 mm. The surface temperature of the lake was found to be 7.5 °C to 7.6 °C and was visible below 14 m to 15 m</span>.</p>\n<p><span style=\"font-size: 14pt;\"><strong><u>Trip Highlight</u></strong></span></p>\n<p>Trip Duration: 16 days</p>\n<p>Altitude: 3270m</p>\n<p>Grade: Moderate to Strenuous </p>\n<p>Start Point: Jumla</p>\n<p>End Point: Jumla</p>\n<p>Accommodations: 3 Star accomodation in Kathmandu, Nepalgunj and Camp during trek</p>\n<p>Transportations: Private vehicles and Domestic flights</p>\n<p><strong> </strong></p>\n<p><span style=\"font-size: 14pt;\"><strong>Rara Lake Trek Itinerary</strong></span></p>\n<table>\n<tbody>\n<tr>\n<td width=\"73\">\n<p>&nbsp;</p>\n</td>\n<td width=\"565\">\n<p><strong>Program</strong></p>\n</td>\n</tr>\n<tr>\n<td width=\"73\">\n<p>Day 01</p>\n</td>\n<td width=\"565\">\n<p>Arrival in Kathmandu and transfer to hotel</p>\n</td>\n</tr>\n<tr>\n<td width=\"73\">\n<p>Day 02</p>\n</td>\n<td width=\"565\">\n<p><strong>City tour of Kathmandu valley</strong></p>\n<p><strong>Sightseeing places</strong></p>\n<p><strong>·         </strong><strong>Pashupatinath Temple</strong></p>\n<p>·         <strong>Boudhanath Stupa</strong></p>\n<p>·         <strong>Swoyambunath Stupa</strong></p>\n<p>·         <strong>Durbar Square</strong></p>\n<p>&nbsp;</p>\n</td>\n</tr>\n<tr>\n<td width=\"73\">\n<p>Day 03</p>\n</td>\n<td width=\"565\">\n<p>Fly from Kathmandu to Nepalgunj and transfer to Hotel</p>\n</td>\n</tr>\n<tr>\n<td width=\"73\">\n<p>Day 04</p>\n</td>\n<td width=\"565\">\n<p>Fly from Nepalgunj to Jumla 2370m</p>\n</td>\n</tr>\n<tr>\n<td width=\"73\">\n<p>Day 05</p>\n</td>\n<td width=\"565\">\n<p>Trek from Jumla to Danphe Langa 3130m/5-6 hours</p>\n</td>\n</tr>\n<tr>\n<td width=\"73\">\n<p>Day 06</p>\n</td>\n<td width=\"565\">\n<p>Trek from Danphe Langa to Chautha 2770m/5-6 hours</p>\n</td>\n</tr>\n<tr>\n<td width=\"73\">\n<p>Day 07</p>\n</td>\n<td width=\"565\">\n<p>Trek from Chautha to Dhotu 2380m/4-5 hours</p>\n</td>\n</tr>\n<tr>\n<td width=\"73\">\n<p>Day 08</p>\n</td>\n<td width=\"565\">\n<p>Trek from Dhotu to Rara Lake 3040m/3-4 hours</p>\n</td>\n</tr>\n<tr>\n<td width=\"73\">\n<p>Day 09</p>\n</td>\n<td width=\"565\">\n<p>Exploring Rara Lake 3040m</p>\n</td>\n</tr>\n<tr>\n<td width=\"73\">\n<p>Day 10</p>\n</td>\n<td width=\"565\">\n<p>Rest and explore Rara Lake as well as surrounding hills</p>\n</td>\n</tr>\n<tr>\n<td width=\"73\">\n<p>Day 11</p>\n</td>\n<td width=\"565\">\n<p>Trek from Rara Lake to Ghorasingha 3190m/4-5 hours</p>\n</td>\n</tr>\n<tr>\n<td width=\"73\">\n<p>Day 12</p>\n</td>\n<td width=\"565\">\n<p>Trek from Ghorasingha to Sinja 2440m/4-5 hours</p>\n</td>\n</tr>\n<tr>\n<td width=\"73\">\n<p>Day 13</p>\n</td>\n<td width=\"565\">\n<p>Trek from Sinja to Jaljala 3270m/5-6 hours</p>\n</td>\n</tr>\n<tr>\n<td width=\"73\">\n<p>Day 14</p>\n</td>\n<td width=\"565\">\n<p>Trek from Jaljala to Jumla 2370m/3-4 hours</p>\n</td>\n</tr>\n<tr>\n<td width=\"73\">\n<p>Day 15</p>\n</td>\n<td width=\"565\">\n<p>Fly from Jumla to Nepalgunj and afternoon fly back to Kathmandu</p>\n</td>\n</tr>\n<tr>\n<td width=\"73\">\n<p>Day 16</p>\n</td>\n<td width=\"565\">\n<p>Final Departure</p>\n</td>\n</tr>\n</tbody>\n</table>\n<p>&nbsp;</p>\n<p><span style=\"font-size: 14pt;\"><strong>Our Service Cost Includes:</strong></span><br />\n </p>\n<ul>\n	<li>Airport / Hotel / Airport pick up &amp; transfer by car / Van.</li>\n	<li>All domestic flights KTM/Jumla/KTM.</li>\n	<li>3 nights accommodation with breakfast at Tibet Guest House in Kathmandu.</li>\n	<li>1 night accommodation with breakfast at Hotel City Palace in Nepalgunj.</li>\n	<li>Kathmandu city tour and all entry fees as per the above itinerary.</li>\n	<li>Meals (breakfast, lunch and dinner) with Tea &amp; coffee and hot/cold filter water during the camping trek.</li>\n	<li>12 nights tented camp and hotel accommodation during the trek.</li>\n	<li>1 experienced helpful and friendly guide, 1 cook and 1 helper, porters (1 porter for 2 peoples), their food &amp; accommodation, salary, equipments and insurance.</li>\n	<li>All ground transportation by private car.</li>\n	<li>Rara National Park Permit.</li>\n	<li>All necessary permits and government tax.</li>\n	<li>First Aid Medical kit box.</li>\n</ul>\n<p><span style=\"font-size: 14pt;\"><strong>Our Service Cost Excludes:</strong></span><br />\n </p>\n<ul>\n	<li>Any meals in Kathmandu and Nepalgunj other than breakfast.</li>\n	<li>International air fare to and from Nepal.</li>\n	<li>NepalTourist Visa fee.</li>\n	<li>Items and expenses of personal nature.</li>\n	<li>Any kind of alcoholic drinks, cold drinks, laundry, phone call, internet.</li>\n	<li>Personal Trekking Equipments like sleeping bags, jackets etc.</li>\n	<li>You’re private Travel insurance and Emergency Evacuation (Helicopter Rescue).</li>\n	<li>Any costs which arise due to a change of the itinerary, because of landslides, political disturbance, and strikes etc.</li>\n</ul></p></p>',NULL,NULL,NULL,'/assets/images/destinations/Boating_at_Rara.jpg',7,'2026-08-23 11:55:01','2026-08-23 11:55:01',1),(41,15,'Kanchenjunga North Trek','kanchenjunga-north-trek','Kanchenjunga north trek is another fantabulous trekking trail in the Kanchenjunga trekking region. The trek which kicks off either from Suketar or Basantapur, has Pang Pema (514m) as the highest…','<a title=\"Kanchenjunga north trek\" href=\"http://trekkinginmountain.com/kanchenjunga-north-trek\">Kanchenjunga north trek</a> is another fantabulous trekking trail in the Kanchenjunga trekking region. The trek which kicks off either from Suketar or Basantapur, has Pang Pema (514m) as the highest ascending point and the highlight. Amazing landscapes and majestic mountains leave you with the sensation of meandering in a factual paradise.<br />\nComparatively longer and physically demanding, it requires prior trekking or hiking experience to venture into this amazing journey.  The exploration of north face of gigantic Mt. <a title=\"Kanchenjunga north trek\" href=\"http://trekkinginmountain.com/kanchenjunga-north-trek\">Kanchenjunga</a> is worth all the efforts and hardships during the trip. You can also have close scrutiny of mighty <a title=\"Kanchenjunga north trek\" href=\"http://trekkinginmountain.com/kanchenjunga-north-trek\">Himalayas</a> and downhill flow of Himalayan rivers.  Luxuriant forests, breathtaking panoramas, wonderful rice terraces, and spectacular scenery will be additional rewards for you during this trekking.<br />\nPhysical robustness and adequate walking experience in the alpines is necessary to embark on this audacious journey. Blaze mountain adventure, being a committed adventure service provider, will leave no stones unturned to provide you with ultimate adventure experience in the <a title=\"Kanchenjunga north trek\" href=\"http://trekkinginmountain.com/kanchenjunga-north-trek\">Kanchenjunga north trekking</a>. Blaze mountain adventure ensure that the trip will be a blend of full fun and exhilaration. Hurry up and book yourself this fantastic excursion; feel free to contact us for detailed insight on this trip</p>\n<p><span style=\"font-size: 18pt;\"><strong>Itinerary</strong></span></p>\n<table style=\"width: 832px; height: 632px;\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td style=\"width: 94.6875px;\" valign=\"top\">\n<p><strong>Day 01</strong></p>\n</td>\n<td style=\"width: 732.465px;\" align=\"justify\">Namaste and warm welcome to nepal.Upon your arrival in Nepal our team member will  welcome and assists you to  your hotel, after which you will receive a welcome dinner.</td>\n</tr>\n<tr>\n<td style=\"width: 94.6875px;\"><strong>Day 02 :</strong></td>\n<td style=\"width: 732.465px;\">Kathmandu Valley city tours and preparation for upcoming trek.</td>\n</tr>\n<tr>\n<td style=\"width: 94.6875px;\"><strong>Day 03 :</strong></td>\n<td style=\"width: 732.465px;\">Flight from Kathmandu to Suketar then trek to Phurumba.</td>\n</tr>\n<tr>\n<td style=\"width: 94.6875px;\"><strong>Day 04 :</strong></td>\n<td style=\"width: 732.465px;\">Trek from Phurumba to Chirwa (1190m).</td>\n</tr>\n<tr>\n<td style=\"width: 94.6875px;\"><strong>Day 05 :</strong></td>\n<td style=\"width: 732.465px;\">Trek from Chirwa to Sakathum (1640m).</td>\n</tr>\n<tr>\n<td style=\"width: 94.6875px;\"><strong>Day 06 :</strong></td>\n<td style=\"width: 732.465px;\">Trek from Sakathum to Amjilassa (2490m).</td>\n</tr>\n<tr>\n<td style=\"width: 94.6875px;\"><strong>Day 07 :</strong></td>\n<td style=\"width: 732.465px;\">Trek from Amjilassa to Gyabla (2730m).</td>\n</tr>\n<tr>\n<td style=\"width: 94.6875px;\"><strong>Day 08 :</strong></td>\n<td style=\"width: 732.465px;\">Trek from Gyabla to Gunsa (3410m).</td>\n</tr>\n<tr>\n<td style=\"width: 94.6875px;\"><strong>Day 09 :</strong></td>\n<td style=\"width: 732.465px;\">Rest day at Ghunsa for acclimatization.</td>\n</tr>\n<tr>\n<td style=\"width: 94.6875px;\"><strong>Day 10 :</strong></td>\n<td style=\"width: 732.465px;\">Trek from Ghunsa to Khambachen (4150m).</td>\n</tr>\n<tr>\n<td style=\"width: 94.6875px;\"><strong>Day 11 :</strong></td>\n<td style=\"width: 732.465px;\">Trek from Khambachen to Lhonak(4790m).</td>\n</tr>\n<tr>\n<td style=\"width: 94.6875px;\"><strong>Day 12 :</strong></td>\n<td style=\"width: 732.465px;\">Trek from Lhonak to Pangpema (5140m).</td>\n</tr>\n<tr>\n<td style=\"width: 94.6875px;\"><strong>Day 13 :</strong></td>\n<td style=\"width: 732.465px;\">Exploration around North base camp of mount Kanchenjunga.</td>\n</tr>\n<tr>\n<td style=\"width: 94.6875px;\"><strong>Day 14 :</strong></td>\n<td style=\"width: 732.465px;\">Trek back to Khambachen (4150m).</td>\n</tr>\n<tr>\n<td style=\"width: 94.6875px;\"><strong>Day 15 :</strong></td>\n<td style=\"width: 732.465px;\">Trek from Khambachen to Ghunsa (3410m).</td>\n</tr>\n<tr>\n<td style=\"width: 94.6875px;\"><strong>Day 16 :</strong></td>\n<td style=\"width: 732.465px;\">Trek from Ghunsa to Amjilosa.</td>\n</tr>\n<tr>\n<td style=\"width: 94.6875px;\"><strong>Day 17 :</strong></td>\n<td style=\"width: 732.465px;\">Trek from Amjilosa to Chirwa.</td>\n</tr>\n<tr>\n<td style=\"width: 94.6875px;\"><strong>Day 18 :</strong></td>\n<td style=\"width: 732.465px;\">Trek from Chirwa to Linkhim.</td>\n</tr>\n<tr>\n<td style=\"width: 94.6875px;\"><strong>Day 19 :</strong></td>\n<td style=\"width: 732.465px;\">Trek from Linkhim to Suketar (2400m).</td>\n</tr>\n<tr>\n<td style=\"width: 94.6875px;\"><strong>Day 20 :</strong></td>\n<td style=\"width: 732.465px;\">Flight from Suketar to Kathmandu, evening farewell dinner.</td>\n</tr>\n<tr>\n<td style=\"width: 94.6875px;\" valign=\"top\"><strong>Day 21 :</strong></td>\n<td style=\"width: 732.465px;\" align=\"justify\">After this wonderfu<em>l Kanchenjunga north trek</em> if you have additional time you can join other program  like Hiking,Expedition,Climbing, Safari, Rafting, Tours.we arrange trip according to your wish.In case if you like to conclude your stay without  any further program we will transfer you  to airport for your departure.</td>\n</tr>\n</tbody>\n</table>\n<p>&nbsp;</p>\n<p><strong>Service Cost Includes:</strong></p>\n<ul>\n	<li>Airport/Hotel/Airport pickup and drop by private car/van.</li>\n	<li>Accommodation in twin bed sharing basis with breakfast at Tibet Guest House in Kathmandu.</li>\n	<li>Accommodation in twin bed sharing basis with breakfast at Meera Hotel in Pokhara.</li>\n	<li>Kathmandu and Pokhara Sightseeing Tour as per the above itinerary.</li>\n	<li>Accommodation in lodge during trek with all meal basis (Breakfast/Lunch/Dinner)</li>\n	<li>Domestic flight tickets from KTM/PKR/KTM.</li>\n	<li>1 experienced helpful and friendly guide, porters (1 porter for 2 peoples), their food &amp; accommodation, salary, equipments &amp; insurance.</li>\n	<li>All transportation by private vehicle.</li>\n	<li>Annapurna Conservation Area Permit (ACAP and TIMS).</li>\n	<li>All Government Tax and documents.<br />\n <br />\n <strong>Service Cost Excludes:</strong><br />\n </li>\n	<li>Any meals (Lunch and Dinner) in Kathmandu and Pokhara other than breakfast.</li>\n	<li>International air fare to and from Nepal.</li>\n	<li>NepalTourist Visa fee.</li>\n	<li>Items and expenses of personal nature.</li>\n	<li>Any kind of alcoholic drinks, cold drinks, laundry, phone call, internet.</li>\n	<li>Personal Trekking Equipments like sleeping bags, jackets etc.</li>\n	<li>Emergency Evacuation (Helicopter Rescue) and Travel insurance.</li>\n	<li>Any costs which arise due to a change of the itinerary, because of landslides, domestic flight delays, political disturbance, and strikes etc.</li>\n	<li>Any other costs whatsoever, that is not mentioned in the cost included.</li>\n	<li>Tips for guide, porters, driver...</li>\n</ul></p>',NULL,NULL,NULL,'/assets/images/nepal-cover.jpg',8,'2026-08-23 11:55:01','2026-08-23 11:55:01',1);
