naslu-region-trek/','custom',3,1,0,'2026-08-31 17:43:46','2026-08-31 17:43:46'),(21,5,'Dolpo Region','/nepal/dolpo-region/','custom',4,1,0,'2026-08-31 17:43:46','2026-08-31 17:43:46'),(22,5,'Western Region Nepal','/nepal/western-region-nepal/','custom',5,1,0,'2026-08-31 17:43:46','2026-08-31 17:43:46'),(23,5,'Meditational Trek in Lower Khumbu','/nepal/meditational-trek-lower-khumbu/','custom',6,1,0,'2026-08-31 17:43:46','2026-08-31 17:43:46'),(24,5,'Rara Lake Trek','/nepal/rara-lake-trek/','custom',7,1,0,'2026-08-31 17:43:46','2026-08-31 17:43:46'),(25,5,'Kanchenjunga North Trek','/nepal/kanchenjunga-north-trek/','custom',8,1,0,'2026-08-31 17:43:46','2026-08-31 17:43:46'),(26,2,'Welcome to Nepal','/about-us/welcome-to-nepal/','custom',1,1,0,'2026-08-31 17:43:46','2026-08-31 17:43:46'),(27,2,'Nepal Information','/about-us/nepal-information/','custom',2,1,0,'2026-08-31 17:43:46','2026-08-31 17:43:46'),(28,2,'About AST Travel & Trek','/about-us/about-ast-travel-trek/','custom',3,1,0,'2026-08-31 17:43:46','2026-08-31 17:43:46'),(29,2,'Why Choose AST','/about-us/why-choose-ast/','custom',4,1,0,'2026-08-31 17:43:46','2026-08-31 17:43:46'),(30,2,'Trekking/Tour Season','/about-us/trekkingtour-season/','custom',5,1,0,'2026-08-31 17:43:46','2026-08-31 17:43:46'),(31,2,'Some Useful Information','/about-us/some-useful-information/','custom',6,1,0,'2026-08-31 17:43:46','2026-08-31 17:43:46'),(32,8,'Shivapuri Day Hike','/ast-services/short-hiking/shivapuri-day-hike/','custom',0,1,0,'2026-09-01 03:12:28','2026-09-01 03:12:28'),(33,8,'Phulchoki Day Hike','/ast-services/short-hiking/phulchwoki-day-hike/','custom',1,1,0,'2026-09-01 03:12:28','2026-09-01 03:12:28'),(34,8,'Champadevi Day Hike','/ast-services/short-hiking/champadevi-day-hike/','custom',2,1,0,'2026-09-01 03:12:28','2026-09-01 03:12:28'),(35,9,'Koshi Tappu Wildlife Reserve','/ast-services/jungle-safari/koshi-tappu-wildlife-reserve/','custom',0,1,0,'2026-09-01 03:12:28','2026-09-01 03:12:28'),(36,9,'Bardia National Park','/ast-services/jungle-safari/bardia-national-park/','custom',1,1,0,'2026-09-01 03:12:28','2026-09-01 03:12:28'),(37,9,'Chitwan National Park','/ast-services/jungle-safari/chitwan-national-park/','custom',2,1,0,'2026-09-01 03:12:28','2026-09-01 03:12:28'),(38,10,'Paragliding in Kathmandu','/ast-services/paragliding/paragliding-in-kathmandu/','custom',0,1,0,'2026-09-01 03:12:28','2026-09-01 03:12:28'),(39,10,'Paragliding in Pokhara','/ast-services/paragliding/paragliding-in-pokhara/','custom',1,1,0,'2026-09-01 03:12:28','2026-09-01 03:12:28'),(40,12,'Bheri River Rafting','/ast-services/rafting/bheri-river-rafting/','custom',0,1,0,'2026-09-01 03:12:28','2026-09-01 03:12:28'),(41,12,'Sunkoshi River Rafting','/ast-services/rafting/sunkoshi-river-rafting/','custom',1,1,0,'2026-09-01 03:12:28','2026-09-01 03:12:28'),(42,12,'Arun River Rafting','/ast-services/rafting/arun-river-rafting/','custom',2,1,0,'2026-09-01 03:12:28','2026-09-01 03:12:28'),(43,12,'Bhote Koshi River Rafting','/ast-services/rafting/bhote-koshi-river-rafting/','custom',4,1,0,'2026-09-01 03:12:28','2026-09-01 03:12:28'),(44,12,'Kali Gandaki River Rafting','/ast-services/rafting/kali-gandaki-river-rafting/','custom',5,1,0,'2026-09-01 03:12:28','2026-09-01 03:12:28'),(45,12,'Karnali River Rafting','/ast-services/rafting/karnali-river-rafting/','custom',6,1,0,'2026-09-01 03:12:28','2026-09-01 03:12:28'),(46,12,'Marshyandi River Rafting','/ast-services/rafting/marshyandi-river-rafting/','custom',7,1,0,'2026-09-01 03:12:28','2026-09-01 03:12:28'),(47,12,'Seti River Rafting','/ast-services/rafting/seti-river-rafting/','custom',8,1,0,'2026-09-01 03:12:28','2026-09-01 03:12:28'),(48,12,'Trisuli River Rafting','/ast-services/rafting/trisuli-river-rafting/','custom',10,1,0,'2026-09-01 03:12:28','2026-09-01 03:12:28');
