INSERT INTO `pages` VALUES (1,NULL,'ABOUT US','about','Welcome to the Website of Adventure Specialist Travel. We hope it will become the home to your travel &amp; tour services, you need for Nepal, Tibet, Bhutan, Myanmar and Sikkim. Our services include:…','<p>Welcome to the Website of Adventure Specialist Travel. We hope it will become the home to your travel &amp; tour services, you need for Nepal, Tibet, Bhutan, Myanmar and Sikkim.   </p>\n<p><strong>Our services include:</strong></p>\n<ul>\n	<li>Culture, Adventure &amp; Jungle Safari Packages for Groups and Individuals</li>\n	<li>Sightseeing tours in &amp; around Kathmandu Valley</li>\n	<li>Arrangement for incentive tours</li>\n	<li>Tours/trekking to Tibet, Bhutan, Sikkim, India and Myanmar</li>\n	<li>White water rafting</li>\n	<li>Hotel reservations</li>\n	<li>Domestic &amp; International air ticketing</li>\n	<li>A scenic mountain flight from Kathmandu or Pokhara</li>\n	<li>Special interest/cultural tours</li>\n	<li>And all tourism related services.</li>\n</ul>\n<p><strong>Explore Nepal from different Angle</strong></p>\n<p>Managed and operated by a group of dedicated and experienced people, who are not only well versed in the adventure travel service business, but also are committed to conserving our natural and cultural diversity. Our tours, treks and river raft trips are well equipped, offers optimum safety, provides guides who have first hand knowledge of the routes, natural history and cultural background.</p>\n<p>Adventure Specialist Travel is legally registered companies under the Ministry of Tourism &amp; Civil Aviation and Ministry of Industry &amp; Commerce, Nepal Government.. We are also an active member of Nepal Association of Tour &amp; Travel Agents (NATTA), Nepal German Chamber of Commerce and Industries (NGCCI) and other local and International Associations, that promotes Tourism in Nepal.</p></p>','/assets/images/pages/15.jpg',0,'2026-08-23 11:55:00','2026-08-23 11:55:00',1),(2,1,'Welcome to Nepal','welcome-to-nepal','Nepal is one of the richest countries in the world in terms of bio-diversity due to its unique geographical position and latitudinal variation. The elevation of the country ranges from 60m above sea…','<p>Nepal is one of the richest countries in the world in terms of bio-diversity due to its unique geographical position and latitudinal variation. The elevation of the country ranges from 60m above sea level to the highest point on earth, Mt. Everest at 8,848m, all within a distance of 150 km with climatic conditions ranging from sub-tropical to arctic. This wild variation fosters an incredible variety of ecosystems, the greatest mountain range on earth, thick tropical jungles teeming with a wealth of wildlife, thundering rivers, forested hills and frozen valleys.</p>\n<p>Within this spectacular geography is also one of the richest cultural landscapes anywhere. The country is a potpourri of ethnic groups and sub-groups who speak over 70 languages and dialects. Nepal offers an astonishing diversity of sightseeing attractions and adventure opportunities found nowhere else on earth. And you can join in the numerous annual festivals that are celebrated throughout the year in traditional style highlighting enduring customs and beliefs.</p>\n<p>We welcome you to take part in any of the activities that we offer and we are glad to extend our warm hospitality to make your stay in Nepal a memorable one.</p>\n<p><strong>Namaste</strong></p>\n<p>&nbsp;</p>\n<p><strong>Please contact us for the following services:</strong></p>\n<ul>\n	<li>Cultural, Adventure &amp; Jungle Safari packages for groups &amp; individuals</li>\n	<li>Sightseeing tours in/an around Kathmandu valley</li>\n	<li>Arrangement for incentive tours</li>\n	<li>Tours to Tibet/China, Bhutan , India and Myanmar</li>\n	<li>Trekking &amp; White Water rafting</li>\n	<li>Hotel reservation</li>\n	<li>Domestic &amp; International ticketing</li>\n	<li>A scenic Mountain Flight</li>\n	<li>Special interest/Cultural Tours</li>\n	<li>And all tourism related services</li>\n</ul></p></p>','/assets/images/pages/3.jpg',1,'2026-08-23 11:55:00','2026-08-23 11:55:00',1),(3,1,'Nepal Information','nepal-information','Nepal’s essential facts — geography, people, climate, and travel essentials for planning your Himalayan journey with Adventure Specialist Travel.','<p><strong>Nepal — Essential Information for Travelers</strong></p>\n<p>Nepal occupies a remarkable vertical world — from 60 meters in the Terai lowlands to 8,848.86 meters at Mount Everest — within just 150 kilometers. This dramatic altitudinal range, coupled with its position between India and China, creates extraordinary biodiversity and cultural diversity in a compact, welcoming country.</p>\n<p>Nepal covers only 0.1% of Earth’s landmass yet is home to:</p>\n<ul>\n<li>2% of all flowering plants in the world</li>\n<li>8% of the world’s bird species (848+ recorded)</li>\n<li>4% of the world’s mammals</li>\n<li>11 of 15 butterfly families (500+ species)</li>\n<li>600+ indigenous plant families and 319 exotic orchid species</li>\n</ul>\n<p><span style=\"font-size: 14pt;\"><strong>Nepal at a Glance</strong></span></p>\n<table style=\"border-color: #dddddd; width: 100%;\" border=\"1\" cellspacing=\"1\" cellpadding=\"8\">\n<tbody>\n<tr><td><strong>Area</strong></td><td>147,516 sq. km</td></tr>\n<tr><td><strong>Location</strong></td><td>Between China (Tibet) to the north and India to the south, east and west</td></tr>\n<tr><td><strong>Capital</strong></td><td>Kathmandu</td></tr>\n<tr><td><strong>Population</strong></td><td>~30.9 million (2024 estimate)</td></tr>\n<tr><td><strong>Language</strong></td><td>Nepali (official); English widely spoken in tourism</td></tr>\n<tr><td><strong>Currency</strong></td><td>Nepalese Rupee (NPR) — USD 1 ≈ NPR 133 (2024, varies)</td></tr>\n<tr><td><strong>Political System</strong></td><td>Federal Democratic Republic (since 2008)</td></tr>\n<tr><td><strong>Religion</strong></td><td>Hindu (~81%) and Buddhist (~9%) in harmonious coexistence; also Islam, Kirat, Christian</td></tr>\n<tr><td><strong>Climate</strong></td><td>Tropical in lowlands to arctic in high Himalaya; four seasons — spring, monsoon, autumn, winter</td></tr>\n<tr><td><strong>Time Zone</strong></td><td>UTC+5:45 (Nepal Time)</td></tr>\n<tr><td><strong>Calling Code</strong></td><td>+977</td></tr>\n</tbody>\n</table>\n<p>&nbsp;</p>\n<p><span style=\"font-size: 14pt;\"><strong>Geography & Climate</strong></span></p>\n<p>Three ecological belts shape travel: the <strong>Terai</strong> (tropical jungles, Chitwan and Bardia), the <strong>Hills</strong> (Kathmandu, Pokhara, terraced villages), and the <strong>Himalaya</strong> (Everest, Annapurna, Langtang). Monsoon (June–August) greens the hills but is ideal only in rain-shadow areas like Dolpo, Mustang and Tibet. Peak trekking seasons are <strong>March–May</strong> (rhododendron bloom, warmer days) and <strong>September–November</strong> (clear skies, festivals).</p>\n<p><span style=\"font-size: 14pt;\"><strong>Culture & People</strong></span></p>\n<p>Nepal is a mosaic of 125+ caste/ethnic groups speaking 120+ languages. UNESCO World Heritage sites in Kathmandu Valley (Pashupatinath, Boudhanath, Swayambhunath, and durbar squares of Kathmandu, Patan and Bhaktapur) reflect Newar artistry and living traditions. Festivals like Dashain, Tihar and Indra Jatra fill the calendar with color.</p>\n<p><span style=\"font-size: 14pt;\"><strong>Travel Essentials</strong></span></p>\n<ul>\n<li><strong>Entry:</strong> Tourist visa on arrival at Tribhuvan International Airport and land borders; carry 2 passport photos and USD cash/card.</li>\n<li><strong>Health:</strong> No mandatory vaccinations; routine plus hepatitis/tetanus advised. Altitude awareness above 3,000m — our guides manage acclimatization.</li>\n<li><strong>Connectivity:</strong> NTC and Ncell SIMs, 4G in cities, limited in mountains. Power 230V; bring universal adapter.</li>\n<li><strong>Etiquette:</strong> Remove shoes in temples, walk clockwise around stupas, ask before photographing people, dress modestly.</li>\n</ul>\n<p>Adventure Specialist Travel — licensed by the Ministry of Culture, Tourism & Civil Aviation and member of NATTA/NGCCI — ensures safety, permits, and local expertise. Contact us to tailor your Nepal Information into a perfect itinerary.</p>','/assets/images/cover-all.jpg',2,'2026-08-23 11:55:00','2026-08-23 11:55:00',1),(4,1,'About AST Travel & Trek','about-ast-travel-trek','Welcome to the Website of Adventure Specialist Travel. We hope it will become the home to your travel &amp; tour services, you need for Nepal, Tibet and Bhutan. Our services include: Culture,…','Welcome to the Website of Adventure Specialist Travel. We hope it will become the home to your travel &amp; tour services, you need for Nepal, Tibet and Bhutan.</p>\n<p>Our services include:</p>\n<ul>\n	<li>Culture, Adventure &amp; Jungle Safari Packages for Groups and Individuals</li>\n	<li>Sightseeing tours in &amp; around Kathmandu Valley</li>\n	<li>Arrangement for incentive tours</li>\n	<li>Tours/trekkings to Tibet, Bhutan, Sikkim &amp; India</li>\n	<li>White water rafting</li>\n	<li>Hotel reservations</li>\n	<li>Domestic &amp; International air ticketing</li>\n	<li>A scenic mountain flight from Kathmandu or Pokhara</li>\n	<li>Special interest/cultural tours</li>\n	<li>And all tourism related services</li>\n</ul>\n<p>&nbsp;</p>\n<p>Managed and operated by a group of dedicated and experienced people, who are not only well versed in the adventure travel service business, but also are committed to conserving our natural and cultural diversity. Our tours, treks and river raft trips are well equipped, offers optimum safety, provides guides who have first hand knowledge of the routes, natural history and cultural background.</p>\n<p>Adventure Specialist Travel is legally registered companies under the Ministry of Tourism &amp; Civil Aviation and Ministry of Industry &amp; Commerce, Nepal Government.. We are also an active member of Nepal Association of Tour &amp; Travel Agents (NATTA), Nepal German Chamber of Commerce and Industries (NGCCI) and other local and International Associations, that promotes Tourism in Nepal.</p></p>','/assets/images/cover-all.jpg',3,'2026-08-23 11:55:00','2026-08-23 11:55:00',1),(5,1,'Why Choose AST','why-choose-ast','&nbsp; Adventure Specialist Travel (AST) was started in 1995. The Founder of AST is Mr. Raj K. Shrestha, who began his career in Tourism business in 1988. 19 years in the tourism trade helped him to…','<p>Adventure Specialist Travel (AST) was started in 1995. The Founder of AST is Mr. Raj K. Shrestha, who began his career in Tourism business in 1988. 19 years in the tourism trade helped him to gain enormous experience in making attractive tour/trek packages and traveled a lot to add realistic/practical knowledge on all the tour packages, he initiated.</p>\n<p>He also traveled to Europe  and USA several times to do the marketing and promote Nepal as a tourist destination among his friends, clientele and tour operators. He is multilingual personnel with high ability to understand western as well as eastern cultures. He facilitates westerners to understand Nepali culture properly and motivate them to support Nepal in different ways, either by visiting Nepal as tourists or initiating deference development projects in Nepal, which will help Nepal and Nepalese for a better future.</p>\n<p>You can visit following website for more information on his social contributions and development works in Nepal, which he has been doing for more than a decade.</p>\n<p><a href=\"http://www.nepalhilfe.de/\" target=\"_blank\" rel=\"noopener noreferrer\">www.nepalhilfe.de</a><br />\nHe believes in generating more employment opportunities through tourism and it is one of the biggest foreign currency earners for this country. AST contributes 10% of its earnings to all the development works; he has been involved in the country. Therefore, booking a trek with AST, you can also contribute to our efforts to make our dreams of ‘better Nepal for tomorrow” come true!</p>\n<p><a href=\"http://fwhcnepal.org.np/\" target=\"_blank\" rel=\"noopener noreferrer\">www.fwhcnepal.org.np</a><br />\nAST is a registered travel agency under the Ministry of Tourism and Civil Aviation, Tourism Department (Reg. No. 426/053), Ministry of Commerce and Industries (Reg. No. 5990/053/54), Nepal Government, and is an active member of Nepal Association of Tour and Travel Agents (NATTA), Nepal German Chamber of Commerce &amp; Industry (NGCCI) and several other local Associations, which promotes tourism business for Nepal.</p>\n<p>Our main office is located at Pulchowk, Lalitpur, exactly at the Gateway to the famous Patan Durbar Square (one of the World Heritage Site), in front of the Municipality Building, Lalitpur, Kathmandu Valley. AST is also affiliated with numerous agencies/companies from all over the world and has an aim to bring many tourists to Nepal in order to generate more job opportunities to youths, who are leaving this country due to lack of proper opportunities in the country. As per recent statistics, it is estimated around 600 to 800 youths, who are leaving this country EVERYDAY for better jobs outside the country. Skilled and talented youths are also attracted to go abroad for better opportunity, which is definitely a ‘brain-drain’ from this country. Therefore, by booking trips with us, you will also help generating job opportunities in Nepal, thus helping Nepal &amp; Nepalese.</p>\n<p>Our Administrative staff can deal with all your queries, and there will always be someone in the office to answer your questions regarding trips to this part of the world instantly. All Staff members are qualified to answer your all queries regarding the trip to Nepal as well as trips to Bhutan, Sikkim &amp; Tibet.</p>\n<p>Some more reasons, why you choose our Company for trips to this part of the world:</p>\n<ul>\n	<li>We try to make your holidays, a lifetime experience! so that you can have a positive impression of your trips and the areas, you are traveling. AST cares for good services and value your money paid for the services. AST does not compromise with better services. If you would like to have references of our previous customers, who live nearby your hometown or region, AST can provide you for your references and probably even done the same trip, you are considering!</li>\n	<li><strong>Friendly Staff:</strong> Nepalese are traditionally friendly people and easygoing people. All staffs, either in the field or in office, are very friendly or care for better hospitality. AST Team consists of the staffs, which come from the northern part of the country, where all high mountains are located, as well as from the lowlands of the country, where people are trained for extreme mountainous activities and have also climbed several high peaks in the country. Staff members are also from the famous trekking areas of Nepal, such as Everest region, Annapurna region, Langtang region, who are eagerly awaiting to take you to their regions to show their life style and let you enjoy the sceneries seen from their home places. Our staffs are well trained to handle high altitude sickness besides their normal safety measures for clients and are very conscious about keeping better environment in the areas, they take you.</li>\n	<li><strong>Hygienic food &amp; water:</strong> AST is very concerned about your fooding or eateries in Nepal, when you are traveling here. It tries to suggest you better &amp; hygienic places, where you can go and eat, however, most of the Restaurants, which are meant for tourists, are, of course, better managed, hygienically. While on trek, AST provides plentiful, healthy, wholesome and varied foods, prepared by cooks trained in modern cooking hygiene. Special care is taken to serve well-boiled and purified drinking water everyday, while on the tour or trekking, to ensure that our clients stay healthy and enjoy their outing fully. Our cooks for the trek are famous for their ability to produce varied and tasty meals in adverse conditions.</li>\n	<li><strong>Group Size:</strong> AST can organize trips according to the size of the group, which can be from minimum number of participants to high number of participants. AST has organized many trips, which consisted to maximum 8 pax in a group. However, it also organized tour/trek for a group of 30 pax recently in Nepal. AST can prepare varieties of itinerary according to the size of the group. There are also tours on ‘group joining’ basis for those, who are interested and like to do the tour with the people from different countries or even same country!</li>\n	<li><strong>Environmental Concern:</strong> AST briefs all the staffs to make them aware of environmental issues in the areas, they take clients and are very much conscious about it. It is more precisely done, especially, when AST has group to a trekking in the country. AST uses kerosene or gas for cooking purpose on the trek to avoid burning firewood. We recycle non-biodegradable waste and use centralized toilet tents. Our staffs are trained in the correct disposal of waste. All biodegradable waste is burned and buried before breaking camp every morning. Non-degradable wastes (tin, cans, bottles, plastic, etc.) are carried back to Kathmandu for proper dispose. Care is also taken to fill in toilet holes after use.</li>\n	<li><strong>Insurance:</strong> Every single porter and staff employed by AST for the trek, is not only well paid, but also protected by a life insurance policy.</li>\n</ul></p>','/assets/images/why-choose-ast-300x225.jpg',4,'2026-08-23 11:55:00','2026-08-23 11:55:00',1),(6,1,'Trekking/Tour Season','trekkingtour-season','WHEN TO GO TO NEPAL These are typical weather and trekking conditions you may encounter month by month but remember that every year is different. Conditions vary from one trekking region to another…','<strong>WHEN TO GO TO NEPAL</strong><br />\n These are typical weather and trekking conditions you may encounter month by month but remember that every year is different. Conditions vary from one trekking region to another and mountains make their own weather - even in traditionally dry months it can rain.</p>\n<p><strong>JUNE, JULY &amp; AUGUST:</strong> The monsoon is in full swing and these months are not good for trekking, except in Dolpo, Mustang and Tibet, which are in the rain shadow of the Himalayas.</p>\n<p><strong>MID – LATE SEPTEMBER:</strong> A fair amount of cloud and rainfall still around. Lush vegetation and wildflowers, hot temperatures at low altitudes and a few leeches presents, but pleasant trekking higher up.</p>\n<p><strong>OCTOBER &amp; NOVEMBER:</strong> Clear skies and good visibility; still warm at lower altitudes but nights could fall to –15C above 4000m. November is cooler than October.</p>\n<p><strong>DECEMBER:</strong> Great temperatures for trekking below 2500m but can get very cold at night at higher altitudes, with temperatures down to-20 C or colder. With proper clothing, trekking can be very rewarding because of the excellent visibility. Light snowfalls a possibility.</p>\n<p><strong>JANUARY:</strong> Conditions similar to December, but often colder.</p>\n<p><strong>FEBRUARY:</strong> Still excellent visibility but starting to warm up during the day, especially later in the month. Good trekking at lower altitudes but still cold at night higher up.</p>\n<p><strong>MARCH:</strong> Still good visibility and getting warmer at low altitudes Wild flowers and rhododendrons start to bloom and a good month for birds.</p>\n<p><strong>APRIL:</strong> Rhododendrons in full bloom, alpine flora at higher altitudes and plenty of bird life, hot trekking at lower altitudes but ideal temperatures higher up. More cloud and haze around in the pre-monsoon build up, especially in the afternoons.</p>\n<p><strong>MAY:</strong> Very hot at lower altitudes but excellent trekking higher up. Abundant flora, especially alpines; mornings often still clear but cloud and haze around and possibly some pre-monsoon showers.</p>\n<p>&nbsp;</p>\n<p><strong>EQUIPMENT &amp; CLOTHING:</strong></p>\n<p>Equipment needed depends largely upon where, when and how one is trekking. The main emphasis while trekking is on keeping warm and dry while still being lightweight. For lower altitude, fleece jackets and pants are adequate, while at higher altitudes down jackets are advisable. Waterproof, wind-proof jackets and pants, well broken-in footwear, head covering are also recommended. Good sleeping bags, sunglasses, drinking water bottle, torchlight, sun block cream, toiletries, first aid kit and a very good route map are other items necessary. Cameras, on the other hand, are handy for taking home memories.</p>\n<p>Trekking equipments are available for hiring in Kathmandu, Pokhara and Namche Bazaar.</p>\n<p>&nbsp;</p>\n<p><strong>HEALTH &amp; MEDICINE:</strong></p>\n<p>Medication shops are few on trekking routes. Therefore, it is best to carry first aid kit and read about the possible problems before hand. On the Everest Base Camp route at Pheriche and on the Annapurna Circuit route at Manang, there are clinics operated by the Himalayan Rescue Association that specializes in treating trekker’s heath problems. These clinics are open only during the main trekking seasons. While on treks, the following problems could occur:</p>\n<ol>\n	<li>Upset stomach, often caused by change in diet or contaminated food and water in a common ailment. To avoid it, one should pay particular attention to hygiene and quality of food and drinks.</li>\n	<li>Cough, cold, sore throats, common in the dry mountain air can lead to chest infection. Sore throats can best be avoided by attempting not to breathe cold air directly through mouth. Smoking should also be avoided.</li>\n	<li>Joint muscle strains, food problems and blisters are other hindrances for trekkers. Wearing good footwear will go a long way in avoiding these problems. For sprains and strains, apply cold water to reduce swelling and support the joint with crepe bandage.</li>\n	<li>Acute Mountain sickness (AMS) is a fatal sickness caused by random altitude ascension. Therefore, climbers ascending 3,000 meters or above should acquire sound knowledge of proper acclimatization processes. Symptoms of AMS include headache, loss of appetite, swelling of limbs, dizziness, difficulty in sleeping, irregular breathing, nausea and unusual weariness. Maintaining good fluid intake helps combat altitude sickness and hurried descent or evacuation to lower altitude in the only best cure.</li>\n</ol>\n<p>&nbsp;</p>\n<p><strong>SAFETY &amp; SECURITY:</strong></p>\n<p>Nepal is a safe country to trek provided the basis rules are observed. When with trekking agency most contingencies are handled by agency staff. However, one could get lost or hurt and have no one to ask for help when trekking alone. Therefore, trekkers should either trek with agencies, or hire reliable guides if trekking in smaller groups. The best way to avoid risk while trekking is through thorough planning, playing by the rules and realizing human limitations. In case of misfortune, a short detailed message should be dispatched to a reliable organization or individual immediately for rescue operation. If communication facilities are unavailable, normal first aid principles should be followed till help arrives. Some of the safety rules to abide by are:</p>\n<ol>\n	<li>Do not trek alone.</li>\n	<li>Do not make a display of wealth.</li>\n	<li>Keep belongings secure and within sight.</li>\n	<li>Make arrangements for handling emergency situations before hand.</li>\n	<li>Register personal information and trekking plan details with respective embassies.</li>\n	<li>Buy travel insurance policy that cover helicopter rescue cost. Leave a copy of details with an agency in Kathmandu.</li>\n	<li>Choose only authorized government registered travel and trekking agencies, guides and porters.</li>\n</ol></p>','/assets/images/cover-all.jpg',5,'2026-08-23 11:55:00','2026-08-23 11:55:00',1),(7,1,'Some Useful Information','some-useful-information','Essential parks, reserves, entry fees and travel tips — practical information to plan your nature and heritage journey in Nepal.','<p><strong>Some Useful Information for Your Nepal Journey</strong></p>\n<p>Planning makes the Himalaya enjoyable. Below are the protected areas, entry formalities, and practical tips that help you travel smoothly and respectfully with Adventure Specialist Travel.</p>\n<p><span style=\"font-size: 14pt;\"><strong>National Parks and Reserves</strong></span></p>\n<p>Chitwan National Park, in the inner Terai, was Nepal’s first national park (1973, UNESCO World Heritage 1984). Its tropical forests and grasslands shelter the one-horned rhinoceros, Royal Bengal tiger, gharial crocodile, gaur bison and Gangetic dolphin, plus 440+ bird species including giant hornbill and Bengal florican.</p>\n<table style=\"border-color: #dddddd; width: 100%;\" border=\"1\" cellspacing=\"1\" cellpadding=\"8\">\n<tbody>\n<tr><td><strong>Park / Reserve</strong></td><td><strong>Area</strong></td><td><strong>Location</strong></td></tr>\n<tr><td>Chitwan National Park</td><td>932 sq. km</td><td>South-central Nepal</td></tr>\n<tr><td>Sagarmatha National Park</td><td>1,148 sq. km</td><td>North-east Nepal (Everest region)</td></tr>\n<tr><td>Langtang National Park</td><td>1,710 sq. km</td><td>32 km north of Kathmandu</td></tr>\n<tr><td>Bardia National Park</td><td>968 sq. km</td><td>Mid-far western Terai</td></tr>\n<tr><td>Shey Phoksundo National Park</td><td>3,555 sq. km</td><td>Mountain region, western Nepal</td></tr>\n<tr><td>Rara National Park</td><td>106 sq. km</td><td>North-west Nepal</td></tr>\n<tr><td>Makalu-Barun National Park</td><td>2,330 sq. km</td><td>Eastern Nepal</td></tr>\n<tr><td>Khaptad National Park</td><td>225 sq. km</td><td>Far-western Nepal</td></tr>\n<tr><td>Annapurna Conservation Area</td><td>7,629 sq. km</td><td>Central Nepal</td></tr>\n<tr><td>Koshi Tappu Wildlife Reserve</td><td>175 sq. km</td><td>Eastern Terai</td></tr>\n<tr><td>Shuklaphanta National Park</td><td>305 sq. km</td><td>Far-western Nepal</td></tr>\n</tbody>\n</table>\n<p>&nbsp;</p>\n<p><span style=\"font-size: 14pt;\"><strong>Entry Fees & Permits (2024)</strong></span></p>\n<ul>\n<li><strong>National Parks:</strong> NPR 3,000 for foreigners (Chitwan, Bardia, Langtang, Sagarmatha etc.); TIMS card NPR 2,000 where required. Fees are collected at park gates — we include them in your itinerary.</li>\n<li><strong>Heritage Sites (Kathmandu Valley):</strong> Durbar Squares and stupa precincts have separate tickets (NPR 1,000–1,500). We pre-arrange these with your guide.</li>\n<li><strong>Trekking Permits:</strong> TIMS + Annapurna/Manaslu/Langtang permits as needed. Restricted areas (Upper Dolpo, Mustang, Manaslu) require special permits — we handle paperwork.</li>\n</ul>\n<p><span style=\"font-size: 14pt;\"><strong>Practical Tips</strong></span></p>\n<ul>\n<li><strong>Money:</strong> NPR; ATMs in cities, cash preferred in mountains. USD 1 ≈ NPR 133 (2024).</li>\n<li><strong>Health:</strong> Carry personal meds, water purification, and travel insurance covering helicopter evacuation above 3,000m.</li>\n<li><strong>Etiquette:</strong> Dress modestly at temples, remove shoes, walk clockwise around stupas, ask before photographing people.</li>\n<li><strong>Connectivity:</strong> NTC/Ncell 4G in towns; limited signal on high trails. Power 230V, bring universal adapter.</li>\n</ul>\n<p>Need a checklist tailored to your trip? Contact us — we’ll send a packing list and permit summary for your exact itinerary.</p>','/assets/images/cover-all.jpg',6,'2026-08-23 11:55:00','2026-08-23 11:55:00',1),(8,NULL,'Managing Director','managing-director','Mr. Raj Kumar Shrestha — Founder of Adventure Specialist Travel since 1995, guiding Himalayan journeys with 30+ years of expertise and community spirit.','<p><strong>Mr. Raj Kumar Shrestha — Founder & Managing Director</strong></p><p>Mr. Raj Kumar Shrestha began his tourism career in 1988 and founded Adventure Specialist Travel (AST) in 1995 with a clear purpose: share Nepal’s Himalayan heritage through safe, respectful, and well-crafted journeys. With over three decades in trekking and tour operations, he brings hands-on route knowledge from Everest and Annapurna to Manaslu, Dolpo, and the Tibetan plateau.</p><p>Multilingual and widely traveled in Europe and the USA for tourism promotion, he bridges Western expectations with Nepali warmth — helping guests understand local culture while supporting sustainable livelihoods. AST contributes 10% of earnings to education and community projects via partner initiatives.</p><p><strong>Contact</strong><br/>Mobile: 9851024546<br/>Email: rajshrestha13367@gmail.com<br/>Office: Bungamati, Lalitpur, Nepal — Sun–Fri 9:00–16:00</p><p><em>“Tourism must create opportunity and preserve culture. When you travel with AST, you support better futures.” — Raj Kumar Shrestha</em></p>','/assets/images/cover-all.jpg',0,'2026-08-23 11:55:00','2026-08-23 11:55:00',1);
