6,'delete_hero::slide','web','2026-08-25 08:53:19','2026-08-25 08:53:19'),(37,'view_inquiry','web','2026-08-25 08:53:19','2026-08-25 08:53:19'),(38,'create_inquiry','web','2026-08-25 08:53:19','2026-08-25 08:53:19'),(39,'update_inquiry','web','2026-08-25 08:53:19','2026-08-25 08:53:19'),(40,'delete_inquiry','web','2026-08-25 08:53:19','2026-08-25 08:53:19'),(41,'page_ManageSiteSettings','web','2026-08-25 08:53:19','2026-08-25 08:53:19'),(42,'widget_RecentInquiriesOverview','web','2026-08-25 08:53:19','2026-08-25 08:53:19'),(43,'widget_StatsOverview','web','2026-08-25 08:53:19','2026-08-25 08:53:19'),(44,'widget_DashboardChart','web','2026-08-25 08:53:19','2026-08-25 08:53:19'),(45,'view_user','web','2026-08-30 10:10:56','2026-08-30 10:10:56'),(46,'create_user','web','2026-08-30 10:10:56','2026-08-30 10:10:56'),(47,'update_user','web','2026-08-30 10:10:56','2026-08-30 10:10:56'),(48,'delete_user','web','2026-08-30 10:10:56','2026-08-30 10:10:56');
